import re
from datetime import datetime

_START_TIME_PATTERN = re.compile(r"^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$")
_DATETIME_FORMAT = "%Y-%m-%d %H:%M"


def schedule_meeting(start_time, duration_minutes):
    if not isinstance(start_time, str):
        raise TypeError("start_time must be a string")

    if not _START_TIME_PATTERN.fullmatch(start_time):
        raise ValueError('start_time must match the exact format "YYYY-MM-DD HH:MM"')

    try:
        datetime.strptime(start_time, _DATETIME_FORMAT)
    except ValueError as exc:
        raise ValueError(f"start_time is not a valid calendar date/time: {start_time!r}") from exc

    if isinstance(duration_minutes, bool) or not isinstance(duration_minutes, int):
        raise TypeError("duration_minutes must be an integer")

    if duration_minutes < 15 or duration_minutes > 480:
        raise ValueError("duration_minutes must be between 15 and 480 inclusive")

    return f"Meeting scheduled: {start_time} for {duration_minutes} minutes"
```

