import re
from datetime import datetime

_START_TIME_RE = re.compile(r"^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}$")


def schedule_meeting(start_time, duration_minutes):
    if not isinstance(start_time, str):
        raise TypeError("start_time must be a string")
    if isinstance(duration_minutes, bool) or not isinstance(duration_minutes, int):
        raise TypeError("duration_minutes must be an integer")

    if len(start_time) != 16 or not _START_TIME_RE.match(start_time):
        raise ValueError(
            'start_time must be a string in the exact format "YYYY-MM-DD HH:MM"'
        )

    try:
        datetime.strptime(start_time, "%Y-%m-%d %H:%M")
    except ValueError as exc:
        raise ValueError(
            f"start_time is not a valid calendar date/time: {start_time!r}"
        ) from exc

    if not (15 <= duration_minutes <= 480):
        raise ValueError(
            f"duration_minutes must be an integer between 15 and 480 inclusive, "
            f"got {duration_minutes!r}"
        )

    return f"Meeting scheduled: {start_time} for {duration_minutes} minutes"
