def find_median_sorted_arrays(nums1, nums2):
    if not isinstance(nums1, list) or not isinstance(nums2, list):
        raise TypeError("Inputs must be lists")

    merged = nums1 + nums2
    try:
        merged.sort()
    except Exception as e:
        raise ValueError("Lists must contain comparable elements") from e

    total = len(merged)
    if total == 0:
        raise ValueError("Cannot find the median of empty lists")

    if total % 2 == 1:
        return float(merged[total // 2])
    else:
        mid1 = merged[total // 2 - 1]
        mid2 = merged[total // 2]
        return (mid1 + mid2) / 2.0
