def find_median_sorted_arrays(nums1, nums2):
    # Validate inputs
    if not isinstance(nums1, list) or not isinstance(nums2, list):
        raise TypeError("Both inputs must be lists.")

    for lst, name in [(nums1, "nums1"), (nums2, "nums2")]:
        for item in lst:
            if not isinstance(item, (int, float)):
                raise ValueError(f"All elements in {name} must be numbers.")

    # Check if both lists are empty
    if not nums1 and not nums2:
        raise ValueError("At least one list must contain elements.")

    # Combine and sort (or merge since they are already sorted)
    combined = sorted(nums1 + nums2)
    total_len = len(combined)

    if total_len % 2 == 1:
        return float(combined[total_len // 2])
    else:
        mid1 = combined[(total_len // 2) - 1]
        mid2 = combined[total_len // 2]
        return (mid1 + mid2) / 2.0
```

