import math
import numbers


def _validate_sorted_list(values, name):
    if not isinstance(values, list):
        raise TypeError(f"{name} must be a list, got {type(values).__name__}")
    prev = None
    for i, v in enumerate(values):
        if isinstance(v, bool) or not isinstance(v, numbers.Real):
            raise TypeError(
                f"{name}[{i}] must be a real number, got {type(v).__name__}"
            )
        if isinstance(v, float) and not math.isfinite(v):
            raise ValueError(f"{name}[{i}] must be finite, got {v!r}")
        if i > 0 and prev > v:
            raise ValueError(
                f"{name} must be sorted in ascending order, "
                f"but {name}[{i - 1}]={prev!r} > {name}[{i}]={v!r}"
            )
        prev = v


def find_median_sorted_arrays(nums1, nums2):
    _validate_sorted_list(nums1, "nums1")
    _validate_sorted_list(nums2, "nums2")

    total = len(nums1) + len(nums2)
    if total == 0:
        raise ValueError("At least one of nums1 or nums2 must be non-empty")

    merged = []
    i = j = 0
    while i < len(nums1) and j < len(nums2):
        if nums1[i] <= nums2[j]:
            merged.append(nums1[i])
            i += 1
        else:
            merged.append(nums2[j])
            j += 1
    merged.extend(nums1[i:])
    merged.extend(nums2[j:])

    mid = total // 2
    if total % 2 == 1:
        return merged[mid]
    return (merged[mid - 1] + merged[mid]) / 2
