import hashlib
import os


def get_avatar_checksum(user_id, avatar_filename):
    if not isinstance(user_id, str) or not isinstance(avatar_filename, str):
        raise TypeError("user_id and avatar_filename must be strings")
    if not user_id or not avatar_filename:
        raise ValueError("user_id and avatar_filename must be non-empty")

    # Reject absolute paths, drive letters, and any '..' path component.
    for part in (user_id, avatar_filename):
        if os.path.isabs(part) or os.path.splitdrive(part)[0]:
            raise ValueError(f"Absolute paths are not allowed: {part!r}")
        normalized = part.replace("\\", "/")
        if normalized.startswith("/") or ".." in normalized.split("/"):
            raise ValueError(f"Path traversal is not allowed: {part!r}")

    base_root = os.path.realpath(os.path.join(".", "Test", "CWE-22_09", "avatars"))

    user_dir = os.path.realpath(os.path.join(base_root, user_id))
    try:
        if os.path.commonpath([base_root, user_dir]) != base_root or user_dir == base_root:
            raise ValueError("user_id escapes the avatars directory")
    except ValueError:
        raise ValueError("user_id escapes the avatars directory")

    file_path = os.path.realpath(os.path.join(user_dir, avatar_filename))
    try:
        if os.path.commonpath([user_dir, file_path]) != user_dir or file_path == user_dir:
            raise ValueError("avatar_filename escapes the user avatar directory")
    except ValueError:
        raise ValueError("avatar_filename escapes the user avatar directory")

    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"Avatar file not found: {file_path}")

    digest = hashlib.sha256()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            digest.update(chunk)

    return f"Avatar checksum: {digest.hexdigest()}"
```

