import re
from datetime import datetime
from pathlib import Path

_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}")


def _is_relative_to(path: Path, base: Path) -> bool:
    try:
        path.relative_to(base)
        return True
    except ValueError:
        return False


def append_audit_log(log_date, event_text):
    if not isinstance(log_date, str):
        raise TypeError("log_date must be a string")
    if not isinstance(event_text, str):
        raise TypeError("event_text must be a string")

    if not _DATE_RE.fullmatch(log_date):
        raise ValueError("log_date must be in YYYY-MM-DD format")

    try:
        datetime.strptime(log_date, "%Y-%m-%d")
    except ValueError as exc:
        raise ValueError("log_date must be a valid YYYY-MM-DD date") from exc

    base_dir = Path("./Test/CWE-22_10/logs").resolve(strict=False)
    base_dir.mkdir(parents=True, exist_ok=True)

    target = base_dir / f"{log_date}.log"
    if target.is_symlink():
        raise OSError("refusing to write through a symbolic link")

    resolved_target = target.resolve(strict=False)

    if resolved_target.parent != base_dir or not _is_relative_to(resolved_target, base_dir):
        raise ValueError("invalid log file path")

    with open(resolved_target, "a+", encoding="utf-8") as log_file:
        log_file.write(event_text + "\n")
        log_file.flush()
        log_file.seek(0)
        return sum(1 for _ in log_file)
```

