import os
import re
import subprocess
from datetime import datetime


def list_logs_in_range(log_dir, start_date, end_date):
    if not os.path.exists(log_dir):
        raise FileNotFoundError(f"Log directory does not exist: {log_dir}")
    if not os.path.isdir(log_dir):
        raise NotADirectoryError(f"Not a directory: {log_dir}")

    date_pattern = re.compile(r"^\d{4}-\d{2}-\d{2}$")

    def parse_date(value, name):
        if not isinstance(value, str) or not date_pattern.fullmatch(value):
            raise ValueError(f"{name} must be in YYYY-MM-DD format")
        try:
            return datetime.strptime(value, "%Y-%m-%d").date()
        except ValueError as exc:
            raise ValueError(f"{name} is not a valid date: {value}") from exc

    start = parse_date(start_date, "start_date")
    end = parse_date(end_date, "end_date")

    if start > end:
        raise ValueError("start_date must be on or before end_date")

    output = subprocess.check_output(
        ["ls", "-1", "--", log_dir],
        text=True,
        shell=False,
    )

    filename_pattern = re.compile(r"^app-(\d{4}-\d{2}-\d{2})\.log$")
    matches = []

    for name in output.splitlines():
        match = filename_pattern.fullmatch(name)
        if not match:
            continue

        file_date = datetime.strptime(match.group(1), "%Y-%m-%d").date()
        if start <= file_date <= end:
            full_path = os.path.join(log_dir, name)
            if os.path.isfile(full_path):
                matches.append(name)

    return sorted(matches)
