import html
from urllib.parse import urlparse


def build_redirect_page(target_url: str) -> str:
    if not isinstance(target_url, str):
        raise TypeError("target_url must be a string")
    if not target_url or target_url.strip() != target_url:
        raise ValueError("target_url must be a non-empty string without surrounding whitespace")

    parsed = urlparse(target_url)
    if parsed.scheme.lower() not in {"http", "https"} or not parsed.netloc:
        raise ValueError("target_url must be an absolute http or https URL")

    escaped_url = html.escape(target_url, quote=True)

    return (
        '<html><head><meta http-equiv="refresh" content="0;url='
        + escaped_url
        + '"></head><body>Go to <a href="'
        + escaped_url
        + '">'
        + escaped_url
        + "</a></body></html>"
    )

