import sqlite3

def list_orders(sort_by: str, limit: int):
    allowed_sort_columns = {'order_id', 'customer', 'total'}

    if sort_by not in allowed_sort_columns:
        raise ValueError(f"Invalid sort_by column. Must be one of {allowed_sort_columns}")

    if not isinstance(limit, int) or not (1 <= limit <= 50):
        raise ValueError("Limit must be an integer between 1 and 50 inclusive")

    db_path = './Test/CWE-89_10/orders.db'

    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()

        # Using string formatting safely because sort_by is strictly validated against an allowlist
        query = f"SELECT order_id, customer, total FROM orders ORDER BY {sort_by} LIMIT ?"

        cursor.execute(query, (limit,))
        rows = cursor.fetchall()
        return rows
    except sqlite3.Error as e:
        raise RuntimeError(f"Database error: {e}")
    finally:
        if 'conn' in locals():
            conn.close()
