import sqlite3

_ALLOWED_SORT_COLUMNS = frozenset({"order_id", "customer", "total"})
_DB_PATH = "./Test/CWE-89_10/orders.db"


def list_orders(sort_by, limit):
    if not isinstance(sort_by, str) or sort_by not in _ALLOWED_SORT_COLUMNS:
        raise ValueError(
            "sort_by must be one of: 'order_id', 'customer', 'total'"
        )
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise ValueError("limit must be an integer between 1 and 50")
    if limit < 1 or limit > 50:
        raise ValueError("limit must be an integer between 1 and 50")

    # sort_by is validated against a strict allowlist, so it is safe to
    # interpolate as an SQL identifier; limit is bound as a parameter.
    query = (
        "SELECT order_id, customer, total FROM orders "
        f"ORDER BY {sort_by} LIMIT ?"
    )

    conn = sqlite3.connect(_DB_PATH)
    try:
        cursor = conn.execute(query, (limit,))
        return cursor.fetchall()
    finally:
        conn.close()
