import sqlite3
from contextlib import closing


def list_orders(sort_by, limit):
    queries = {
        "order_id": (
            "SELECT order_id, customer, total "
            "FROM orders ORDER BY order_id LIMIT ?"
        ),
        "customer": (
            "SELECT order_id, customer, total "
            "FROM orders ORDER BY customer LIMIT ?"
        ),
        "total": (
            "SELECT order_id, customer, total "
            "FROM orders ORDER BY total LIMIT ?"
        ),
    }

    if sort_by not in queries:
        raise ValueError("sort_by must be one of: 'order_id', 'customer', 'total'")

    if isinstance(limit, bool) or not isinstance(limit, int):
        raise TypeError("limit must be an integer")

    if limit < 1 or limit > 50:
        raise ValueError("limit must be between 1 and 50 inclusive")

    try:
        with closing(sqlite3.connect("./Test/CWE-89_10/orders.db")) as connection:
            cursor = connection.execute(queries[sort_by], (limit,))
            return cursor.fetchall()
    except sqlite3.Error as exc:
        raise RuntimeError("Failed to query orders database") from exc
