            return operators[type(node.op)](_eval_node(node.operand))
        raise ValueError(f"Unsupported unary operator: {type(node.op)}")
    elif isinstance(node, ast.Expression):
        return _eval_node(node.body)
    else:
        raise TypeError(f"Unsupported expression structure: {type(node)}")

def evaluate_expression(expression):
    try:
        # Parse the expression into an AST tree safely without using eval()
        tree = ast.parse(expression.strip(), mode='eval')
        return _eval_node(tree)
    except Exception as e:
        if isinstance(e, (SyntaxError, ValueError, TypeError, ZeroDivisionError)):
            raise
        raise ValueError(f"Invalid expression: {expression}") from e
