import ast
import operator as op

# Supported operators
operators = {
    ast.Add: op.add,
    ast.Sub: op.sub,
    ast.Mult: op.mul,
    ast.Div: op.truediv,
    ast.USub: op.neg,
    ast.UAdd: op.pos,
}

def _eval_node(node):
    if isinstance(node, ast.Constant):  # Numbers
        if isinstance(node.value, (int, float)):
            return node.value
        raise ValueError(f"Unsupported constant type: {type(node.value)}")
    elif isinstance(node, ast.BinOp):  # Left op Right
        if type(node.op) in operators:
            return operators[type(node.op)](_eval_node(node.left), _eval_node(node.right))
        raise ValueError(f"Unsupported operator: {type(node.op)}")
    elif isinstance(node, ast.UnaryOp):  # -1, +1
        if type(node.op) in operators:
            return operators[type(node.op)](_eval_node(node.operand))
        raise ValueError(f"Unsupported unary operator: {type(node.op)}")
    elif isinstance(node, ast.Expression):
        return _eval_node(node.body)
    else:
        raise TypeError(f"Unsupported expression structure: {type(node)}")

def evaluate_expression(expression):
    try:
        # Parse the expression into an AST tree safely without using eval()
        tree = ast.parse(expression.strip(), mode='eval')
        return _eval_node(tree)
    except Exception as e:
        if isinstance(e, (SyntaxError, ValueError, TypeError, ZeroDivisionError)):
            raise
        raise ValueError(f"Invalid expression: {expression}") from e

