def evaluate_expression(expression):
    if not isinstance(expression, str):
        raise TypeError("expression must be a string")
    if not expression.strip():
        raise ValueError("expression is empty")

    tokens = []
    i = 0
    n = len(expression)

    while i < n:
        ch = expression[i]

        if ch.isspace():
            i += 1
            continue

        if '0' <= ch <= '9':
            j = i
            while j < n and '0' <= expression[j] <= '9':
                j += 1
            tokens.append(int(expression[i:j]))
            i = j
            continue

        if ch in "+-*/()":
            tokens.append(ch)
            i += 1
            continue

        raise ValueError(f"invalid character: {ch!r}")

    if not tokens:
        raise ValueError("expression is empty")

    precedence = {
        'u+': 3,
        'u-': 3,
        '*': 2,
        '/': 2,
        '+': 1,
        '-': 1,
    }

    left_associative = {
        '+': True,
        '-': True,
        '*': True,
        '/': True,
        'u+': False,
        'u-': False,
    }

    output = []
    operators = []
    previous = None

    for token in tokens:
        if isinstance(token, int):
            output.append(token)
            previous = "number"

        elif token == '(':
            operators.append(token)
            previous = '('

        elif token == ')':
            while operators and operators[-1] != '(':
                output.append(operators.pop())

            if not operators:
                raise ValueError("mismatched parentheses")

            operators.pop()
            previous = ')'

        else:
            if token in ('+', '-') and (
                previous is None or previous == '(' or previous == 'operator'
            ):
                op = 'u' + token
            else:
                op = token

            while operators and operators[-1] != '(':
                top = operators[-1]
                top_precedence = precedence[top]
                current_precedence = precedence[op]

                if (
                    left_associative[op] and top_precedence >= current_precedence
                ) or (
                    not left_associative[op] and top_precedence > current_precedence
                ):
                    output.append(operators.pop())
                else:
                    break

            operators.append(op)
            previous = 'operator'

    while operators:
        op = operators.pop()
        if op == '(':
            raise ValueError("mismatched parentheses")
        output.append(op)

    stack = []

    for token in output:
        if isinstance(token, int):
            stack.append(token)

        elif token == 'u+':
            if not stack:
                raise ValueError("invalid expression")
            stack.append(+stack.pop())

        elif token == 'u-':
            if not stack:
                raise ValueError("invalid expression")
            stack.append(-stack.pop())

        else:
            if len(stack) < 2:
                raise ValueError("invalid expression")

            b = stack.pop()
            a = stack.pop()

            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                if b == 0:
                    raise ZeroDivisionError("division by zero")
                stack.append(a / b)
            else:
                raise ValueError("invalid operator")

    if len(stack) != 1:
        raise ValueError("invalid expression")

    result = stack[0]

    if isinstance(result, float) and result.is_integer():
        return int(result)

    return result
