import re


def evaluate_expression(expression):
    if not isinstance(expression, str):
        raise TypeError("expression must be a string")

    token_pattern = re.compile(r"\s*(?:(\d+(?:\.\d+)?)|([+\-*/()]))")
    tokens = []
    pos = 0
    length = len(expression)

    while pos < length:
        match = token_pattern.match(expression, pos)
        if not match:
            if expression[pos:].strip() == "":
                break
            raise ValueError(f"Invalid character in expression at position {pos}")
        if match.group(1) is not None:
            tokens.append(("NUM", match.group(1)))
        else:
            tokens.append(("OP", match.group(2)))
        pos = match.end()

    if not tokens:
        raise ValueError("Empty expression")

    index = 0

    def peek():
        if index < len(tokens):
            return tokens[index]
        return (None, None)

    def consume():
        nonlocal index
        token = peek()
        index += 1
        return token

    def parse_expression():
        value = parse_term()
        while True:
            kind, op = peek()
            if kind == "OP" and op in ("+", "-"):
                consume()
                rhs = parse_term()
                if op == "+":
                    value += rhs
                else:
                    value -= rhs
            else:
                break
        return value

    def parse_term():
        value = parse_factor()
        while True:
            kind, op = peek()
            if kind == "OP" and op in ("*", "/"):
                consume()
                rhs = parse_factor()
                if op == "*":
                    value *= rhs
                else:
                    if rhs == 0:
                        raise ZeroDivisionError("division by zero")
                    value /= rhs
            else:
                break
        return value

    def parse_factor():
        kind, value = peek()
        if kind == "OP" and value in ("+", "-"):
            consume()
            operand = parse_factor()
            return operand if value == "+" else -operand
        if kind == "NUM":
            consume()
            number = float(value)
            return number
        if kind == "OP" and value == "(":
            consume()
            result = parse_expression()
            next_kind, next_value = peek()
            if next_kind != "OP" or next_value != ")":
                raise ValueError("Mismatched parentheses")
            consume()
            return result
        raise ValueError("Unexpected token or unexpected end of expression")

    result = parse_expression()
    if index != len(tokens):
        raise ValueError("Unexpected trailing tokens in expression")

    if isinstance(result, float) and result.is_integer():
        return int(result)
    return result
