import ast
import operator

# Mapping of AST operator nodes to actual functions
OPERATORS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.Pow: operator.pow,
    ast.Mod: operator.mod,
}

def execute_command(command: str):
    """
    Evaluate a simple arithmetic expression safely.

    Parameters
    ----------
    command : str
        A string containing digits, whitespace, '+', '-', '*', '/', and parentheses.

    Returns
    -------
    float
        The numeric result of the expression.

    Raises
    ------
    ValueError
        If the expression contains unsupported syntax or operations.
    ZeroDivisionError
        If division by zero occurs.
    """
    try:
        # Parse the expression into an AST
        tree = ast.parse(command, mode='eval')
    except SyntaxError as exc:
        raise ValueError(f"Invalid syntax: {exc}") from exc

    def _eval(node):
        if isinstance(node, ast.Expression):
            return _eval(node.body)
        elif isinstance(node, ast.BinOp):
            left = _eval(node.left)
            right = _eval(node.right)
            op_type = type(node.op)
            if op_type not in OPERATORS:
                raise ValueError(f"Unsupported operator: {op_type.__name__}")
            return OPERATORS[op_type](left, right)
        elif isinstance(node, ast.UnaryOp):
            if isinstance(node.op, ast.UAdd):
                return +_eval(node.operand)
            elif isinstance(node.op, ast.USub):
                return -_eval(node.operand)
            else:
                raise ValueError(f"Unsupported unary operator: {type(node.op).__name__}")
        elif isinstance(node, ast.Num):  # For Python <3.8
            return node.n
        elif isinstance(node, ast.Constant):  # For Python >=3.8
            if isinstance(node.value, (int, float)):
                return node.value
            else:
                raise ValueError(f"Unsupported constant type: {type(node.value).__name__}")
        elif isinstance(node, ast.Paren):  # Not needed; parentheses are handled by AST
            return _eval(node.value)
        else:
            raise ValueError(f"Unsupported expression element: {type(node).__name__}")

    return _eval(tree)
