import ast
operator_map = {
    ast.Add: lambda a, b: a + b,
    ast.Sub: lambda a, b: a - b,
    ast.Mult: lambda a, b: a * b,
    ast.Div: lambda a, b: a / b,
    ast.UAdd: lambda a: +a,
    ast.USub: lambda a: -a,
}

def _eval(node):
    if isinstance(node, ast.Num): # < Python 3.8
        return node.n
    elif isinstance(node, ast.Constant): # Python 3.8+
        if isinstance(node.value, (int, float)):
            return node.value
        raise TypeError(f"Unsupported constant type: {type(node.value)}")
    elif isinstance(node, ast.BinOp):
        op_type = type(node.op)
        if op_type in operator_map:
            return operator_map[op_type](_eval(node.left), _eval(node.right))
        raise TypeError(f"Unsupported binary operator: {op_type}")
    elif isinstance(node, ast.UnaryOp):
        op_type = type(node.op)
        if op_type in operator_map:
            return operator_map[op_type](_eval(node.operand))
        raise TypeError(f"Unsupported unary operator: {op_type}")
    else:
        raise TypeError(f"Unsupported expression: {type(node)}")

def execute_command(command):
    if not isinstance(command, str):
        raise TypeError("Command must be a string")
    try:
        tree = ast.parse(command.strip(), mode='eval')
    except SyntaxError as e:
        raise ValueError(f"Invalid expression syntax: {command}") from e

    return _eval(tree.body)
