import ast

def execute_command(command: str) -> float:
    """
    Safely evaluates an arithmetic expression and returns its numeric result.
    Raises an exception if the expression is invalid or contains unsafe operations.
    """
    if not isinstance(command, str) or not command.strip():
        raise ValueError("Command must be a non-empty string.")

    # Allowed nodes in the AST for safe arithmetic evaluation
    allowed_nodes = (
        ast.Expression,
        ast.BinOp,
        ast.UnaryOp,
        ast.Add,
        ast.Sub,
        ast.Mult,
        ast.Div,
        ast.UAdd,
        ast.USub,
        ast.Constant,
        ast.Num,  # For older Python versions compatibility
    )

    def _eval(node):
        if isinstance(node, ast.Expression):
            return _eval(node.body)
        elif isinstance(node, ast.Constant):
            if isinstance(node.value, (int, float)):
                return node.value
            raise TypeError(f"Unsupported constant type: {type(node.value)}")
        elif isinstance(node, ast.Num):  # Python < 3.8 fallback
            return node.n
        elif isinstance(node, ast.BinOp):
            op_type = type(node.op)
            if op_type not in _OPERATORS:
                raise TypeError(f"Unsupported operator: {op_type}")
            return _OPERATORS[op_type](_eval(node.left), _eval(node.right))
        elif isinstance(node, ast.UnaryOp):
            op_type = type(node.op)
            if op_type not in _UNARY_OPERATORS:
                raise TypeError(f"Unsupported unary operator: {op_type}")
            return _UNARY_OPERATORS[op_type](_eval(node.operand))
        else:
            raise TypeError(f"Unsupported expression structure: {type(node)}")

    import operator
    _OPERATORS = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
    }
    _UNARY_OPERATORS = {
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
    }

    try:
        parsed_ast = ast.parse(command.strip(), mode='eval')

        # Verify all nodes are allowed
        for n in ast.walk(parsed_ast):
            if not isinstance(n, allowed_nodes):
                raise TypeError(f"Disallowed construct in expression: {type(n)}")

        return _eval(parsed_ast)
    except Exception as e:
        raise ValueError(f"Failed to evaluate expression securely: {e}") from e
