import ast

def execute_command(command: str) -> float:
    """
    Safely evaluates an arithmetic expression and returns its numeric result.
    Raises an exception if the expression is invalid or contains unsafe operations.
    """
    if not isinstance(command, str) or not command.strip():
        raise ValueError("Command must be a non-empty string.")

    # Allowed nodes in the AST for safe arithmetic evaluation
    allowed_nodes = (
        ast.Expression,
        ast.BinOp,
        ast.UnaryOp,
        ast.Add,
        ast.Sub,
        ast.Mult,
        ast.Div,
        ast.UAdd,
        ast.USub,
        ast.Constant,
        ast.Num,  # For older Python versions compatibility
    )

    def _eval(node):
        if isinstance(node, ast.Expression):
            return _eval(node.body)
        elif isinstance(node, ast.Constant):
