    _UNARY_OPERATORS = {
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
    }

    try:
        parsed_ast = ast.parse(command.strip(), mode='eval')

        # Verify all nodes are allowed
        for n in ast.walk(parsed_ast):
            if not isinstance(n, allowed_nodes):
