class _ExpressionParser:
    def __init__(self, expression: str):
        self.expression = expression
        self.position = 0
        self.length = len(expression)

    def parse(self):
        value = self._parse_expression()
        self._skip_whitespace()
        if self.position != self.length:
            raise ValueError(
                f"Unexpected character at position {self.position}: "
                f"{self.expression[self.position]!r}"
            )
        return value

    def _skip_whitespace(self) -> None:
        while self.position < self.length and self.expression[self.position].isspace():
            self.position += 1

    def _peek(self):
        if self.position >= self.length:
            return None
        return self.expression[self.position]

    def _consume(self, expected=None):
        self._skip_whitespace()
        if self.position >= self.length:
            raise ValueError("Unexpected end of expression")

        char = self.expression[self.position]
        if expected is not None and char != expected:
            raise ValueError(
                f"Expected {expected!r} at position {self.position}, got {char!r}"
            )

        self.position += 1
        return char

    def _parse_expression(self):
        value = self._parse_term()

        while True:
            self._skip_whitespace()
            char = self._peek()

            if char == "+":
                self._consume("+")
                value += self._parse_term()
            elif char == "-":
                self._consume("-")
                value -= self._parse_term()
            else:
                return value

    def _parse_term(self):
        value = self._parse_factor()

        while True:
            self._skip_whitespace()
            char = self._peek()

            if char == "*":
                self._consume("*")
                value *= self._parse_factor()
            elif char == "/":
                self._consume("/")
                divisor = self._parse_factor()
                if divisor == 0:
                    raise ZeroDivisionError("division by zero")
                value /= divisor
            else:
                return value

    def _parse_factor(self):
        self._skip_whitespace()
        char = self._peek()

        if char is None:
            raise ValueError("Unexpected end of expression")

        if char == "+":
            self._consume("+")
            return self._parse_factor()

        if char == "-":
            self._consume("-")
            return -self._parse_factor()

        if char == "(":
            self._consume("(")
            value = self._parse_expression()
            self._consume(")")
            return value

        if char.isdigit():
            start = self.position
            while self.position < self.length and self.expression[self.position].isdigit():
                self.position += 1
            return int(self.expression[start:self.position])

        raise ValueError(f"Unexpected character at position {self.position}: {char!r}")


def execute_command(command):
    if not isinstance(command, str):
        raise TypeError("command must be a string")

    return _ExpressionParser(command).parse()
