class _ArithmeticParser:
    def __init__(self, expression: str):
        self.expression = expression
        self.pos = 0
        self.length = len(expression)

    def parse(self):
        self._skip_whitespace()
        if self.pos >= self.length:
            raise ValueError("Empty arithmetic expression")

        value = self._parse_expression()
        self._skip_whitespace()

        if self.pos != self.length:
            raise ValueError(
                f"Unexpected character {self.expression[self.pos]!r} at position {self.pos}"
            )

        return value

    def _skip_whitespace(self):
        while self.pos < self.length and self.expression[self.pos].isspace():
            self.pos += 1

    def _peek(self):
        if self.pos >= self.length:
            return ""
        return self.expression[self.pos]

    def _parse_expression(self):
        value = self._parse_term()

        while True:
            self._skip_whitespace()
            op = self._peek()

            if op not in ("+", "-"):
                return value

            self.pos += 1
            rhs = self._parse_term()

            if op == "+":
                value = value + rhs
            else:
                value = value - rhs

    def _parse_term(self):
        value = self._parse_factor()

        while True:
            self._skip_whitespace()
            op = self._peek()

            if op not in ("*", "/"):
                return value

            self.pos += 1
            rhs = self._parse_factor()

            if op == "*":
                value = value * rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                value = value / rhs

    def _parse_factor(self):
        self._skip_whitespace()
        ch = self._peek()

        if ch == "":
            raise ValueError("Unexpected end of expression")

        if ch == "+":
            self.pos += 1
            return +self._parse_factor()

        if ch == "-":
            self.pos += 1
            return -self._parse_factor()

        if ch == "(":
            self.pos += 1
            value = self._parse_expression()
            self._skip_whitespace()

            if self._peek() != ")":
                raise ValueError(f"Expected ')' at position {self.pos}")

            self.pos += 1
            return value

        return self._parse_number()

    def _parse_number(self):
        self._skip_whitespace()
        start = self.pos
        has_digit = False

        while self.pos < self.length and self.expression[self.pos].isdigit():
            has_digit = True
            self.pos += 1

        if self.pos < self.length and self.expression[self.pos] == ".":
            self.pos += 1
            while self.pos < self.length and self.expression[self.pos].isdigit():
                has_digit = True
                self.pos += 1

        if not has_digit:
            found = self.expression[self.pos] if self.pos < self.length else "end of expression"
            raise ValueError(f"Expected number at position {start}, found {found!r}")

        token = self.expression[start:self.pos]

        if "." in token:
            return float(token)

        return int(token)


def execute_command(command):
    if not isinstance(command, str):
        raise TypeError("command must be a string")

    return _ArithmeticParser(command).parse()
