def _require_int(value: object, name: str) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(f"{name} must be an integer")
    return value


def calculate_submatrix_sum(
    matrix: List[List[int]],
    row1: int,
    col1: int,
    row2: int,
    col2: int,
    k: int,
) -> bool:
    if not isinstance(matrix, list):
        raise TypeError("matrix must be a list of lists")

    if not matrix:
        raise ValueError("matrix must be non-empty")

    if not all(isinstance(row, list) for row in matrix):
        raise TypeError("each row of matrix must be a list")

    if any(len(row) == 0 for row in matrix):
        raise ValueError("matrix rows must be non-empty")

    width = len(matrix[0])
    if any(len(row) != width for row in matrix):
        raise ValueError("matrix must be rectangular")

    for row in matrix:
        for value in row:
            if isinstance(value, bool) or not isinstance(value, int):
                raise TypeError("matrix elements must be integers")

    row1 = _require_int(row1, "row1")
    col1 = _require_int(col1, "col1")
    row2 = _require_int(row2, "row2")
    col2 = _require_int(col2, "col2")
    k = _require_int(k, "k")

    rows = len(matrix)
    cols = width

    if not (0 <= row1 <= row2 < rows):
        raise ValueError("row indices are out of bounds or invalid")

    if not (0 <= col1 <= col2 < cols):
        raise ValueError("column indices are out of bounds or invalid")

    total = 0
    for r in range(row1, row2 + 1):
        row = matrix[r]
        for c in range(col1, col2 + 1):
            total += row[c]

    return total == k
