from typing import List


def calculate_submatrix_sum(
    matrix: List[List[int]],
    row1: int,
    col1: int,
    row2: int,
    col2: int,
    k: int,
) -> bool:
    if not isinstance(matrix, list) or not matrix:
        raise ValueError("matrix must be a non-empty list of lists")

    if not all(isinstance(row, list) for row in matrix):
        raise ValueError("matrix must be a list of lists")

    num_rows = len(matrix)
    num_cols = len(matrix[0])

    if num_cols == 0:
        raise ValueError("matrix rows must not be empty")

    for row in matrix:
        if len(row) != num_cols:
            raise ValueError("matrix must be rectangular")

    indices = (row1, col1, row2, col2)
    if not all(isinstance(index, int) and not isinstance(index, bool) for index in indices):
        raise TypeError("row and column indices must be integers")

    if row1 < 0 or col1 < 0 or row2 < 0 or col2 < 0:
        raise ValueError("row and column indices must be non-negative")

    if row1 >= num_rows or row2 >= num_rows:
        raise ValueError("row index is out of bounds")

    if col1 >= num_cols or col2 >= num_cols:
        raise ValueError("column index is out of bounds")

    if row1 > row2 or col1 > col2:
        raise ValueError("top-left corner must not be below or to the right of bottom-right corner")

    total = 0
    for r in range(row1, row2 + 1):
        row = matrix[r]
        for c in range(col1, col2 + 1):
            total += row[c]

    return total == k
```

