def reserve_tickets(age, num_tickets):
    if not isinstance(age, (int, float)) or not isinstance(num_tickets, int):
        raise TypeError("Age and number of tickets must be numeric types.")
    if age < 0 or num_tickets <= 0:
        raise ValueError("Age must be non-negative and number of tickets must be positive.")

    if age < 12:
        price_per_ticket = 20
    elif 12 <= age < 65:
        price_per_ticket = 50
    else:
        price_per_ticket = 40

    subtotal = price_per_ticket * num_tickets

    if num_tickets >= 10:
        discount = 0.10
    elif 5 <= num_tickets <= 9:
        discount = 0.05
    else:
        discount = 0.0

    total_cost = subtotal * (1 - discount)
    return round(total_cost)
