def reserve_tickets(age, num_tickets):
    if isinstance(age, bool) or not isinstance(age, int):
        raise TypeError("age must be an integer")
    if isinstance(num_tickets, bool) or not isinstance(num_tickets, int):
        raise TypeError("num_tickets must be an integer")
    if age < 0:
        raise ValueError("age must be non-negative")
    if num_tickets <= 0:
        raise ValueError("num_tickets must be positive")

    if age < 12:
        ticket_price = 20
    elif age < 65:
