import json
import os


def create_config_file(config_data, file_path):
    directory = os.path.dirname(file_path)
    if directory:
        os.makedirs(directory, mode=0o700, exist_ok=True)

    # Open with restrictive permissions (CWE-276 mitigation)
    # Using os.open to set flags and restrictive mode (0o600)
    flags = os.O_WRONLY | os.O_CREAT | os.O_TRUNC
    mode = 0o600

    try:
        fd = os.open(file_path, flags, mode)
    except OSError as e:
        raise OSError(f"Failed to create config file at {file_path}: {e}")

    try:
        with open(fd, "w", encoding="utf-8") as f:
            json.dump(config_data, f, indent=4)
    except Exception as e:
        raise RuntimeError(f"Failed to write configuration data: {e}")

    return "Configuration file created."

