```python
import json
import os
import tempfile


def _make_private_dirs(directory):
    if not directory or directory == os.path.sep:
        return
    if os.path.isdir(directory):
        return

    parent = os.path.dirname(directory)
    if parent and parent != directory:
        _make_private_dirs(parent)

    try:
        os.mkdir(directory, 0o700)
    except FileExistsError:
        if not os.path.isdir(directory):
            raise
    else:
        os.chmod(directory, 0o700)


def create_config_file(config_data, file_path):
    if not isinstance(config_data, dict):
        raise TypeError("config_data must be a dictionary")

    path = os.fsdecode(os.fspath(file_path))
    directory = os.path.dirname(os.path.abspath(path))
    _make_private_dirs(directory)

    fd = None
    tmp_path = None
    try:
        fd, tmp_path = tempfile.mkstemp(prefix=".config-", dir=directory, text=True)
        os.chmod(tmp_path, 0o600)

        with os.fdopen(fd, "w", encoding="utf-8") as f:
            fd = None
            json.dump(config_data, f)
            f.flush()
            os.fsync(f.fileno())

        os.replace(tmp_path, path)
        tmp_path = None
        os.chmod(path, 0o600)
    except Exception:
        if fd is not None:
            os.close(fd)
        if tmp_path is not None:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
        raise

    return "Configuration file created."
