```python
import os

_MAX_FIRMWARE_SIZE = 256 * 1024
_MAGIC_HEADER = b"FWR1"


def save_firmware_blob(blob_name, blob_bytes, upload_dir):
    if not isinstance(blob_name, str) or not blob_name.strip():
        raise ValueError("blob_name must be a non-empty string")
    if "\x00" in blob_name:
        raise ValueError("blob_name must not contain null bytes")

    if not isinstance(blob_bytes, (bytes, bytearray)):
        raise TypeError("blob_bytes must be bytes or bytearray")

    blob_bytes = bytes(blob_bytes)
    if len(blob_bytes) > _MAX_FIRMWARE_SIZE:
        raise ValueError("firmware blob exceeds the 256KB limit")
    if len(blob_bytes) < len(_MAGIC_HEADER) or blob_bytes[:4] != _MAGIC_HEADER:
        raise ValueError("firmware blob is missing the required 'FWR1' magic header")

    # Normalize separators and strip any directory components to prevent traversal.
    candidate = blob_name.replace("\\", "/")
    safe_name = os.path.basename(candidate)
    if not safe_name or safe_name in (".", ".."):
        raise ValueError("invalid blob_name")

    root, ext = os.path.splitext(safe_name)
    if not root or ext.lower() != ".bin":
        raise ValueError("blob_name must end with a single '.bin' extension")

    upload_root = os.path.realpath(upload_dir)
    os.makedirs(upload_root, exist_ok=True)

    target_path = os.path.realpath(os.path.join(upload_root, safe_name))
    try:
        if os.path.commonpath([upload_root, target_path]) != upload_root:
            raise ValueError("resolved path escapes the upload directory")
    except ValueError as exc:
        raise ValueError("resolved path escapes the upload directory") from exc

    if target_path == upload_root:
        raise ValueError("invalid target path")

    flags = os.O_CREAT | os.O_WRONLY | os.O_TRUNC
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    if hasattr(os, "O_BINARY"):
        flags |= os.O_BINARY

    fd = os.open(target_path, flags, 0o600)
    try:
        with os.fdopen(fd, "wb") as fh:
            fh.write(blob_bytes)
    except Exception:
        raise

    return f"Firmware stored at {target_path}"
