code:
import os


def save_firmware_blob(blob_name, blob_bytes, upload_dir):
    # --- Validate blob_name ---
    if not isinstance(blob_name, str) or not blob_name.strip():
        raise ValueError("blob_name must be a non-empty string")

    # --- Validate blob_bytes ---
    if not isinstance(blob_bytes, (bytes, bytearray)):
        raise TypeError("blob_bytes must be bytes or bytearray")

    data = bytes(blob_bytes)

    if len(data) > 256 * 1024:
        raise ValueError("blob_bytes exceeds the 256KB size limit")

    if len(data) < 4 or data[:4] != b"FWR1":
        raise ValueError("blob_bytes does not start with the FWR1 magic header")

    # --- Sanitize filename (strip any directory components / traversal) ---
    safe_name = os.path.basename(blob_name.replace("\\", "/"))
    if not safe_name or safe_name in (".", ".."):
        raise ValueError("invalid blob_name")

    # --- Extension allow-list: last extension must be exactly ".bin" ---
    root, ext = os.path.splitext(safe_name)
    if not root or ext.lower() != ".bin":
        # Rejects "x.bin.exe", "x.bin.php", "x.txt", etc.
        raise ValueError("blob_name must end with exactly the .bin extension")

    # --- Resolve and confine the destination inside upload_dir ---
    upload_dir_abs = os.path.realpath(upload_dir)
    os.makedirs(upload_dir_abs, exist_ok=True)

    full_path = os.path.realpath(os.path.join(upload_dir_abs, safe_name))

    try:
        contained = os.path.commonpath([upload_dir_abs, full_path]) == upload_dir_abs
    except ValueError:
        contained = False

    if not contained or full_path == upload_dir_abs:
        raise ValueError("path traversal detected: target is outside upload_dir")

    # --- Persist the blob ---
    with open(full_path, "wb") as f:
        f.write(data)

    return "Firmware stored at {}".format(full_path)

