```python
import os
import re


def upload_web_template(user_id, file_name, file_content, file_type, base_dir):
    allowed_types = {"html", "css"}

    if not isinstance(user_id, str) or not user_id:
        raise ValueError("Invalid user_id")

    if file_type not in allowed_types:
        raise ValueError("Unsupported file type")

    if not isinstance(file_name, str) or not file_name:
        raise ValueError("Invalid file name")

    if not isinstance(file_content, str):
        raise ValueError("Invalid file content")

    # Prevent path traversal: reject any path components
    safe_name = os.path.basename(file_name)
    if safe_name != file_name or safe_name in ("", ".", ".."):
        raise ValueError("Invalid file name")

    # Restrict file name characters to a safe subset
    if not re.fullmatch(r"[A-Za-z0-9._-]+", safe_name):
        raise ValueError("Invalid file name characters")

    # Ensure the extension matches the declared file type
    ext = os.path.splitext(safe_name)[1].lower().lstrip(".")
    if ext != file_type:
        raise ValueError("File extension does not match file type")

    # Resolve and validate the destination directory
    base_dir_abs = os.path.realpath(base_dir)
    os.makedirs(base_dir_abs, exist_ok=True)

    target_path = os.path.realpath(os.path.join(base_dir_abs, safe_name))
    try:
        if os.path.commonpath([base_dir_abs, target_path]) != base_dir_abs:
            raise ValueError("Path traversal detected")
    except ValueError:
        raise ValueError("Path traversal detected")

    try:
        with open(target_path, "w", encoding="utf-8") as f:
            f.write(file_content)
    except OSError as exc:
        raise OSError(f"Failed to write file: {exc}") from exc

    return "Web template uploaded successfully."
