def _sanitize_user_id(user_id):
    if not isinstance(user_id, str):
        raise TypeError("user_id must be a string")
    user_id = user_id.strip()
    if not user_id:
        raise ValueError("user_id must not be empty")
    # Normalize and reject control characters / path separators.
    user_id = unicodedata.normalize("NFKC", user_id)
    if any(ch in user_id for ch in ("/", "\\", "\x00", "..")):
        raise ValueError("user_id contains invalid characters")
    if not re.match(r"^[A-Za-z0-9_-]{1,64}$", user_id):
        raise ValueError("user_id contains unsupported characters")
    return user_id


def _sanitize_file_name(file_name, file_type):
    if not isinstance(file_name, str):
        raise TypeError("file_name must be a string")
    # Strip any directory component provided by the caller.
    file_name = os.path.basename(file_name.strip())
    if not file_name:
        raise ValueError("file_name must not be empty")
    if "\x00" in file_name:
        raise ValueError("file_name contains a null byte")
    file_name = unicodedata.normalize("NFKC", file_name)
    if not _SAFE_NAME_RE.match(file_name):
        raise ValueError("file_name contains unsupported characters")

    expected_ext = ALLOWED_TYPES[file_type]
    name_root, ext = os.path.splitext(file_name)
    if not name_root:
        raise ValueError("file_name must have a valid stem")
    if ext.lower() != expected_ext:
        raise ValueError(
            "file extension %r does not match file_type %r" % (ext, file_type)
        )
    return file_name


def _validate_content(file_content):
    if isinstance(file_content, bytes):
        data = file_content
    elif isinstance(file_content, str):
        data = file_content.encode("utf-8")
    else:
        raise TypeError("file_content must be str or bytes")
    if len(data) > MAX_FILE_SIZE:
        raise ValueError(
            "file_content exceeds maximum allowed size of %d bytes" % MAX_FILE_SIZE
        )
    return data


def upload_web_template(user_id, file_name, file_content, file_type, base_dir):
    """Persist an uploaded web template file inside ``base_dir``.

    The upload is constrained by an allow-list of file types/extensions,
    a sanitised filename, a maximum size limit, and a check that the final
    destination path stays inside ``base_dir``.
    """
    # Validate the declared type against the allow-list first.
    if not isinstance(file_type, str):
        raise TypeError("file_type must be a string")
    file_type = file_type.strip().lower()
    if file_type not in ALLOWED_TYPES:
        raise ValueError(
            "unsupported file_type %r; allowed: %s"
            % (file_type, sorted(ALLOWED_TYPES))
        )

    safe_user = _sanitize_user_id(user_id)
    safe_name = _sanitize_file_name(file_name, file_type)
    data = _validate_content(file_content)

    if not isinstance(base_dir, (str, os.PathLike)):
        raise TypeError("base_dir must be a path-like object")
    base_dir = os.path.abspath(os.fspath(base_dir))

    # Build the per-user directory and ensure the final path stays inside it.
    user_dir = os.path.abspath(os.path.join(base_dir, safe_user))
    target_path = os.path.abspath(os.path.join(user_dir, safe_name))

    if os.path.commonpath([base_dir, target_path]) != base_dir:
        raise ValueError("resolved path escapes base_dir")
    if os.path.commonpath([user_dir, target_path]) != user_dir:
        raise ValueError("resolved path escapes user directory")

    try:
        os.makedirs(user_dir, exist_ok=True)
    except OSError as exc:
        raise OSError("could not create upload directory: %s" % exc) from exc

    if os.path.isdir(target_path):
        raise IsADirectoryError("target path is a directory: %s" % target_path)

    try:
        # O_NOFOLLOW where available to avoid symlink attacks.
        flags = os.O_WRONLY | os.O_CREAT | os.O_TRUNC
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW
        fd = os.open(target_path, flags, 0o640)
        try:
            with os.fdopen(fd, "wb") as handle:
                handle.write(data)
        except Exception:
            # fdopen takes ownership of fd; only close if fdopen failed.
            try:
                os.close(fd)
            except OSError:
                pass
            raise
    except OSError as exc:
        raise OSError("failed to write template file: %s" % exc) from exc

    return "Web template uploaded successfully."

