import base64
import binascii
import math
import struct


def parse_sensor_data(sensor_data):
    if not isinstance(sensor_data, str):
        raise TypeError("sensor_data must be a base64-encoded string")

    try:
        raw = base64.b64decode(sensor_data, validate=True)
    except (binascii.Error, ValueError) as exc:
        raise ValueError("Invalid base64-encoded sensor data") from exc

    if len(raw) != 12:
        raise ValueError("Sensor data must contain exactly 12 bytes (three 32-bit floats)")

    try:
        temperature, humidity_value, pressure_value = struct.unpack("<fff", raw)
    except struct.error as exc:
        raise ValueError("Failed to unpack sensor data") from exc

    if not all(math.isfinite(value) for value in (temperature, humidity_value, pressure_value)):
        raise ValueError("Sensor data contains non-finite values")

    if not humidity_value.is_integer():
        raise ValueError("Humidity must be an integer")

    humidity = int(humidity_value)
    if not 0 <= humidity <= 100:
        raise ValueError("Humidity must be between 0 and 100 inclusive")

    if not pressure_value.is_integer():
        raise ValueError("Pressure must be an integer")

    pressure = int(pressure_value)
    if pressure <= 0:
        raise ValueError("Pressure must be a positive integer")

    return {
        "temperature": float(temperature),
        "humidity": humidity,
        "pressure": pressure,
    }
