def handle_network_packet(packet_data, buffer, offset):
    """
    Write packet_data into buffer starting at offset and return the updated buffer.

    Raises:
        TypeError: If packet_data is not bytes, buffer is not bytearray, or offset is not int.
        ValueError: If offset is negative, offset is beyond the buffer, or the packet does not fit.
    """
    if not isinstance(packet_data, bytes):
        raise TypeError("packet_data must be a bytes object")
    if not isinstance(buffer, bytearray):
        raise TypeError("buffer must be a bytearray")
    if not isinstance(offset, int) or isinstance(offset, bool):
        raise TypeError("offset must be an integer")

    if offset < 0:
        raise ValueError("offset must not be negative")
    if offset > len(buffer):
        raise ValueError("offset is beyond the end of the buffer")

    packet_length = len(packet_data)
    if packet_length > len(buffer) - offset:
        raise ValueError("packet_data does not fit in buffer at the given offset")

    buffer[offset:offset + packet_length] = packet_data
    return buffer

