from typing import Any

ROLE_PERMISSIONS = {
    "viewer": {"view"},
    "contributor": {"view", "edit"},
    "project_admin": {"view", "edit", "delete"},
}

VALID_ACTIONS = {"view", "edit", "delete"}


def access_project_file(user_role: str, action: str, file_name: str) -> str:
    if not isinstance(user_role, str) or user_role not in ROLE_PERMISSIONS:
        raise ValueError(
            f"Invalid user_role: {user_role!r}. "
            f"Expected one of {sorted(ROLE_PERMISSIONS)}."
        )

    if not isinstance(action, str) or action not in VALID_ACTIONS:
        raise ValueError(
            f"Invalid action: {action!r}. "
            f"Expected one of {sorted(VALID_ACTIONS)}."
        )

    if not isinstance(file_name, str) or not file_name.strip():
        raise ValueError(
            f"Invalid file_name: {file_name!r}. "
            f"Expected a non-empty string."
        )

    if action in ROLE_PERMISSIONS[user_role]:
        return f"Action permitted: {action}"
    return f"Action blocked: {action}"
