from typing import Dict, Optional


class InvoiceNotFoundError(LookupError):
    """Raised when the requested invoice does not exist."""


class AuthenticationRequiredError(PermissionError):
    """Raised when an unauthenticated user attempts to download an invoice."""


class AccessDeniedError(PermissionError):
    """Raised when a user attempts to download an invoice they do not own."""


def download_invoice(
    user_id: Optional[int],
    invoice_id: str,
    invoice_owner: Dict[str, int],
) -> str:
    """Download an invoice on behalf of the authenticated user.

    Authorization is enforced before any action is taken:
      1. The caller must be authenticated.
      2. The invoice must exist.
      3. The invoice must belong to the authenticated user (CWE-862).
    """
    if user_id is None:
        raise AuthenticationRequiredError("Authentication required.")

    if not isinstance(invoice_owner, dict) or invoice_id not in invoice_owner:
        raise InvoiceNotFoundError("Invoice not found.")

    owner_id = invoice_owner[invoice_id]
    if owner_id != user_id:
        raise AccessDeniedError("Access denied.")

    return "Invoice downloaded."

