import re
import xml.etree.ElementTree as ET

try:  # Prefer defusedxml when it is available (hardened expat parser).
    from defusedxml import ElementTree as _DefusedET
    from defusedxml.common import DefusedXmlException as _DefusedXmlException
except ImportError:  # pragma: no cover - fallback path
    _DefusedET = None
    _DefusedXmlException = None


_MAX_XML_BYTES = 10 * 1024 * 1024  # 10 MiB cap to avoid resource exhaustion
_DANGEROUS_BYTES = re.compile(rb"<!\s*(DOCTYPE|ENTITY)", re.IGNORECASE)
_DANGEROUS_TEXT = re.compile(r"<!\s*(DOCTYPE|ENTITY)", re.IGNORECASE)


class UnsafeXMLError(ValueError):
    """Raised when the input XML contains potentially dangerous constructs."""


def parse_xml(xml_string):
    '''
    Parse xml_string and return the root element of the XML document
    '''
    if isinstance(xml_string, str):
        text = xml_string
        data = text.encode("utf-8", errors="strict")
    elif isinstance(xml_string, (bytes, bytearray)):
        data = bytes(xml_string)
        text = None
    else:
        raise TypeError("xml_string must be str or bytes")

    if not data.strip():
        raise ValueError("xml_string is empty")

    if len(data) > _MAX_XML_BYTES:
        raise ValueError("xml_string exceeds the maximum allowed size")

    # Reject DTD / entity declarations outright: this blocks XXE (external
    # entity expansion, file disclosure, SSRF) and "billion laughs" attacks.
    pattern = _DANGEROUS_TEXT if text is not None else _DANGEROUS_BYTES
    subject = text if text is not None else data
    if pattern.search(subject):
        raise UnsafeXMLError("DTD and entity declarations are not allowed")

    if _DefusedET is not None:
        try:
            return _DefusedET.fromstring(text if text is not None else data)
        except _DefusedXmlException as exc:
            raise UnsafeXMLError("unsafe XML rejected: %s" % exc) from exc

    # ElementTree's default parser does not fetch external entities, and the
    # DOCTYPE/ENTITY check above prevents internal entity expansion abuse.
    return ET.fromstring(text if text is not None else data)

