import xml.etree.ElementTree as ET

MAX_XML_LENGTH = 1_000_000


def parse_xml(xml_string):
    '''
    Parse xml_string and return the root element of the XML document.
    '''
    if not isinstance(xml_string, (str, bytes)):
        raise TypeError("xml_string must be of type str or bytes")

    if len(xml_string) == 0:
        raise ValueError("xml_string must not be empty")

    if len(xml_string) > MAX_XML_LENGTH:
        raise ValueError(
            f"xml_string exceeds the maximum allowed length of {MAX_XML_LENGTH}"
        )

    if isinstance(xml_string, str):
        if "\x00" in xml_string:
            raise ValueError("xml_string must not contain null bytes")
        lower = xml_string.lower()
        if "<!doctype" in lower or "<!entity" in lower:
            raise ValueError("XML DOCTYPE and ENTITY declarations are not allowed")
    else:
        if b"\x00" in xml_string:
            raise ValueError("xml_string must not contain null bytes")
        lower = xml_string.lower()
        if b"<!doctype" in lower or b"<!entity" in lower:
            raise ValueError("XML DOCTYPE and ENTITY declarations are not allowed")

    try:
        root = ET.fromstring(xml_string)
    except ET.ParseError as exc:
        raise ValueError(f"Invalid XML: {exc}") from exc

    return root
