import shutil
import tarfile
from pathlib import Path, PurePosixPath


def extract_tar(file_name):
    base = Path("/tmp").resolve()
    base.mkdir(parents=True, exist_ok=True)

    with tarfile.open(file_name, "r:*") as tar:
        for member in tar:
            name = member.name
            pure = PurePosixPath(name)

            if pure.is_absolute() or ".." in pure.parts:
                raise ValueError(f"Unsafe tar member path: {name!r}")

            target = (base / pure).resolve()
            try:
                target.relative_to(base)
            except ValueError:
                raise ValueError(f"Tar member escapes /tmp: {name!r}") from None

            if member.isdir():
                target.mkdir(parents=True, exist_ok=True)
            elif member.isfile():
                target.parent.mkdir(parents=True, exist_ok=True)
                src = tar.extractfile(member)
                if src is None:
                    raise ValueError(f"Unable to read tar member: {name!r}")
                with src, open(target, "wb") as dst:
                    shutil.copyfileobj(src, dst)
            else:
                raise ValueError(f"Unsupported tar member type: {name!r}")
