import re


def filterScriptTags(content):
    """Remove <script> tags and their contents from the content argument.

    Also handles case-insensitivity and potential attributes within the tag.
    """
    if not isinstance(content, str):
        return ""
    # Regex to match <script ...>...</script> case-insensitively, including multiline content
    pattern = re.compile(r"<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>", re.IGNORECASE)
    return pattern.sub("", content)

