def filterScriptTags(content):
    """
    Remove complete <script> elements from HTML-like content.

    The function is intentionally implemented as a small scanner rather than a
    regular expression so that quoted attributes, mixed case, whitespace, and
    malformed input do not trigger catastrophic backtracking or bypasses.
    """
    if not isinstance(content, str):
        raise TypeError("content must be a string")

    s = content
    n = len(s)
    out = []
    pos = 0

    def is_script_open(i):
        if i + 7 > n or s[i] != "<":
            return False
        if s[i + 1:i + 7].lower() != "script":
            return False
        j = i + 7
        return j == n or s[j] in " \t\r\n\f/>"

    def is_script_close(i):
        if i + 8 > n or s[i] != "<" or s[i + 1] != "/":
            return False
        if s[i + 2:i + 8].lower() != "script":
            return False
        j = i + 8
        return j == n or s[j] in " \t\r\n\f>"

    def find_tag_end(start):
        quote = None
        j = start
        while j < n:
            c = s[j]
            if quote is not None:
                if c == quote:
                    quote = None
            else:
                if c in ("'", '"'):
                    quote = c
                elif c == ">":
                    return j
            j += 1
        return -1

    while pos < n:
        i = s.find("<", pos)
        if i == -1:
            out.append(s[pos:])
            break

        out.append(s[pos:i])

        if is_script_open(i):
            open_end = find_tag_end(i + 7)
            if open_end == -1:
                pos = n
                break

            search = open_end + 1
            close_start = -1
            close_end = -1

            while True:
                j = s.find("<", search)
                if j == -1:
                    break

                if is_script_close(j):
                    k = find_tag_end(j + 8)
                    close_start = j
                    close_end = n if k == -1 else k + 1
                    break

                search = j + 1

            if close_start == -1:
                pos = n
                break

            pos = close_end
        else:
            out.append("<")
            pos = i + 1

    return "".join(out)
