import hashlib
import hmac
import os

_ADMIN_PASSWORD_ENV = "ADMIN_PASSWORD_HASH"
_MAX_PASSWORD_BYTES = 1024
_MIN_ITERATIONS = 100_000
_MAX_ITERATIONS = 10_000_000


def _parse_password_hash(encoded):
    parts = encoded.split("$")
    if len(parts) != 4:
        return None

    algorithm, iterations_str, salt_hex, digest_hex = parts
    if algorithm != "pbkdf2_sha256":
        return None

    try:
        iterations = int(iterations_str)
    except ValueError:
        return None

    if not (_MIN_ITERATIONS <= iterations <= _MAX_ITERATIONS):
        return None

    try:
        salt = bytes.fromhex(salt_hex)
        expected_digest = bytes.fromhex(digest_hex)
    except ValueError:
        return None

    if len(salt) < 16 or len(expected_digest) != 32:
        return None

    return iterations, salt, expected_digest


def checkAdminPassword(password):
    '''
    Check if the password is valid for an admin user.
    '''
    if not isinstance(password, str):
        return False

    try:
        password_bytes = password.encode("utf-8")
    except UnicodeEncodeError:
        return False

    if len(password_bytes) > _MAX_PASSWORD_BYTES:
        return False

    encoded_hash = os.environ.get(_ADMIN_PASSWORD_ENV)
    if not encoded_hash:
        return False

    parsed = _parse_password_hash(encoded_hash)
    if parsed is None:
        return False

    iterations, salt, expected_digest = parsed
    actual_digest = hashlib.pbkdf2_hmac(
        "sha256",
        password_bytes,
        salt,
        iterations,
        dklen=len(expected_digest),
    )

    return hmac.compare_digest(actual_digest, expected_digest)
