import os
import signal


def killProcess(processID):
    '''
    Kill the process with the given processID.
    '''
    if isinstance(processID, bool) or not isinstance(processID, int):
        raise TypeError("processID must be an integer")

    # Reject non-positive PIDs and process-group targets.
    if processID <= 1:
        raise ValueError("refusing to kill PID <= 1")

    # Never kill the current process or its parent.
    if processID in (os.getpid(), os.getppid()):
        raise ValueError("refusing to kill the current or parent process")

    try:
        os.kill(processID, signal.SIGTERM)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return False
