import os
import signal


def killProcess(processID):
    '''
    Kill the process with the given processID.

    Security (CWE-283): the caller must own the target process before it is
    signalled. Ownership is verified against the effective user ID. The
    caller's own process and PID 1 are never signalled.
    '''
    try:
        pid = int(processID)
    except (TypeError, ValueError):
        raise ValueError("processID must be an integer")

    if pid <= 0:
        raise ValueError("processID must be a positive integer")

    if pid == 1:
        raise PermissionError("refusing to signal PID 1")

    if pid == os.getpid():
        raise PermissionError("refusing to signal the current process")

    proc_path = "/proc/{}".format(pid)
    try:
        proc_stat = os.stat(proc_path)
    except FileNotFoundError:
        raise ProcessLookupError("no such process: {}".format(pid))
    except OSError as exc:
        raise PermissionError(
            "unable to verify ownership of process {}: {}".format(pid, exc)
        )

    if proc_stat.st_uid != os.geteuid():
        raise PermissionError(
            "caller does not own process {}".format(pid)
        )

    try:
        os.kill(pid, signal.SIGTERM)
    except ProcessLookupError:
        raise ProcessLookupError("no such process: {}".format(pid))
    except PermissionError:
        raise PermissionError(
            "insufficient permission to signal process {}".format(pid)
        )

    return True
