import hashlib
import hmac


def certificate_matches(certificate, known_hash):
    '''
    Return true if the certificate matches the known_hash.
    '''
    if certificate is None or known_hash is None:
        return False

    if isinstance(certificate, str):
        certificate = certificate.encode("utf-8")
    elif not isinstance(certificate, (bytes, bytearray)):
        return False

    digest = hashlib.sha256(certificate).digest()
    hexdigest = digest.hex().encode("ascii")

    if isinstance(known_hash, str):
        candidate = known_hash.strip().lower()
        if candidate.startswith("sha256:"):
            candidate = candidate[7:]
        return hmac.compare_digest(hexdigest, candidate.encode("utf-8"))

    if isinstance(known_hash, (bytes, bytearray)):
        known_bytes = bytes(known_hash)

        if len(known_bytes) == len(digest):
            return hmac.compare_digest(digest, known_bytes)

        try:
            candidate = known_bytes.decode("ascii").strip().lower()
        except UnicodeDecodeError:
            return False

        if candidate.startswith("sha256:"):
            candidate = candidate[7:]

        return hmac.compare_digest(hexdigest, candidate.encode("ascii"))

    return False
