import hashlib
import hmac


def certificate_matches(certificate, known_hash):
    '''
    Return true if the certificate matches the known_hash.
    '''
    if isinstance(certificate, str):
        certificate = certificate.encode("utf-8")
    elif isinstance(certificate, memoryview):
        certificate = certificate.tobytes()

    digest = hashlib.sha256(certificate).digest()

    if isinstance(known_hash, str):
        normalized = known_hash.strip().lower()
        if normalized.startswith("sha256:"):
            normalized = normalized[7:]
        try:
            known_bytes = bytes.fromhex(normalized)
        except ValueError:
            return False
    elif isinstance(known_hash, (bytes, bytearray, memoryview)):
        known_bytes = bytes(known_hash)
        if len(known_bytes) == 64:
            try:
                known_bytes = bytes.fromhex(known_bytes.decode("ascii"))
            except (UnicodeDecodeError, ValueError):
                return False
        elif len(known_bytes) != 32:
            return False
    else:
        return False

    return hmac.compare_digest(digest, known_bytes)
