def _secret_to_jwk(secret):
    """Build an octet JWK from a shared secret for HMAC verification."""
    k = base64.urlsafe_b64encode(secret.encode("utf-8")).rstrip(b"=").decode("ascii")
    return jwk.JWK(kty="oct", k=k)


def verifyJWTToken(jwt_token, key=None, allowed_algs=_ALLOWED_ALGS):
    '''
    Verify the JWT Token and return it.
    '''
    if not allowed_algs:
        raise ValueError("allowed_algs must be a non-empty collection of algorithms")

    if key is None:
        secret = os.environ.get("JWT_SECRET")
        if not secret:
            raise RuntimeError("JWT_SECRET environment variable is not set")
        key = _secret_to_jwk(secret)
    elif isinstance(key, str):
        key = _secret_to_jwk(key)

    try:
        # Signature verification is always performed; algorithm is restricted.
        header, claims = jwt.verify_jwt(
            jwt_token,
            key,
            allowed_algs=list(allowed_algs),
        )
    except Exception as exc:
        raise ValueError("Invalid JWT token") from exc

    return claims

