import os

def readFile(fileName):
    """
    Safely reads the content of a file.

    The function attempts to open the file directly, avoiding a separate
    existence check to prevent a race condition. If the file cannot be
    opened, an IOError is raised.
    """
    try:
        with open(fileName, "r", encoding="utf-8") as fh:
            return fh.read()
    except FileNotFoundError as e:
        raise FileNotFoundError(f"File not found: {fileName}") from e
    except IOError as e:
        raise IOError(f"Error reading file {fileName}") from e

