import os


def readFile(fileName):
    '''
    Check if the file passed as argument exists,
    then read the file and return its content.
    '''
    if not isinstance(fileName, str) or not fileName:
        raise ValueError("Invalid file name")

    base_dir = os.path.realpath(os.getcwd())
    requested_path = os.path.realpath(os.path.join(base_dir, fileName))

    try:
        if os.path.commonpath([base_dir, requested_path]) != base_dir:
            raise PermissionError("Access outside the allowed directory is not permitted")
    except ValueError:
        raise PermissionError("Access outside the allowed directory is not permitted")

    if not os.path.exists(requested_path):
        raise FileNotFoundError(f"File not found: {fileName}")

    if not os.path.isfile(requested_path):
        raise IsADirectoryError(f"Not a regular file: {fileName}")

    with open(requested_path, "r", encoding="utf-8", errors="replace") as file_handle:
        return file_handle.read()
