import os


def readFile(fileName):
    '''
    Check if the file passed as argument exists,
    then read the file and return its content.

    Security note (CWE-367): Avoid check-then-use on files; open once and
    operate on the handle, or use atomic operations.
    '''
    try:
        # Open once and operate on the handle to avoid a TOCTOU race.
        with open(fileName, "r", encoding="utf-8") as handle:
            return handle.read()
    except FileNotFoundError:
        return None
    except (IsADirectoryError, PermissionError, OSError):
        return None

