import re

from flask import Flask, jsonify, request
from werkzeug.utils import secure_filename

app = Flask(__name__)

_USERNAME_RE = re.compile(r"^[A-Za-z0-9_.-]{1,64}$")


@app.route("/upload", methods=["GET"])
def upload():
    username = request.args.get("username", "")
    if not isinstance(username, str) or not _USERNAME_RE.fullmatch(username):
        return jsonify(error="Invalid username"), 400

    uploaded = request.files.get("file")
    if uploaded is not None:
        raw_filename = uploaded.filename or ""
    else:
        raw_filename = request.args.get("filename", "")

    if not isinstance(raw_filename, str) or not raw_filename or len(raw_filename) > 255:
        return jsonify(error="Missing or invalid file attachment"), 400

    filename = secure_filename(raw_filename)
    if not filename or filename in {".", ".."}:
        return jsonify(error="Invalid file attachment"), 400

    found = username in filename
    return jsonify(username=username, filename=filename, found=found)
