import os
from django.http import FileResponse, HttpResponseBadRequest, HttpResponseForbidden
from django.contrib.auth.decorators import login_required
from django.conf import settings
from pathlib import Path


@login_required
def getResource(request):
    """
    Get username and date from the request and send the corresponding file to the user.

    Parameters
    ----------
    request : HttpRequest
        The incoming request containing 'username' and 'date' parameters.

    Returns
    -------
    FileResponse
        The requested file if it exists and the user is authorized.
    HttpResponseBadRequest
        If required parameters are missing or invalid.
    HttpResponseForbidden
        If the user is not authorized to access the requested file.
    """

    # Retrieve parameters from GET or POST
    username = request.GET.get("username") or request.POST.get("username")
    date_str = request.GET.get("date") or request.POST.get("date")

    if not username or not date_str:
        return HttpResponseBadRequest("Missing 'username' or 'date' parameter.")

    # Ensure the username matches the logged-in user for safety
    if username != request.user.username:
        return HttpResponseForbidden("You are not authorized to access this resource.")

    # Construct safe file path
    # Assuming the files are stored under MEDIA_ROOT/<username>/<date>/*.ext
    base_dir = Path(settings.MEDIA_ROOT) / username / date_str
    if not base_dir.is_dir():
        return HttpResponseBadRequest("Requested resource does not exist.")

    # Return the first file found in the directory
    # (Adjust logic if you need to select a specific file)
    try:
        file_path = next(base_dir.iterdir())
    except StopIteration:
        return HttpResponseBadRequest("No files found for the requested date.")

    # Security: ensure the file path is within the expected directory
    if not str(file_path.resolve()).startswith(str(base_dir.resolve())):
        return HttpResponseForbidden("Invalid file path detected.")

    # Serve the file
    return FileResponse(open(file_path, "rb"), as_attachment=True, filename=file_path.name)

