import os
import mimetypes

from django.conf import settings
from django.http import HttpResponse, FileResponse


def _safe_join(base, *paths):
    base = os.path.abspath(base)
    final_path = os.path.abspath(os.path.join(base, *paths))
    if os.path.commonpath([base, final_path]) != base:
        raise ValueError("Invalid path")
    return final_path


def getResource(request):
    '''
    Get username and date from the request, then
    send the file to the user by creating path by the username and date.
    '''
    username = request.GET.get("username") or request.POST.get("username")
    date = request.GET.get("date") or request.POST.get("date")

    if not username or not date:
        return HttpResponse("Missing username or date", status=400)

    base_dir = getattr(settings, "RESOURCE_ROOT", getattr(settings, "MEDIA_ROOT", ""))
    if not base_dir:
        return HttpResponse("Resource root is not configured", status=500)

    try:
        file_path = _safe_join(base_dir, username, date)
    except ValueError:
        return HttpResponse("Invalid path", status=400)

    if not os.path.isfile(file_path):
        return HttpResponse("File not found", status=404)

    content_type, _ = mimetypes.guess_type(file_path)
    return FileResponse(
        open(file_path, "rb"),
