```python
import os
import re
from datetime import datetime

from django.http import HttpResponse, FileResponse, Http404
from django.conf import settings

# Strict allowlists: no path separators, no "..", no null bytes.
USERNAME_RE = re.compile(r"^[A-Za-z0-9_-]{1,64}$")
DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def getResource(request):
    '''
    Get username and date from the request, then
    send the file to the user by creating path by the username and date.
    '''
    username = request.GET.get("username", "")
    date = request.GET.get("date", "")

    # Validate inputs against strict patterns to prevent path traversal.
    if not USERNAME_RE.fullmatch(username):
        return HttpResponse("Invalid username", status=400)
    if not DATE_RE.fullmatch(date):
        return HttpResponse("Invalid date", status=400)

    # Ensure the date is a real calendar date.
    try:
        datetime.strptime(date, "%Y-%m-%d")
    except ValueError:
        return HttpResponse("Invalid date", status=400)

    # Build the path from a fixed base directory and validated components.
    base_dir = os.path.realpath(os.path.join(settings.MEDIA_ROOT, "resources"))
    file_path = os.path.realpath(os.path.join(base_dir, username, f"{date}.txt"))

    # Defense in depth: confirm the resolved path is still inside base_dir.
    if os.path.commonpath([base_dir, file_path]) != base_dir:
        return HttpResponse("Forbidden", status=403)

    if not os.path.isfile(file_path):
        raise Http404("Resource not found")

    # Stream the file back to the user.
    return FileResponse(open(file_path, "rb"), as_attachment=True)
```

