import os
import re
from datetime import datetime

from django.conf import settings
from django.http import FileResponse, Http404, HttpResponseBadRequest, HttpResponseForbidden

_SAFE_COMPONENT = re.compile(r"^[A-Za-z0-9_.-]+$")


def getResource(request):
    username = request.GET.get("username")
    date = request.GET.get("date")

    if not username or not date:
        return HttpResponseBadRequest("Missing username or date")

    if not _SAFE_COMPONENT.match(username) or username in {".", ".."}:
        return HttpResponseBadRequest("Invalid username")

    if not _SAFE_COMPONENT.match(date) or date in {".", ".."}:
        return HttpResponseBadRequest("Invalid date")

    try:
        datetime.strptime(date, "%Y-%m-%d")
    except ValueError:
        return HttpResponseBadRequest("Invalid date")

    if not request.user.is_authenticated:
        return HttpResponseForbidden("Not authorized")

    if request.user.username != username and not request.user.is_staff:
        return HttpResponseForbidden("Not authorized")

    base_dir = os.path.realpath(getattr(settings, "RESOURCE_ROOT", settings.MEDIA_ROOT))
    file_path = os.path.realpath(os.path.join(base_dir, username, date))

    try:
        if os.path.commonpath([base_dir, file_path]) != base_dir:
            return HttpResponseForbidden("Invalid path")
    except ValueError:
        return HttpResponseForbidden("Invalid path")

    if not os.path.isfile(file_path):
        raise Http404("Resource not found")

    return FileResponse(open(file_path, "rb"), as_attachment=True)
