import hmac

HAS_ADMIN_ACCESS = False

ADMIN_USERNAME = "admin"
ADMIN_PASSWORD = "admin"


def _read_request_param(request, key):
    """Read a parameter from common request-like objects or a plain dict."""
    for attr in ("GET", "POST", "data", "query_params", "form"):
        container = getattr(request, attr, None)
        if container is not None:
            try:
                if key in container:
                    return container[key]
            except TypeError:
                pass

    if isinstance(request, dict):
        return request.get(key)

    return None


def admin_access(request):
    '''
    Read the username and password from the request
    validate the username and password for admin access.
    Flag that the user has admin access.
    '''
    global HAS_ADMIN_ACCESS

    username = _read_request_param(request, "username")
    password = _read_request_param(request, "password")

    if username is None or password is None:
        HAS_ADMIN_ACCESS = False
        return False

    if not isinstance(username, str):
        username = str(username)
    if not isinstance(password, str):
        password = str(password)

    is_valid = hmac.compare_digest(username, ADMIN_USERNAME) and hmac.compare_digest(
        password, ADMIN_PASSWORD
    )

    HAS_ADMIN_ACCESS = is_valid
    return is_valid
