import hashlib
import hmac
import os

HAS_ADMIN_ACCESS = False


def _extract_credentials(request):
    """Safely extract username/password from common request objects."""
    data = None

    for attr in ("form", "POST"):
        candidate = getattr(request, attr, None)
        if candidate:
            data = candidate
            break

    if data is None:
        json_attr = getattr(request, "json", None)
        if isinstance(json_attr, dict):
            data = json_attr
        else:
            get_json = getattr(request, "get_json", None)
            if callable(get_json):
                try:
                    data = get_json(silent=True)
                except Exception:
                    data = None

    if not isinstance(data, dict):
        return None, None

    return data.get("username"), data.get("password")


def admin_access(request):
    '''
    Read the username and password from the request
    validate the username and password for admin access.
    Flag that the user has admin access.
    '''
    global HAS_ADMIN_ACCESS
    HAS_ADMIN_ACCESS = False

    username, password = _extract_credentials(request)

    if not isinstance(username, str) or not isinstance(password, str):
        return False

    # Bound input sizes to avoid resource-exhaustion attacks.
    if len(username) > 256 or len(password) > 1024:
        return False

    expected_username = os.environ.get("ADMIN_USERNAME", "")
    expected_password_hash = os.environ.get("ADMIN_PASSWORD_HASH", "")

    if not expected_username or not expected_password_hash:
        return False

    provided_password_hash = hashlib.sha256(password.encode("utf-8")).hexdigest()

    username_ok = hmac.compare_digest(
        username.encode("utf-8"), expected_username.encode("utf-8")
    )
    password_ok = hmac.compare_digest(provided_password_hash, expected_password_hash)

    if username_ok and password_ok:
        HAS_ADMIN_ACCESS = True
        return True

    return False
