import pickle
from typing import Any


class SafeUnpickler(pickle.Unpickler):
    """
    A minimal safe unpickler that disallows the creation of arbitrary
    Python objects. Only basic built-in types are allowed.
    """

    def find_class(self, module: str, name: str) -> Any:
        # Only allow built-in types from the 'builtins' module
        if module != "builtins":
            raise pickle.UnpicklingError(
                f"Disallowed module: {module!r}. Only built-in types are allowed."
            )
        if name not in {"list", "dict", "set", "tuple", "str", "int", "float", "bool", "bytes"}:
            raise pickle.UnpicklingError(
                f"Disallowed type: {module}.{name!r}. Only basic types are allowed."
            )
        return getattr(__builtins__, name)


def getPickleData(pickled: bytes) -> Any:
    """
    Return deserialized data from a pickled byte string in a secure way.

    Parameters
    ----------
    pickled : bytes
        The pickled data to deserialize.

    Returns
    -------
    Any
        The deserialized Python object.

    Raises
    ------
    pickle.UnpicklingError
        If the pickle data contains disallowed objects or is malformed.
    """
    if not isinstance(pickled, (bytes, bytearray)):
        raise TypeError("pickled must be a bytes-like object")

    try:
        return SafeUnpickler(pickled).load()
    except (pickle.UnpicklingError, AttributeError, EOFError) as exc:
        raise pickle.UnpicklingError("Failed to safely unpickle data") from exc

