import io
import pickle


# Only these builtin callables/types are permitted during unpickling.
# Everything else (os.system, subprocess.Popen, eval, exec, etc.) is rejected,
# mitigating CWE-502 (Deserialization of Untrusted Data).
_SAFE_BUILTINS = frozenset({
    "dict", "list", "tuple", "set", "frozenset",
    "str", "bytes", "bytearray", "int", "float", "complex", "bool",
    "object", "NoneType", "slice", "range",
})


class _RestrictedUnpickler(pickle.Unpickler):
    """Unpickler that refuses to resolve any non-whitelisted global."""

    def find_class(self, module, name):
        if module == "builtins" and name in _SAFE_BUILTINS:
            return super().find_class(module, name)
        if module == "collections" and name in {"OrderedDict", "defaultdict"}:
            return super().find_class(module, name)
        raise pickle.UnpicklingError(
            f"Refusing to deserialize disallowed global: {module}.{name}"
        )

    def persistent_load(self, pid):
        raise pickle.UnpicklingError("Persistent IDs are not allowed")


def getPickleData(pickled):
    '''
    Return deserialized data.

    Deserialization is performed with a restricted unpickler that only
    permits a small whitelist of inert builtin types, so loading a malicious
    payload cannot execute arbitrary code (CWE-502). For fully untrusted
    input, prefer a non-executable format such as JSON.
    '''
    if isinstance(pickled, str):
        raise TypeError("pickled data must be bytes-like, not str")
    if not isinstance(pickled, (bytes, bytearray, memoryview)):
        raise TypeError("pickled data must be bytes, bytearray, or memoryview")

    return _RestrictedUnpickler(io.BytesIO(bytes(pickled))).load()
