import os

from django.core.exceptions import ImproperlyConfigured


def _get_env(name: str, default: str | None = None, required: bool = False) -> str:
    """Fetch an environment variable, optionally requiring it to be present."""
    value = os.environ.get(name, default)
    if required and not value:
        raise ImproperlyConfigured(f"Missing required environment variable: {name}")
    return value


# Never hard-code credentials in source control; load them from the environment.
DATABASES = {
    "default": {
        "ENGINE": "django.db.backends.postgresql",
        "NAME": _get_env("DJANGO_DB_NAME", required=True),
        "USER": _get_env("DJANGO_DB_USER", required=True),
        "PASSWORD": _get_env("DJANGO_DB_PASSWORD", required=True),
        "HOST": _get_env("DJANGO_DB_HOST", "localhost"),
        "PORT": _get_env("DJANGO_DB_PORT", "5432"),
        "CONN_MAX_AGE": int(_get_env("DJANGO_DB_CONN_MAX_AGE", "60")),
        "CONN_HEALTH_CHECKS": True,
        "OPTIONS": {
            # Enforce TLS so credentials/data are not sent in clear text.
            "sslmode": _get_env("DJANGO_DB_SSLMODE", "require"),
            "connect_timeout": int(_get_env("DJANGO_DB_CONNECT_TIMEOUT", "10")),
        },
        "TEST": {
            "NAME": _get_env("DJANGO_DB_TEST_NAME", "test_default"),
        },
    }
}

# Prevent Django from logging full SQL with parameters in production.
if not os.environ.get("DJANGO_DEBUG", "0") == "1":
    for _db_config in DATABASES.values():
        _db_config.setdefault("OPTIONS", {})
