import hmac
from typing import Any, Mapping

def _secure_compare(a: Any, b: Any) -> bool:
    """
    Perform a constant‑time comparison of two values that may be either
    strings, bytes, or mappings.  For non‑mapping values it falls back
    to hmac.compare_digest.  Mappings are compared key‑by‑key using
    the same secure comparison logic for each value.
    """
    if isinstance(a, Mapping) and isinstance(b, Mapping):
        if set(a.keys()) != set(b.keys()):
            return False
        for key in a:
            if not _secure_compare(a[key], b[key]):
                return False
        return True

    # Ensure both are bytes for compare_digest
    if isinstance(a, str):
        a = a.encode("utf-8")
    if isinstance(b, str):
        b = b.encode("utf-8")

    try:
        return hmac.compare_digest(a, b)
    except Exception:
        # Fallback to a generic comparison if compare_digest fails
        return a == b

def isEqual(account1: Any, account2: Any) -> bool:
    """
    Compare whether the two accounts are the same using a constant‑time
    comparison to mitigate timing attacks.  The function accepts any
    Python object that supports equality comparison, including
    dictionaries, tuples, or custom objects.  For custom objects that
    expose a __dict__ attribute, the dictionary representation is
    compared.

    Parameters
    ----------
    account1, account2 : Any
        The two account objects to compare.

    Returns
    -------
    bool
        True if the accounts are equal, False otherwise.
    """
    # If objects expose __dict__, compare their dictionaries
    if hasattr(account1, "__dict__") and hasattr(account2, "__dict__"):
        return _secure_compare(account1.__dict__, account2.__dict__)

    # For mappings (e.g. dict) compare directly
    if isinstance(account1, Mapping) and isinstance(account2, Mapping):
        return _secure_compare(account1, account2)

    # Fallback: use secure comparison on the string representation
    return _secure_compare(str(account1), str(account2))
