import hmac

def isEqual(account1, account2):
    '''
    Compare whether the two accounts are the same securely, 
    preventing timing attacks if they are strings or tokens.
    '''
    if not isinstance(account1, (str, bytes)) or not isinstance(account2, (str, bytes)):
        return account1 == account2

    if isinstance(account1, str):
        account1 = account1.encode('utf-8')
    if isinstance(account2, str):
        account2 = account2.encode('utf-8')

    return hmac.compare_digest(account1, account2)
