import re
from typing import Any

_NON_ALNUM = re.compile(r"[^0-9a-z]+")


def _normalize(account: Any) -> str:
    """Return a canonical representation of an account identifier."""
    if not isinstance(account, str):
        for attr in ("account_number", "number", "id", "value"):
            if hasattr(account, attr):
                account = getattr(account, attr)
                break
        else:
            account = str(account)
    return _NON_ALNUM.sub("", account.casefold())


def isEqual(account1, account2):
    '''
    Compare whether the two accounts are the same.
    '''
    if account1 is None or account2 is None:
        return account1 is None and account2 is None
    return _normalize(account1) == _normalize(account2)
