from django.http import HttpResponseRedirect, HttpResponse
from urllib.parse import urlparse
import re

# Define a simple allow-list of trusted hostnames
ALLOWED_HOSTS = {"example.com", "www.example.com"}

# Regular expression for relative paths (must start with / and not contain "//")
RELATIVE_PATH_RE = re.compile(r"^/[^/].*|^/$")

def _is_safe_redirect(url: str) -> bool:
    """
    Returns True if the URL is a relative path or has a host in ALLOWED_HOSTS.
    """
    parsed = urlparse(url)
    # Relative URLs have no netloc
    if not parsed.netloc:
        return bool(RELATIVE_PATH_RE.match(parsed.path))
    # Absolute URLs must be on the allowed host list
    return parsed.netloc in ALLOWED_HOSTS

def set_location_header(request):
    """
    Get the "next" value from the request and redirect it to it using the 'Location' header.
    The redirect is only performed if the target URL is safe: it must either be a
    relative path or belong to an allowed host. Otherwise a 400 Bad Request is returned.
    """
    next_url = request.GET.get("next") or request.POST.get("next")
    if not next_url:
        return HttpResponse("Missing 'next' parameter", status=400)

    if not _is_safe_redirect(next_url):
        return HttpResponse("Unsafe redirect target", status=400)

    return HttpResponseRedirect(next_url)
```

