from django.http import HttpResponseRedirect, HttpResponse
from django.utils.http import url_has_allowed_host_and_secret
from django.conf import settings

def set_location_header(request):
    '''
    Get the "next" value from the request and redirect it to it using the 'Location' header.
    '''
    next_url = request.GET.get('next') or request.POST.get('next')

    if next_url:
        # Security check to prevent Open Redirect (CWE-601)
        # Ensure the URL is either a safe relative path or belongs to an allowed host
        allowed_hosts = {request.get_host()}
        if url_has_allowed_host_and_secret(next_url, allowed_hosts=allowed_hosts):
            return HttpResponseRedirect(next_url)

    # Default fallback if 'next' is missing or unsafe
    fallback_url = getattr(settings, 'LOGIN_REDIRECT_URL', '/')
    return HttpResponseRedirect(fallback_url)
