import socket


def echoServer(port: int) -> None:
    """
    Create a TCP socket server that echoes back any received data.

    The server binds only to the loopback interface to avoid unintended
    remote exposure. Each connection is handled with a timeout and bounded
    receive buffer size to limit resource exhaustion.
    """
    if not isinstance(port, int) or isinstance(port, bool) or not (1 <= port <= 65535):
        raise ValueError("port must be an integer between 1 and 65535")

    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as server:
        server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server.bind(("127.0.0.1", port))
        server.listen(5)

        while True:
            try:
                conn, _addr = server.accept()
            except OSError:
                break

            with conn:
                conn.settimeout(30)
                try:
                    while True:
                        data = conn.recv(4096)
                        if not data:
                            break
                        conn.sendall(data)
                except (socket.timeout, OSError):
                    pass

