import xml.sax
import xml.sax.handler
from xml.etree.ElementTree import Element


class _TreeBuilder(xml.sax.handler.ContentHandler):
    """SAX content handler that builds a lightweight ElementTree-like tree."""

    def __init__(self):
        super().__init__()
        self.root = None
        self._stack = []

    def startElement(self, name, attrs):
        elem = Element(name, dict(attrs))
        if self._stack:
            self._stack[-1].append(elem)
        else:
            self.root = elem
        self._stack.append(elem)

    def endElement(self, name):
        self._stack.pop()

    def characters(self, content):
        if not self._stack:
            return
        elem = self._stack[-1]
        if len(elem):
            child = elem[-1]
            child.tail = (child.tail or "") + content
        else:
            elem.text = (elem.text or "") + content


def get_root():
    '''
    Create an XML parser,
    parse the file 'resources/config.xml' and return the parsed result.
    '''
    parser = xml.sax.make_parser()

    # Harden the parser against XXE / external entity expansion.
    for feature in (
        xml.sax.handler.feature_external_ges,
        xml.sax.handler.feature_external_pes,
    ):
        try:
            parser.setFeature(feature, False)
        except (xml.sax.SAXNotRecognizedException,
                xml.sax.SAXNotSupportedException):
            pass

    # Disable namespace processing (not needed here) and avoid any DTD loading.
    try:
        parser.setFeature(xml.sax.handler.feature_namespaces, False)
    except (xml.sax.SAXNotRecognizedException,
            xml.sax.SAXNotSupportedException):
        pass

    handler = _TreeBuilder()
    parser.setContentHandler(handler)

    with open("resources/config.xml", "rb") as xml_file:
        parser.parse(xml_file)

    return handler.root
