def convert_to_int():
    """
    Continuously prompt the user for input and attempt to convert it to an integer.
    If the conversion fails, print an error message and continue prompting.
    """
    while True:
        user_input = input("Enter a number (or 'quit' to exit): ")
        if user_input.lower() == "quit":
            break
        try:
            number = int(user_input)
            print(f"Converted value: {number}")
        except ValueError:
            print(f"'{user_input}' is not a valid integer. Please try again.")
