import re


def checkNumber(number):
    """Use regular expression to match lines with numbers"""
    # Convert input to string safely to prevent type-related issues,
    # and use a strict regex to avoid catastrophic backtracking (ReDoS).
    # This pattern checks if the string represents a valid integer or float.
    pattern = r"^\s*[-+]?(?:\d+|\d*\.\d+|\d+\.\d*)\s*$"
    if not isinstance(number, (int, float, str)):
        return False
    return bool(re.match(pattern, str(number)))

