def find_median_sorted_arrays(nums1, nums2):
    if nums1 is None or nums2 is None:
        raise TypeError("Input arrays must not be None")
    if not isinstance(nums1, list) or not isinstance(nums2, list):
        raise TypeError("Inputs must be lists")

    total_length = len(nums1) + len(nums2)
    if total_length == 0:
        raise ValueError("Cannot find the median of two empty arrays")

    def _is_sorted(values):
        return all(values[i - 1] <= values[i] for i in range(1, len(values)))

    if not _is_sorted(nums1) or not _is_sorted(nums2):
        raise ValueError("Input arrays must be sorted")

    if len(nums1) > len(nums2):
        nums1, nums2 = nums2, nums1

    m, n = len(nums1), len(nums2)
    half = (m + n + 1) // 2
    low, high = 0, m

    while low <= high:
        i = (low + high) // 2
        j = half - i

        if i > 0 and j < n and nums1[i - 1] > nums2[j]:
            high = i - 1
        elif j > 0 and i < m and nums2[j - 1] > nums1[i]:
            low = i + 1
        else:
            if i == 0:
                left_max = nums2[j - 1]
            elif j == 0:
                left_max = nums1[i - 1]
            else:
                left_max = max(nums1[i - 1], nums2[j - 1])

            if (m + n) % 2 == 1:
                return left_max

            if i == m:
                right_min = nums2[j]
            elif j == n:
                right_min = nums1[i]
            else:
                right_min = min(nums1[i], nums2[j])

            return (left_max + right_min) / 2

    raise ValueError("Input arrays must be sorted")
