import hashlib
import os
import stat
from pathlib import Path


def get_avatar_checksum(user_id, avatar_filename):
    base_dir = Path("./Test/CWE-22_09/avatars").resolve(strict=False)

    def validate_component(value, name):
        if not isinstance(value, str) or not value or "\x00" in value:
            raise ValueError(f"{name} must be a non-empty string")

        path_value = Path(value)
        parts = path_value.parts

        if (
            path_value.is_absolute()
            or len(parts) != 1
            or parts[0] != value
            or value in (".", "..")
        ):
            raise ValueError(f"Invalid {name}")

        # Windows normalizes trailing dots and spaces; reject them to avoid bypasses.
        if os.name == "nt" and value.rstrip(" .") != value:
            raise ValueError(f"Invalid {name}")

    validate_component(user_id, "user_id")
    validate_component(avatar_filename, "avatar_filename")

    candidate = (base_dir / user_id / avatar_filename).resolve(strict=True)

    try:
        candidate.relative_to(base_dir)
    except ValueError:
        raise ValueError("Resolved avatar path is outside the allowed directory")

    if not candidate.is_file():
        raise FileNotFoundError(f"Avatar file not found: {candidate}")

    flags = os.O_RDONLY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW

    fd = os.open(candidate, flags)
    try:
        if not stat.S_ISREG(os.fstat(fd).st_mode):
            raise FileNotFoundError(f"Avatar file not found: {candidate}")

        sha256 = hashlib.sha256()
        with os.fdopen(fd, "rb") as avatar_file:
            fd = -1
            for chunk in iter(lambda: avatar_file.read(8192), b""):
                sha256.update(chunk)
    finally:
        if fd != -1:
            os.close(fd)

    return f"Avatar checksum: {sha256.hexdigest()}"

