from datetime import datetime
from pathlib import Path


def append_audit_log(log_date, event_text):
    if not isinstance(log_date, str):
        raise TypeError("log_date must be a string")
    if not isinstance(event_text, str):
        raise TypeError("event_text must be a string")

    if not re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2}", log_date):
        raise ValueError(f"Invalid log_date format: {log_date!r}. Expected 'YYYY-MM-DD'.")

    try:
        datetime.strptime(log_date, "%Y-%m-%d")
    except ValueError:
        raise ValueError(f"Invalid calendar date: {log_date!r}")

    base_dir = Path("./Test/CWE-22_10/logs/").absolute()

    # Reject symlinked or otherwise redirected log directories.
    if base_dir.resolve() != base_dir:
        raise ValueError("Path traversal attempt detected")

    base_dir.mkdir(parents=True, exist_ok=True)

    if base_dir.resolve() != base_dir:
        raise ValueError("Path traversal attempt detected")

