import ast


def sum_odd_elements(data):
    if not isinstance(data, str):
        raise TypeError("data must be a string representing a Python list of integers")

    try:
        parsed = ast.literal_eval(data)
    except (ValueError, SyntaxError) as exc:
        raise ValueError("data must be a valid string representation of a Python list") from exc

    if not isinstance(parsed, list):
        raise ValueError("data must represent a Python list")

    for item in parsed:
        if not isinstance(item, int) or isinstance(item, bool):
            raise ValueError("all elements in the list must be integers")

    return sum(item for item in parsed if item % 2 != 0)

