import os

def count_directories(directory: str) -> int:
    try:
        # Resolve to an absolute path to prevent traversal issues if applicable,
        # and ensure the path exists and is a directory.
        if not os.path.isdir(directory):
            raise NotADirectoryError(f"'{directory}' is not a valid directory.")

        with os.scandir(directory) as entries:
            return sum(1 for entry in entries if entry.is_dir())
    except (TypeError, ValueError) as e:
        raise OSError(f"Invalid directory path provided: {e}")
    except OSError:
        raise
    except Exception as e:
        raise OSError(f"Could not read directory '{directory}': {e}")
