import html

def build_redirect_page(target_url: str) -> str:
    if not isinstance(target_url, str) or not target_url.strip():
        raise ValueError("target_url must be a non-empty string")

    # Prevent XSS and HTML injection by escaping the target_url
    escaped_url = html.escape(target_url, quote=True)

    return (
        f'<html><head><meta http-equiv="refresh" content="0;url={escaped_url}">'
        f'</head><body>Go to <a href="{escaped_url}">{escaped_url}</a></body></html>'
    )
