import html


def build_redirect_page(target_url):
    """Return a minimal HTML page that redirects to *target_url*.

    Raises TypeError if *target_url* is not a string, and ValueError if it is
    empty or contains control characters that cannot be embedded safely.
    """
    if not isinstance(target_url, str):
        raise TypeError(
            "target_url must be a str, got %r" % (type(target_url).__name__,)
        )

    if not target_url.strip():
        raise ValueError("target_url must be a non-empty string")

    if any(ord(ch) < 0x20 or ord(ch) == 0x7F for ch in target_url):
        raise ValueError("target_url must not contain control characters")

    escaped = html.escape(target_url, quote=True)

    return (
        '<html><head><meta http-equiv="refresh" content="0;url={url}"></head>'
        '<body>Go to <a href="{url}">{url}</a></body></html>'
    ).format(url=escaped)

