code:
import ast
import operator

# Supported binary operators mapped to their functions
_OPERATORS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
}

def evaluate_expression(expression: str):
    """
    Evaluate a simple arithmetic expression containing integers,
    +, -, *, / operators and parentheses.

    Parameters
    ----------
    expression : str
        The expression to evaluate.

    Returns
    -------
    int | float
        The numeric result of the expression.

    Raises
    ------
    ValueError
        If the expression contains unsupported syntax or cannot be evaluated.
    ZeroDivisionError
        If division by zero occurs.
    """
    if not isinstance(expression, str):
        raise ValueError("Expression must be a string.")

    try:
        # Parse expression into an AST
        expr_ast = ast.parse(expression, mode='eval')
    except SyntaxError as e:
        raise ValueError(f"Invalid syntax: {e}") from e

    def _eval(node):
        if isinstance(node, ast.Expression):
            return _eval(node.body)
        elif isinstance(node, ast.Num):  # For Python <3.8
            return node.n
        elif isinstance(node, ast.Constant):  # For Python >=3.8
            if isinstance(node.value, (int, float)):
                return node.value
            raise ValueError(f"Unsupported constant type: {type(node.value)}")
        elif isinstance(node, ast.BinOp):
            left = _eval(node.left)
            right = _eval(node.right)
            op_type = type(node.op)
            if op_type not in _OPERATORS:
                raise ValueError(f"Unsupported operator: {op_type}")
            try:
                result = _OPERATORS[op_type](left, right)
            except ZeroDivisionError as e:
                raise ZeroDivisionError("Division by zero") from e
            return result
        elif isinstance(node, ast.UnaryOp):
            operand = _eval(node.operand)
            if isinstance(node.op, ast.UAdd):
                return +operand
            elif isinstance(node.op, ast.USub):
                return -operand
            else:
                raise ValueError(f"Unsupported unary operator: {type(node.op)}")
        elif isinstance(node, ast.Paren):
            return _eval(node.value)
        else:
            raise ValueError(f"Unsupported syntax element: {type(node)}")

    result = _eval(expr_ast)

    # Convert to int if result is an integer value
    if isinstance(result, float) and result.is_integer():
        return int(result)
    return result

