class _ExpressionParser:
    def __init__(self, expression):
        if not isinstance(expression, str):
            raise TypeError("expression must be a string")
        self.expression = expression
        self.index = 0
        self.length = len(expression)

    def parse(self):
        self._skip_whitespace()
        if self.index >= self.length:
            raise ValueError("empty expression")

        result = self._parse_expression()

        self._skip_whitespace()
        if self.index != self.length:
            raise ValueError(
                f"unexpected character {self.expression[self.index]!r} "
                f"at position {self.index}"
            )

        return result

    def _skip_whitespace(self):
        while self.index < self.length and self.expression[self.index].isspace():
            self.index += 1

    def _peek(self):
        self._skip_whitespace()
        if self.index >= self.length:
            return ""
        return self.expression[self.index]

    def _parse_expression(self):
        value = self._parse_term()

        while True:
            operator = self._peek()
            if operator not in ("+", "-"):
                break

            self.index += 1
            right = self._parse_term()

            if operator == "+":
                value += right
            else:
                value -= right

        return value

    def _parse_term(self):
        value = self._parse_factor()

        while True:
            operator = self._peek()
            if operator not in ("*", "/"):
                break

            self.index += 1
            right = self._parse_factor()

            if operator == "*":
                value *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                value /= right

        return value

    def _parse_factor(self):
        self._skip_whitespace()

        if self.index >= self.length:
            raise ValueError("unexpected end of expression")

        character = self.expression[self.index]

        if character == "+":
            self.index += 1
            return self._parse_factor()

        if character == "-":
            self.index += 1
            return -self._parse_factor()

        if character == "(":
            self.index += 1
            value = self._parse_expression()
            self._skip_whitespace()

            if self.index >= self.length or self.expression[self.index] != ")":
                raise ValueError("missing closing parenthesis")

            self.index += 1
            return value

        if character.isdigit():
            start = self.index
            while self.index < self.length and self.expression[self.index].isdigit():
                self.index += 1
            return int(self.expression[start:self.index])

        raise ValueError(
            f"unexpected character {character!r} at position {self.index}"
        )


def evaluate_expression(expression):
    return _ExpressionParser(expression).parse()

