import ast
import operator as op

# Supported binary operators mapping from AST operator nodes to functions
OPERATORS = {
    ast.Add: op.add,
    ast.Sub: op.sub,
    ast.Mult: op.mul,
    ast.Div: op.truediv,
}

def _eval(node: ast.AST) -> float:
    if isinstance(node, ast.Num):          # Python <3.8
        return node.n
    if isinstance(node, ast.Constant):     # Python >=3.8
        if isinstance(node.value, (int, float)):
            return node.value
        raise TypeError(f"Unsupported constant type: {type(node.value).__name__}")

    if isinstance(node, ast.BinOp):
        left = _eval(node.left)
        right = _eval(node.right)
        op_type = type(node.op)
        if op_type not in OPERATORS:
            raise TypeError(f"Unsupported operator: {op_type.__name__}")
        try:
            return OPERATORS[op_type](left, right)
        except ZeroDivisionError as exc:
            raise ZeroDivisionError("Division by zero") from exc

    if isinstance(node, ast.UnaryOp):
        operand = _eval(node.operand)
        if isinstance(node.op, ast.UAdd):
            return +operand
        if isinstance(node.op, ast.USub):
            return -operand
        raise TypeError(f"Unsupported unary operator: {type(node.op).__name__}")

    if isinstance(node, ast.Expression):
        return _eval(node.body)

    raise TypeError(f"Unsupported expression: {ast.dump(node)}")

def execute_command(command: str) -> float:
    """
    Evaluate a simple arithmetic expression containing digits, whitespace,
    '+', '-', '*', '/', and parentheses.

    Parameters
    ----------
    command : str
        The arithmetic expression to evaluate.

    Returns
    -------
    float
        The numeric result of evaluating the expression.

    Raises
    ------
    SyntaxError
        If the expression contains invalid syntax.
    TypeError
        If the expression contains unsupported operations or data types.
    ZeroDivisionError
        If division by zero occurs.
    """
    if not isinstance(command, str):
        raise TypeError("command must be a string")

    try:
        tree = ast.parse(command, mode='eval')
    except SyntaxError as exc:
        raise SyntaxError(f"Invalid syntax: {exc.msg}") from exc

    try:
        result = _eval(tree)
    except (SyntaxError, TypeError, ZeroDivisionError):
        raise
    except Exception as exc:
        raise RuntimeError("Failed to evaluate expression") from exc

    return result

