def calculate_submatrix_sum(matrix, row1, col1, row2, col2, k):
    if not isinstance(matrix, list) or not matrix or not isinstance(matrix[0], list) or not matrix[0]:
        raise ValueError("Matrix must be a non-empty list of lists.")

    rows = len(matrix)
    cols = len(matrix[0])

    # Validate types of inputs to prevent unexpected behavior
    if not all(isinstance(val, int) for val in [row1, col1, row2, col2, k]):
        raise TypeError("Coordinates and target sum must be integers.")

    if not (0 <= row1 <= row2 < rows and 0 <= col1 <= col2 < cols):
        raise IndexError("Submatrix coordinates are out of bounds.")

    sub_sum = 0
    for r in range(row1, row2 + 1):
        if not isinstance(matrix[r], list) or len(matrix[r]) != cols:
            raise ValueError("Matrix is ragged (inconsistent row lengths).")
        for c in range(col1, col2 + 1):
            val = matrix[r][c]
            if not isinstance(val, (int, float)):
                raise TypeError("Matrix elements must be numbers.")
            sub_sum += val

    return sub_sum == k
