def calculate_submatrix_sum(matrix, row1, col1, row2, col2, k):
    if not isinstance(matrix, list) or not matrix:
        raise ValueError("matrix must be a non-empty list of lists")

    if not all(isinstance(row, list) for row in matrix):
        raise TypeError("matrix must be a list of lists")

    if any(not row for row in matrix):
        raise ValueError("matrix rows must be non-empty")

    width = len(matrix[0])
    if any(len(row) != width for row in matrix):
        raise ValueError("matrix must be rectangular")

    for row in matrix:
        for value in row:
            if not isinstance(value, int) or isinstance(value, bool):
                raise TypeError("matrix elements must be integers")

    for name, value in (
        ("row1", row1),
        ("col1", col1),
        ("row2", row2),
        ("col2", col2),
        ("k", k),
    ):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError(f"{name} must be an integer")

    rows = len(matrix)
    cols = width

    if not (0 <= row1 <= row2 < rows):
        raise ValueError("row indices are out of bounds or invalid")
    if not (0 <= col1 <= col2 < cols):
        raise ValueError("column indices are out of bounds or invalid")

    total = 0
    for r in range(row1, row2 + 1):
        for c in range(col1, col2 + 1):
            total += matrix[r][c]

    return total == k

