import os
import stat


def save_firmware_blob(blob_name, blob_bytes, upload_dir):
    if not isinstance(blob_name, str) or not blob_name.strip():
        raise ValueError("blob_name must be a non-empty string")

    if not isinstance(blob_bytes, (bytes, bytearray)):
        raise TypeError("blob_bytes must be bytes or bytearray")

    if len(blob_bytes) > 256 * 1024:
        raise ValueError("blob_bytes exceeds the 256KB size limit")

    if not blob_name.lower().endswith(".bin"):
        raise ValueError("blob_name must end with '.bin'")

    if os.path.splitext(blob_name)[1].lower() != ".bin":
        raise ValueError("double extensions are not allowed; the last extension must be '.bin'")

    if bytes(blob_bytes[:4]) != b"FWR1":
        raise ValueError("firmware must start with the magic header b'FWR1'")

    safe_name = os.path.basename(blob_name.replace("\\", "/"))
    if not safe_name or safe_name in (".", ".."):
        raise ValueError("invalid blob_name")

    if not safe_name.lower().endswith(".bin"):
        raise ValueError("invalid blob_name")

    if os.path.splitext(safe_name)[1].lower() != ".bin":
        raise ValueError("invalid blob_name")

    base_dir = os.path.abspath(upload_dir)
    os.makedirs(base_dir, exist_ok=True)

    full_path = os.path.join(base_dir, safe_name)

    flags = os.O_WRONLY | os.O_CREAT | os.O_TRUNC
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    if hasattr(os, "O_BINARY"):
        flags |= os.O_BINARY

    if os.name == "posix" and hasattr(os, "O_DIRECTORY"):
        dir_flags = os.O_RDONLY | os.O_DIRECTORY
        if hasattr(os, "O_NOFOLLOW"):
            dir_flags |= os.O_NOFOLLOW
        try:
            dir_fd = os.open(base_dir, dir_flags)
        except OSError as e:
            raise ValueError("could not open upload directory securely") from e
        try:
            fd = os.open(safe_name, flags, 0o600, dir_fd=dir_fd)
            try:
                st = os.fstat(fd)
                if not stat.S_ISREG(st.st_mode):
                    raise ValueError("target is not a regular file")
                view = memoryview(blob_bytes)
                while view:
                    written = os.write(fd, view)
                    view = view[written:]
            finally:
                os.close(fd)
        finally:
            os.close(dir_fd)
    else:
        real_base = os.path.realpath(base_dir)
        real_full = os.path.realpath(full_path)
        try:
            if os.path.commonpath([real_base, real_full]) != real_base:
                raise ValueError("path traversal detected")
        except ValueError:
            raise ValueError("path traversal detected")
        fd = os.open(full_path, flags, 0o600)
        try:
            st = os.fstat(fd)
            if not stat.S_ISREG(st.st_mode):
                raise ValueError("target is not a regular file")
            view = memoryview(blob_bytes)
            while view:
                written = os.write(fd, view)
                view = view[written:]
        finally:
            os.close(fd)

    return f"Firmware stored at {os.path.realpath(full_path)}"
