import os


SUCCESS_MESSAGE = "Web template uploaded successfully."
_ALLOWED_FILE_TYPES = {"html", "css"}


def upload_web_template(user_id, file_name, file_content, file_type, base_dir):
    if not isinstance(file_name, str) or not file_name:
        raise ValueError("file_name must be a non-empty string")

    if not isinstance(file_type, str):
        raise ValueError("file_type must be a string")

    normalized_file_type = file_type.lower()
    if normalized_file_type not in _ALLOWED_FILE_TYPES:
        raise ValueError(f"Unsupported file type: {file_type!r}")

    if not isinstance(file_content, (str, bytes)):
        raise TypeError("file_content must be str or bytes")

    if os.path.isabs(file_name) or file_name in (".", ".."):
        raise ValueError("Invalid file name")

    if "/" in file_name or "\\" in file_name or "\x00" in file_name:
        raise ValueError("Invalid file name")

    if os.path.basename(file_name) != file_name:
        raise ValueError("Invalid file name")

    root, extension = os.path.splitext(file_name)
    if not root or extension.lower() != f".{normalized_file_type}":
        raise ValueError("File name extension does not match file_type")

    base_path = os.path.abspath(os.fsdecode(os.fspath(base_dir)))
    os.makedirs(base_path, exist_ok=True)

    if not os.path.isdir(base_path):
        raise NotADirectoryError(f"base_dir is not a directory: {base_path!r}")

    target_path = os.path.join(base_path, file_name)
    base_real_path = os.path.realpath(base_path)
    target_real_path = os.path.realpath(target_path)

    try:
        common_path = os.path.commonpath([base_real_path, target_real_path])
    except ValueError as exc:
        raise ValueError("Invalid file path") from exc

    if common_path != base_real_path:
        raise ValueError("File path escapes base_dir")

    flags = os.O_WRONLY | os.O_CREAT | os.O_TRUNC
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW

    fd = os.open(target_path, flags, 0o600)
    try:
        if isinstance(file_content, bytes):
            with os.fdopen(fd, "wb") as file_handle:
                file_handle.write(file_content)
        else:
            with os.fdopen(fd, "w", encoding="utf-8") as file_handle:
                file_handle.write(file_content)
    except Exception:
        try:
            os.close(fd)
        except OSError:
            pass
        raise

    return SUCCESS_MESSAGE

