import os
import stat


SUCCESS_MESSAGE = "Web template uploaded successfully."
_ALLOWED_FILE_TYPES = {"html", "css"}


def upload_web_template(user_id, file_name, file_content, file_type, base_dir):
    if not isinstance(file_name, str) or not file_name:
        raise ValueError("file_name must be a non-empty string")

    if not isinstance(file_type, str):
        raise ValueError("file_type must be a string")

    normalized_file_type = file_type.lower()
    if normalized_file_type not in _ALLOWED_FILE_TYPES:
        raise ValueError(f"Unsupported file type: {file_type!r}")

    if not isinstance(file_content, (str, bytes)):
        raise TypeError("file_content must be str or bytes")

    if os.path.isabs(file_name) or file_name in (".", ".."):
        raise ValueError("Invalid file name")

    if "/" in file_name or "\\" in file_name or "\x00" in file_name:
        raise ValueError("Invalid file name")

    if os.path.basename(file_name) != file_name:
        raise ValueError("Invalid file name")

    if os.name == "nt" and ":" in file_name:
        raise ValueError("Invalid file name")

    root, extension = os.path.splitext(file_name)
    if not root or extension.lower() != f".{normalized_file_type}":
        raise ValueError("File name extension does not match file_type")

    base_path = os.path.abspath(os.fsdecode(os.fspath(base_dir)))
    os.makedirs(base_path, exist_ok=True)

    if not os.path.isdir(base_path):
        raise NotADirectoryError(f"base_dir is not a directory: {base_path!r}")

    base_real_path = os.path.realpath(base_path)
    if not os.path.isdir(base_real_path):
        raise NotADirectoryError(f"base_dir is not a directory: {base_real_path!r}")

    open_flags = os.O_WRONLY | os.O_CREAT
    if hasattr(os, "O_NOFOLLOW"):
        open_flags |= os.O_NOFOLLOW
    if hasattr(os, "O_NONBLOCK"):
        open_flags |= os.O_NONBLOCK
    if hasattr(os, "O_NOCTTY"):
        open_flags |= os.O_NOCTTY
    if hasattr(os, "O_CLOEXEC"):
        open_flags |= os.O_CLOEXEC

    dir_fd = None
    fd = None
    try:
        if os.open in getattr(os, "supports_dir_fd", set()):
            dir_flags = os.O_RDONLY
            if hasattr(os, "O_PATH"):
                dir_flags = os.O_PATH
            if hasattr(os, "O_DIRECTORY"):
                dir_flags |= os.O_DIRECTORY
            if hasattr(os, "O_NOFOLLOW"):
                dir_flags |= os.O_NOFOLLOW
            if hasattr(os, "O_CLOEXEC"):
                dir_flags |= os.O_CLOEXEC

            dir_fd = os.open(base_real_path, dir_flags)
            if not stat.S_ISDIR(os.fstat(dir_fd).st_mode):
                raise NotADirectoryError(f"base_dir is not a directory: {base_real_path!r}")

            fd = os.open(file_name, open_flags, 0o600, dir_fd=dir_fd)
        else:
            target_path = os.path.join(base_real_path, file_name)

            if not hasattr(os, "O_NOFOLLOW"):
                try:
                    existing = os.lstat(target_path)
                except FileNotFoundError:
                    pass
                else:
                    if stat.S_ISLNK(existing.st_mode):
                        raise ValueError("Target path is a symbolic link")

            fd = os.open(target_path, open_flags, 0o600)

        st = os.fstat(fd)
        if not stat.S_ISREG(st.st_mode):
            raise ValueError("Target path is not a regular file")
        if st.st_nlink > 1:
            raise ValueError("Target file has multiple hard links")

        os.ftruncate(fd, 0)

        if isinstance(file_content, bytes):
            file_handle = os.fdopen(fd, "wb")
        else:
            file_handle = os.fdopen(fd, "w", encoding="utf-8")

        fd = None
        with file_handle:
            file_handle.write(file_content)
    finally:
        if fd is not None:
            try:
                os.close(fd)
            except OSError:
                pass
        if dir_fd is not None:
            try:
                os.close(dir_fd)
            except OSError:
                pass

    return SUCCESS_MESSAGE
