import base64
import json
import binascii


def _reject_json_constant(value):
    # Reject non-standard JSON constants (NaN, Infinity, -Infinity) which
    # Python's json module accepts by default but are not valid JSON.
    raise ValueError(f"Invalid JSON constant: {value}")


def load_user_preferences(prefs_string):
    if not isinstance(prefs_string, (str, bytes)):
        raise TypeError("prefs_string must be a str or bytes")

    # Use validate=True so invalid characters are rejected instead of
    # silently discarded (which can mask tampered payloads).
    try:
        decoded_bytes = base64.b64decode(prefs_string, validate=True)
    except (binascii.Error, ValueError) as exc:
        raise ValueError("Invalid base64-encoded string") from exc

    try:
        decoded_str = decoded_bytes.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ValueError("Decoded content is not valid UTF-8") from exc

    try:
        preferences = json.loads(decoded_str, parse_constant=_reject_json_constant)
    except json.JSONDecodeError as exc:
        raise ValueError("Decoded content is not valid JSON") from exc
    except RecursionError as exc:
        # Guard against deeply nested payloads causing a stack overflow.
        raise ValueError("Decoded JSON is too deeply nested") from exc
    except ValueError as exc:
        raise ValueError("Decoded content is not valid JSON") from exc

    if not isinstance(preferences, dict):
        raise ValueError("Decoded JSON must be an object (dictionary)")

    return preferences
