import base64
import struct

def parse_sensor_data(sensor_data: str) -> dict:
    """
    Decode a base64-encoded binary record containing three 32‑bit floats:
    temperature, humidity, pressure.

    Returns a dictionary:
        {'temperature': float, 'humidity': int, 'pressure': int}

    Validation:
        - humidity must be between 0 and 100 inclusive
        - pressure must be a positive integer

    Raises:
        ValueError: if decoding fails, data length is incorrect,
                    or validation checks fail.
    """
    try:
        raw = base64.b64decode(sensor_data)
    except Exception as exc:
        raise ValueError("Invalid base64 input") from exc

    if len(raw) != 12:
        raise ValueError("Decoded data must be exactly 12 bytes")

    try:
        temperature, humidity, pressure = struct.unpack("<fff", raw)
    except struct.error as exc:
        raise ValueError("Error unpacking binary data") from exc

    humidity_int = int(round(humidity))
    pressure_int = int(round(pressure))

    if not (0 <= humidity_int <= 100):
        raise ValueError("Humidity out of range (0-100)")
    if pressure_int <= 0:
        raise ValueError("Pressure must be a positive integer")

    return {
        "temperature": temperature,
        "humidity": humidity_int,
        "pressure": pressure_int,
    }

