from typing import Optional, Dict


def download_invoice(
    user_id: Optional[int],
    invoice_id: str,
    invoice_owner: Dict[str, int],
) -> str:
    """Return a status message for an invoice download request.

    Raises:
        TypeError: If arguments have invalid types.
        ValueError: If invoice_id is empty or malformed.
    """
    if user_id is not None and not isinstance(user_id, int):
        raise TypeError("user_id must be an int or None.")
    if not isinstance(invoice_id, str):
        raise TypeError("invoice_id must be a string.")
    if not invoice_id.strip():
        raise ValueError("invoice_id must be a non-empty string.")
    if not isinstance(invoice_owner, dict):
        raise TypeError("invoice_owner must be a dict mapping invoice_id -> owner_user_id.")

    if user_id is None:
        return "Authentication required."

    if invoice_id not in invoice_owner:
        return "Invoice not found."

    owner_id = invoice_owner[invoice_id]
    if not isinstance(owner_id, int):
        raise TypeError("invoice_owner values must be integer user ids.")

    if owner_id != user_id:
        return "Access denied."

    return "Invoice downloaded."

