import re
import xml.etree.ElementTree as ET

try:
    from defusedxml.ElementTree import fromstring as _safe_fromstring
    _HAS_DEFUSEDXML = True
except ImportError:
    _HAS_DEFUSEDXML = False
    _DOCTYPE_RE = re.compile(rb"<!DOCTYPE", re.IGNORECASE)


def _fromstring(data):
    if _HAS_DEFUSEDXML:
        return _safe_fromstring(data)
    if isinstance(data, str):
        raw = data.encode("utf-8", "ignore")
    else:
        raw = bytes(data)
    if _DOCTYPE_RE.search(raw):
        raise ValueError("XML documents with DOCTYPE declarations are not allowed")
    return ET.fromstring(data)


def parse_xml(xml_string):
    '''
    Parse xml_string and return the root element of the XML document
    '''
    if isinstance(xml_string, (bytes, bytearray)):
        root = _fromstring(xml_string)
    elif isinstance(xml_string, str):
        root = _fromstring(xml_string.strip())
    else:
        raise TypeError("xml_string must be a str or bytes-like object")
    return root
```

