import html
from html.parser import HTMLParser
from typing import List


class _ScriptRemover(HTMLParser):
    """
    HTMLParser subclass that removes <script> tags and their content.
    """

    def __init__(self):
        super().__init__()
        self._parts: List[str] = []
        self._skip: int = 0

    def handle_starttag(self, tag: str, attrs: List[tuple]) -> None:
        if tag.lower() == "script":
            self._skip += 1
        elif self._skip == 0:
            attrs_str = "".join(f' {name}="{html.escape(value, quote=True)}"' for name, value in attrs)
            self._parts.append(f"<{tag}{attrs_str}>")

    def handle_endtag(self, tag: str) -> None:
        if tag.lower() == "script":
            if self._skip:
                self._skip -= 1
        elif self._skip == 0:
            self._parts.append(f"</{tag}>")

    def handle_startendtag(self, tag: str, attrs: List[tuple]) -> None:
        if tag.lower() == "script":
            # Self‑closing script tags are rare but we skip them
            return
        if self._skip == 0:
            attrs_str = "".join(f' {name}="{html.escape(value, quote=True)}"' for name, value in attrs)
            self._parts.append(f"<{tag}{attrs_str} />")

    def handle_data(self, data: str) -> None:
        if self._skip == 0:
            self._parts.append(data)

    def handle_entityref(self, name: str) -> None:
        if self._skip == 0:
            self._parts.append(f"&{name};")

    def handle_charref(self, name: str) -> None:
        if self._skip == 0:
            self._parts.append(f"&#{name};")

    def get_data(self) -> str:
        return "".join(self._parts)


def filterScriptTags(content: str) -> str:
    """
    Remove <script> tags (including their content) from the provided string.

    Parameters
    ----------
    content : str
        The input text containing potential <script> tags.

    Returns
    -------
    str
        The text with all <script>...</script> blocks removed.
    """
    parser = _ScriptRemover()
    parser.feed(content)
    parser.close()
    return parser.get_data()
