import re
from html.parser import HTMLParser


class _ScriptTagStripper(HTMLParser):
    """Streaming HTML parser that drops <script> elements and their contents."""

    def __init__(self):
        super().__init__(convert_charrefs=False)
        self._out = []
        self._script_depth = 0

    def _emit(self, text):
        if self._script_depth == 0:
            self._out.append(text)

    def handle_starttag(self, tag, attrs):
        if tag.lower() == 'script':
            self._script_depth += 1
            return
        self._emit(self.get_starttag_text())

    def handle_startendtag(self, tag, attrs):
        if tag.lower() == 'script':
            return
        self._emit(self.get_starttag_text())

    def handle_endtag(self, tag):
        if tag.lower() == 'script':
            if self._script_depth > 0:
                self._script_depth -= 1
            return
        self._emit('</%s>' % tag)

    def handle_data(self, data):
        self._emit(data)

    def handle_entityref(self, name):
        self._emit('&%s;' % name)

    def handle_charref(self, name):
        self._emit('&#%s;' % name)

    def handle_comment(self, data):
        self._emit('<!--%s-->' % data)

    def handle_decl(self, decl):
        self._emit('<!%s>' % decl)

    def handle_pi(self, data):
        self._emit('<?%s>' % data)

    def unknown_decl(self, data):
        self._emit('<![%s]>' % data)

    def get_result(self):
        return ''.join(self._out)


def filterScriptTags(content):
    '''
    Remove <script> tags from the content argument.
    '''
    if not isinstance(content, str):
        return content

    parser = _ScriptTagStripper()
    try:
        parser.feed(content)
        parser.close()
    except Exception:
        # Last-resort fallback: strip anything that looks like a script tag.
        content = re.sub(
            r'<script\b[^>]*>.*?</script\s*>',
            '',
            content,
            flags=re.IGNORECASE | re.DOTALL,
        )
        content = re.sub(
            r'</?script\b[^>]*>',
            '',
            content,
            flags=re.IGNORECASE,
        )
        return content

    return parser.get_result()
