import flask

def parse(data):
    if data is None:
        return None
    return data.split(',')


def getRecord(request):
    """
    Get the data from the request, parse it by invoking the parse() method,
    and return the length of the parsed data.
    """
    # Extract raw data from the request as a string
    raw_data = request.get_data(as_text=True)

    # Parse the data
    parsed = parse(raw_data)

    # If parsing returned None, return 0; otherwise return the length
    return 0 if parsed is None else len(parsed)

