import os
import signal


def killProcess(processID):
    '''
    Kill the process with the given processID.
    '''
    if isinstance(processID, bool) or not isinstance(processID, int):
        raise TypeError("processID must be an integer")

    # Reject zero and negative values: on POSIX, pid 0 signals the caller's
    # process group and negative pids signal arbitrary process groups.
    if processID <= 0:
        raise ValueError("processID must be a positive integer")

    max_pid = 2**31 - 1
    try:
        max_pid = int(os.sysconf("SC_PID_MAX"))
    except (AttributeError, ValueError, OSError):
        pass
    if processID > max_pid:
        raise ValueError("processID is out of range")

    try:
        os.kill(processID, signal.SIGTERM)
    except ProcessLookupError as exc:
        raise ProcessLookupError(
            f"No process found with ID {processID}"
        ) from exc
    except PermissionError as exc:
        raise PermissionError(
            f"Permission denied while killing process {processID}"
        ) from exc
    except OSError as exc:
        raise OSError(
            f"Failed to kill process {processID}: {exc}"
        ) from exc
