import hashlib
import hmac


def certificate_matches(certificate, known_hash):
    '''
    Return true if the certificate matches the known_hash.
    '''
    if certificate is None or known_hash is None:
        return False

    if isinstance(certificate, str):
        data = certificate.encode("utf-8")
    elif isinstance(certificate, (bytes, bytearray)):
        data = bytes(certificate)
    else:
        data = str(certificate).encode("utf-8")

    if isinstance(known_hash, str):
        expected = known_hash.strip().lower()
    else:
        expected = str(known_hash).strip().lower()

    for algorithm in ("sha256", "sha1", "md5", "sha512", "sha384", "sha224"):
        digest = hashlib.new(algorithm, data).hexdigest()
        if hmac.compare_digest(digest, expected):
            return True

    return False

