import os

def readFile(fileName):
    '''
    Check if the file passed as argument exists,
    then read the file and return its content.
    '''
    # Resolve to an absolute path to prevent path traversal issues where applicable,
    # or ensure basic safety checks. Here we validate that it's a file and normalize the path.
    if not isinstance(fileName, (str, bytes, os.PathLike)):
        raise TypeError("Invalid file name type.")

    safe_path = os.path.abspath(fileName)

    if os.path.exists(safe_path) and os.path.isfile(safe_path):
        with open(safe_path, 'r', encoding='utf-8') as file:
            return file.read()
    else:
        raise FileNotFoundError(f"The file '{fileName}' does not exist.")

