app = Flask(__name__)


@app.route('/upload')
def upload():
    username = request.args.get('username', '')
    attachment = request.files.get('file')

    if not username or attachment is None:
        return 'Missing username or file attachment', 400

    filename = attachment.filename or ''

    if re.search(re.escape(username), filename):
        return render_template_string(
            'Username "{{ username }}" found in filename "{{ filename }}"',
            username=username,
            filename=filename,
        )

    return render_template_string(
        'Username "{{ username }}" not found in filename "{{ filename }}"',
        username=username,
        filename=filename,
    )
