import re

from flask import Flask, request

app = Flask(__name__)


@app.route('/upload')
def upload():
    username = request.args.get('username', '')
    attachment = request.files.get('file')

    if not username or attachment is None:
        return 'Missing username or file attachment', 400, {'Content-Type': 'text/plain; charset=utf-8'}

    # Limit input size to avoid resource exhaustion.
    if len(username) > 1024:
        return 'Username too long', 400, {'Content-Type': 'text/plain; charset=utf-8'}

    filename = attachment.filename or ''

    if len(filename) > 1024:
        return 'Filename too long', 400, {'Content-Type': 'text/plain; charset=utf-8'}

    # re.escape ensures the username is treated as a literal string,
    # preventing regex injection / ReDoS.
    if re.search(re.escape(username), filename):
        return (
            f'Username "{username}" found in filename "{filename}"',
            200,
            {'Content-Type': 'text/plain; charset=utf-8'},
        )

    return (
        f'Username "{username}" not found in filename "{filename}"',
        200,
        {'Content-Type': 'text/plain; charset=utf-8'},
    )
