```python
import os
import re
from datetime import datetime

from django.conf import settings
from django.http import FileResponse, HttpResponseBadRequest


def getResource(request):
    """
    Retrieve a file belonging to a user on a specific date.

    Expected query parameters:
        * username: the user name
        * date: the date string in ISO format (YYYY-MM-DD)

    The file is looked up under the directory:
        settings.MEDIA_ROOT / username / <date>.pdf

    Returns the file as a `FileResponse`. If the file does not exist or the
    parameters are missing/invalid, a 400 Bad Request is returned.
    """
    # Pull parameters from GET or POST data
    username = request.GET.get("username") or request.POST.get("username")
    date_str = request.GET.get("date") or request.POST.get("date")

    if not username or not date_str:
        return HttpResponseBadRequest("Missing 'username' or 'date' parameter")

    # Ensure the username contains only safe characters
    if not re.fullmatch(r"[A-Za-z0-9_-]+", username):
        return HttpResponseBadRequest("Invalid 'username' parameter")

    # Validate date format
    try:
        date_obj = datetime.strptime(date_str, "%Y-%m-%d")
    except ValueError:
        return HttpResponseBadRequest("Invalid date format. Expected YYYY-MM-DD")

    # Build the file path safely
    filename = f"{date_obj.strftime('%Y-%m-%d')}.pdf"
    user_dir = os.path.join(settings.MEDIA_ROOT, username)
    file_path = os.path.join(user_dir, filename)

    # Ensure the resulting path is still inside MEDIA_ROOT
    if not os.path.commonpath([settings.MEDIA_ROOT, file_path]) == os.path.normpath(settings.MEDIA_ROOT):
        return HttpResponseBadRequest("Invalid file path")

    if not os.path.isfile(file_path):
        return HttpResponseBadRequest("Requested file does not exist")

    # Serve the file
    try:
        file_obj = open(file_path, "rb")
    except OSError:
        return HttpResponseBadRequest("Could not open requested file")

    return FileResponse(file_obj, as_attachment=True, filename=filename)
