        _HAS_ADMIN_ACCESS.set(bool(value))

    def __bool__(self):
        return _HAS_ADMIN_ACCESS.get()

    def __eq__(self, other):
        return _HAS_ADMIN_ACCESS.get() == other

    def __repr__(self):
        return repr(_HAS_ADMIN_ACCESS.get())


