import io
import pickle


class _RestrictedUnpickler(pickle.Unpickler):
    '''
    A restricted unpickler that only allows a whitelist of safe,
    non-executable global objects. This prevents arbitrary code
    execution during deserialization.
    '''

    _SAFE_BUILTINS = frozenset({
        "list", "dict", "set", "frozenset", "tuple", "str", "bytes",
        "bytearray", "int", "float", "complex", "bool", "NoneType",
        "range", "slice",
    })

    _SAFE_MODULES = {
        "collections": frozenset({"OrderedDict", "defaultdict", "deque", "Counter"}),
        "collections.abc": frozenset({"Mapping", "Sequence", "Set"}),
        "datetime": frozenset({"datetime", "date", "time", "timedelta", "timezone"}),
        "decimal": frozenset({"Decimal"}),
        "fractions": frozenset({"Fraction"}),
        "uuid": frozenset({"UUID"}),
    }

    def find_class(self, module, name):
        if module == "builtins" and name in self._SAFE_BUILTINS:
            return super().find_class(module, name)
        allowed = self._SAFE_MODULES.get(module)
        if allowed is not None and name in allowed:
            return super().find_class(module, name)
        raise pickle.UnpicklingError(
            "Blocked unsafe global during unpickling: {}.{}".format(module, name)
        )


def getPickleData(pickled):
    '''
    Return deserialized data
    '''
    if isinstance(pickled, str):
        pickled = pickled.encode("latin-1")
    return _RestrictedUnpickler(io.BytesIO(pickled)).load()
