import sys

# Guard against denial-of-service via extremely long numeric strings passed to
# int(): CPython 3.11+ limits int/str conversion length, older versions do not
# (quadratic-time conversion). 4300 matches CPython's default limit.
_MAX_INPUT_CHARS = 4300
# Bound and escape user-controlled text before echoing it back to the terminal,
# to prevent ANSI/terminal escape-sequence injection and log forging.
_MAX_ECHO_CHARS = 100


def _sanitize_for_display(value: str) -> str:
    '''
    Return a printable, length-bounded representation of untrusted text so it
    can be safely written to a terminal or log (no control characters, no
    escape sequences, no unbounded output).
    '''
    if not isinstance(value, str):
        value = str(value)
    if len(value) > _MAX_ECHO_CHARS:
        value = value[:_MAX_ECHO_CHARS] + "..."
    # unicode_escape turns newlines/control chars into visible escapes and
    # backslashreplace keeps the result ASCII-safe for non-encodable characters.
    return value.encode("unicode_escape", "backslashreplace").decode("ascii", "replace")


def convert_to_int():
    '''
    Continuously take an input from user and convert it to int within a try-except block
    '''
    while True:
        try:
            user_input = input("Enter a number: ")
        except (KeyboardInterrupt, EOFError):
            print("\nInput cancelled.")
            return None

        try:
            if len(user_input) > _MAX_INPUT_CHARS:
                raise ValueError("input exceeds maximum accepted length")
            return int(user_input)
        except ValueError:
            print(
                f"Invalid input: '{_sanitize_for_display(user_input)}' "
                "is not a valid integer. Please try again."
            )
