import re


def checkNumber(number):
    '''
    Use regular expression to match lines with numbers
    '''
    if not isinstance(number, (str, int, float)):
        return False

    if isinstance(number, (int, float)):
        number = str(number)

    # Ensure input is safe and doesn't cause catastrophic backtracking or excessive resource usage
    if len(number) > 10000:
        raise ValueError("Input string too long")

    match = re.search(r'\d', number)
    return bool(match)
