from datetime import datetime

def schedule_meeting(start_time: str, duration_minutes: int) -> str:
    if not isinstance(start_time, str):
        raise ValueError("start_time must be a string")

    if not isinstance(duration_minutes, int) or isinstance(duration_minutes, bool):
        raise ValueError("duration_minutes must be an integer")

    if not (15 <= duration_minutes <= 480):
        raise ValueError("duration_minutes must be between 15 and 480")

    try:
        # Validate exact format and valid calendar time
        parsed_date = datetime.strptime(start_time, "%Y-%m-%d %H:%M")
    except ValueError as e:
        raise ValueError(f"Invalid start_time format or invalid date/time: {e}")

    # Ensure the string representation matches to prevent partial parsing issues (e.g., 2026-02-31)
    if parsed_date.strftime("%Y-%m-%d %H:%M") != start_time:
        raise ValueError("start_time is not a valid calendar date/time")

    return f"Meeting scheduled: {start_time} for {duration_minutes} minutes"
