def find_median_sorted_arrays(nums1, nums2):
    # Validate input types
    if not isinstance(nums1, list) or not isinstance(nums2, list):
        raise TypeError("Both inputs must be lists.")

    # Validate contents are numbers (int or float) and lists are sorted
    for lst_name, lst in [("nums1", nums1), ("nums2", nums2)]:
        for item in lst:
            if not isinstance(item, (int, float)):
                raise ValueError(f"All elements in {lst_name} must be numbers.")

        # Check if sorted
        if lst != sorted(lst):
            raise ValueError(f"Input list {lst_name} must be sorted.")

    # Combine and find median
    merged = nums1 + nums2
    merged.sort()

    total_len = len(merged)
    if total_len == 0:
        raise ValueError("Cannot find median of empty combined lists.")

    if total_len % 2 == 1:
        return float(merged[total_len // 2])
    else:
        mid1 = merged[(total_len // 2) - 1]
        mid2 = merged[total_len // 2]
        return (mid1 + mid2) / 2.0
