import numbers


def find_median_sorted_arrays(nums1, nums2):
    if not isinstance(nums1, list) or not isinstance(nums2, list):
        raise TypeError("nums1 and nums2 must be lists")

    for name, values in (("nums1", nums1), ("nums2", nums2)):
        for value in values:
            if isinstance(value, bool) or not isinstance(value, numbers.Real):
                raise TypeError(f"{name} must contain only real numbers")
        for index in range(1, len(values)):
            if values[index - 1] > values[index]:
                raise ValueError(f"{name} must be sorted in ascending order")

    if not nums1 and not nums2:
        raise ValueError("At least one input list must contain a value")

    merged = []
    i = 0
    j = 0

    while i < len(nums1) and j < len(nums2):
        if nums1[i] <= nums2[j]:
            merged.append(nums1[i])
            i += 1
        else:
            merged.append(nums2[j])
            j += 1

    if i < len(nums1):
        merged.extend(nums1[i:])
    if j < len(nums2):
        merged.extend(nums2[j:])

    total = len(merged)
    middle = total // 2

    if total % 2 == 1:
        return merged[middle]

    return (merged[middle - 1] + merged[middle]) / 2
