        if isinstance(value, bool) or not isinstance(value, Real):
            raise TypeError(
                f"{name}[{index}] must be a real number, got {type(value).__name__}"
            )
        if isinstance(value, float) and not math.isfinite(value):
            raise ValueError(f"{name}[{index}] must be finite, got {value!r}")
        if previous is not None and value < previous:
            raise ValueError(f"{name} must be sorted in non-decreasing order")
        previous = value


def find_median_sorted_arrays(nums1, nums2):
    _validate_sorted_list(nums1, "nums1")
    _validate_sorted_list(nums2, "nums2")

    if not nums1 and not nums2:
        raise ValueError("at least one of nums1 or nums2 must be non-empty")

    a, b = nums1, nums2
    if len(a) > len(b):
        a, b = b, a

    m, n = len(a), len(b)
    total = m + n
    half = (total + 1) // 2

    low, high = 0, m
    while low <= high:
        i = (low + high) // 2
        j = half - i

        a_left = a[i - 1] if i > 0 else float("-inf")
        a_right = a[i] if i < m else float("inf")
        b_left = b[j - 1] if j > 0 else float("-inf")
        b_right = b[j] if j < n else float("inf")

        if a_left <= b_right and b_left <= a_right:
            if total % 2 == 1:
                return max(a_left, b_left)
            return (max(a_left, b_left) + min(a_right, b_right)) / 2

        if a_left > b_right:
            high = i - 1
        else:
            low = i + 1

    raise ValueError("unable to compute median for the provided inputs")
