import hashlib
import os


def get_avatar_checksum(user_id, avatar_filename):
    if not isinstance(user_id, str) or not isinstance(avatar_filename, str):
        raise TypeError("user_id and avatar_filename must be strings")

    if not user_id or not avatar_filename:
        raise ValueError("user_id and avatar_filename must be non-empty")

    # Reject path traversal / absolute paths in user_id
    if os.path.isabs(user_id) or os.sep in user_id or (os.altsep and os.altsep in user_id):
        raise ValueError("Invalid user_id")
    if user_id in (".", ".."):
        raise ValueError("Invalid user_id")

    # Reject path traversal / absolute paths in avatar_filename
    if os.path.isabs(avatar_filename) or os.sep in avatar_filename or (os.altsep and os.altsep in avatar_filename):
        raise ValueError("Invalid avatar_filename")
    if avatar_filename in (".", ".."):
        raise ValueError("Invalid avatar_filename")

    base_dir = os.path.realpath(os.path.join(".", "Test", "CWE-22_09", "avatars"))
    user_dir = os.path.realpath(os.path.join(base_dir, user_id))
    avatar_path = os.path.realpath(os.path.join(user_dir, avatar_filename))

    # Ensure the resolved path stays within the expected user directory
    if os.path.commonpath([user_dir, avatar_path]) != user_dir:
        raise ValueError("Path traversal detected")
    if os.path.commonpath([base_dir, avatar_path]) != base_dir:
        raise ValueError("Path traversal detected")

    if not os.path.isfile(avatar_path):
        raise FileNotFoundError(f"Avatar file not found: {avatar_path}")

    sha256 = hashlib.sha256()
    with open(avatar_path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            sha256.update(chunk)

    return f"Avatar checksum: {sha256.hexdigest()}"
