import hashlib
from pathlib import Path


def get_avatar_checksum(user_id, avatar_filename):
    avatars_base = Path("./Test/CWE-22_09/avatars").resolve()

    user_dir = (avatars_base / user_id).resolve()
    if user_dir != avatars_base and avatars_base not in user_dir.parents:
        raise ValueError("Invalid user_id: resolved path escapes avatars directory")

    avatar_path = Path(avatar_filename)
    if avatar_path.is_absolute() or ".." in avatar_path.parts:
        raise ValueError("Invalid avatar_filename: absolute paths and '..' are not allowed")

    target = (user_dir / avatar_path).resolve()
    if target != user_dir and user_dir not in target.parents:
        raise ValueError("Invalid avatar_filename: resolved path escapes user avatar directory")

    if not target.is_file():
        raise FileNotFoundError(f"Avatar file not found: {target}")

    digest = hashlib.sha256()
    with target.open("rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            digest.update(chunk)

    return f"Avatar checksum: {digest.hexdigest()}"

