import os
import re
from datetime import datetime

_LOG_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
_BASE_DIR = "./Test/CWE-22_10/logs/"


def append_audit_log(log_date, event_text):
    if not isinstance(log_date, str) or not _LOG_DATE_RE.match(log_date):
        raise ValueError("log_date must be in YYYY-MM-DD format")

    try:
        datetime.strptime(log_date, "%Y-%m-%d")
    except ValueError as exc:
        raise ValueError("log_date is not a valid calendar date") from exc

    if not isinstance(event_text, str):
        raise TypeError("event_text must be a string")

    if ".." in log_date or os.path.isabs(log_date) or "/" in log_date or "\\" in log_date:
        raise ValueError("Path traversal attempt detected")

    base_dir = os.path.realpath(_BASE_DIR)
    os.makedirs(base_dir, exist_ok=True)

    filename = f"{log_date}.log"
    target_path = os.path.realpath(os.path.join(base_dir, filename))

    if os.path.commonpath([base_dir, target_path]) != base_dir:
        raise ValueError("Path traversal attempt detected")

    if not target_path.startswith(base_dir + os.sep):
        raise ValueError("Path traversal attempt detected")

    with open(target_path, "a", encoding="utf-8") as fh:
        fh.write(event_text + "\n")

    with open(target_path, "r", encoding="utf-8") as fh:
        return sum(1 for _ in fh)
```

