import os
import re
import subprocess
from datetime import datetime


def list_logs_in_range(log_dir, start_date, end_date):
    # Validate log_dir
    if not os.path.isdir(log_dir):
        raise ValueError(f"log_dir is not an existing directory: {log_dir}")

    # Validate date format
    date_re = re.compile(r"^\d{4}-\d{2}-\d{2}$")
    if not date_re.match(start_date) or not date_re.match(end_date):
        raise ValueError("Dates must be in YYYY-MM-DD format")

    try:
        start = datetime.strptime(start_date, "%Y-%m-%d").date()
        end = datetime.strptime(end_date, "%Y-%m-%d").date()
    except ValueError as e:
        raise ValueError(f"Invalid date: {e}")

    if start > end:
        raise ValueError("start_date must be <= end_date")

    # Call ls securely (no shell, use -- to end option parsing)
    try:
        output = subprocess.check_output(
