            text=True,
        )
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to list directory contents: {e}")

    filenames = output.splitlines()

    log_re = re.compile(r"^app-(\d{4}-\d{2}-\d{2})\.log$")
    result = []
    for name in filenames:
        m = log_re.match(name)
        if m:
