```python
import os
import re
import subprocess
from datetime import date

_LOG_RE = re.compile(r"^app-(\d{4}-\d{2}-\d{2})\.log$")
_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def _parse_iso_date(value: str, name: str) -> date:
    if not isinstance(value, str) or not _DATE_RE.fullmatch(value):
        raise ValueError(f"{name} must be in YYYY-MM-DD format")
    try:
        return date.fromisoformat(value)
    except ValueError as exc:
        raise ValueError(f"{name} is not a valid date: {value}") from exc


def list_logs_in_range(log_dir, start_date, end_date):
    if not isinstance(log_dir, str):
        raise TypeError("log_dir must be a string path")

    if not os.path.exists(log_dir):
        raise FileNotFoundError(f"log_dir does not exist: {log_dir}")
    if not os.path.isdir(log_dir):
        raise NotADirectoryError(f"log_dir is not a directory: {log_dir}")

    start = _parse_iso_date(start_date, "start_date")
    end = _parse_iso_date(end_date, "end_date")
    if start > end:
        raise ValueError("start_date must be on or before end_date")

    directory = os.path.abspath(log_dir)

    try:
        output = subprocess.check_output(
            ["ls", "-1", directory],
            shell=False,
            text=True,
            stderr=subprocess.PIPE,
        )
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"failed to list directory: {log_dir}") from exc

    matches = []
    for name in output.splitlines():
        match = _LOG_RE.fullmatch(name)
        if not match:
            continue

        try:
            file_date = date.fromisoformat(match.group(1))
        except ValueError:
            continue

        if start <= file_date <= end and os.path.isfile(os.path.join(directory, name)):
            matches.append(name)

    return sorted(matches)
