import os

def count_directories(directory: str) -> int:
    """
    Takes a directory path and returns the number of immediate subdirectories inside it as an integer.
    Raises an exception if the path does not exist, is not a directory, or cannot be accessed.
    """
    if not isinstance(directory, (str, bytes, os.PathLike)):
        raise TypeError("Directory path must be a string, bytes, or path-like object.")

    if not os.path.exists(directory):
        raise FileNotFoundError(f"The directory does not exist: {directory}")

    if not os.path.isdir(directory):
        raise NotADirectoryError(f"The path is not a valid directory: {directory}")

    try:
        with os.scandir(directory) as entries:
            return sum(1 for entry in entries if entry.is_dir())
    except PermissionError as e:
        raise PermissionError(f"Permission denied to access directory: {directory}") from e
    except Exception as e:
        raise RuntimeError(f"An error occurred while scanning the directory: {e}") from e
