import os


def count_directories(directory):
    if not isinstance(directory, (str, bytes, os.PathLike)):
        raise TypeError("directory must be a path-like object")
    count = 0
    with os.scandir(directory) as entries:
        for entry in entries:
            try:
                if entry.is_dir():
                    count += 1
            except OSError as exc:
                raise OSError(f"Unable to inspect entry {entry.path!r}") from exc
    return count
