import subprocess
import os

def archive_directory(directory, dest_tar_path):
    if not directory or not isinstance(directory, str):
        raise ValueError("Invalid directory path")
    if not dest_tar_path or not isinstance(dest_tar_path, str):
        raise ValueError("Invalid destination tar path")

    abs_dir = os.path.abspath(directory)
    if not os.path.isdir(abs_dir):
        raise NotADirectoryError(f"Directory not found: {directory}")

    # Use subprocess with shell=False and argument list to prevent command injection (CWE-78)
    # -c: create, -f: file
    # We change directory to the parent or use -C for safety and clean paths
    parent_dir = os.path.dirname(abs_dir)
    dir_name = os.path.basename(abs_dir)

    if not parent_dir:
        parent_dir = "."

    cmd = ["tar", "-cvf", os.path.abspath(dest_tar_path), "-C", parent_dir, dir_name]

    try:
        subprocess.run(cmd, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=False)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Tar command failed: {e.stderr.decode().strip()}")

    return f"Archived to {dest_tar_path}"

