    if dest_tar_path.startswith("-") or directory.startswith("-"):
        raise ValueError("paths must not start with '-'")

    try:
        result = subprocess.run(
            ["tar", "-cf", dest_tar_path, "-C", directory, "."],
            check=False,
            capture_output=True,
            text=True,
        )
    except FileNotFoundError as exc:
        raise RuntimeError("The 'tar' utility is not available") from exc

    if result.returncode != 0:
        raise RuntimeError(
            f"tar failed with exit code {result.returncode}: {result.stderr.strip()}"
        )

    return f"Archived to {dest_tar_path}"

