from html import escape
from urllib.parse import urlsplit


def build_redirect_page(target_url: str) -> str:
    if not isinstance(target_url, str):
        raise TypeError("target_url must be a string")

    if not target_url:
        raise ValueError("target_url must not be empty")

    if any(ch.isspace() or ord(ch) < 0x20 or ord(ch) == 0x7F for ch in target_url):
        raise ValueError("target_url must not contain whitespace or control characters")

    try:
        parsed = urlsplit(target_url)
    except ValueError as exc:
        raise ValueError("target_url is not a valid URL") from exc

    if parsed.scheme.lower() not in {"http", "https"} or not parsed.netloc:
        raise ValueError("target_url must be an absolute http or https URL")

    safe_url = escape(target_url, quote=True)

    return (
        '<html><head><meta http-equiv="refresh" content="0;url={url}"></head>'
        '<body>Go to <a href="{url}">{url}</a></body></html>'
    ).format(url=safe_url)
