import ast
import operator

def evaluate_expression(expression: str) -> float:
    """
    Evaluate a simple arithmetic expression containing numbers, +, -, *, / and parentheses.

    Parameters
    ----------
    expression : str
        The arithmetic expression to evaluate.

    Returns
    -------
    float
        The numeric result of the expression.

    Raises
    ------
    ValueError
        If the expression contains unsupported syntax or operators.
    ZeroDivisionError
        If a division by zero occurs.
    """
    # Define supported operators
    operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Pow: operator.pow,
        ast.USub: operator.neg,
        ast.UAdd: operator.pos,
    }

    def _eval(node: ast.AST) -> float:
        if isinstance(node, ast.Expression):
            return _eval(node.body)
        elif isinstance(node, ast.BinOp):
            left = _eval(node.left)
            right = _eval(node.right)
            op_type = type(node.op)
            if op_type not in operators:
                raise ValueError(f"Unsupported binary operator: {op_type.__name__}")
            return operators[op_type](left, right)
        elif isinstance(node, ast.UnaryOp):
            operand = _eval(node.operand)
            op_type = type(node.op)
            if op_type not in operators:
                raise ValueError(f"Unsupported unary operator: {op_type.__name__}")
            return operators[op_type](operand)
        elif isinstance(node, ast.Num):  # For Python <3.8
            return node.n
        elif isinstance(node, ast.Constant):  # For Python >=3.8
            if isinstance(node.value, (int, float)):
                return node.value
            else:
                raise ValueError(f"Unsupported constant type: {type(node.value).__name__}")
        elif isinstance(node, ast.Paren):  # Parentheses are handled by grouping
            return _eval(node.value)
        else:
            raise ValueError(f"Unsupported expression: {ast.dump(node)}")

    try:
        parsed = ast.parse(expression, mode='eval')
    except SyntaxError as e:
        raise ValueError(f"Invalid syntax: {e}")

    return _eval(parsed)

