```python
def evaluate_expression(expression):
    if not isinstance(expression, str):
        raise TypeError("expression must be a string")

    s = expression
    n = len(s)
    pos = 0

    def skip_whitespace():
        nonlocal pos
        while pos < n and s[pos].isspace():
            pos += 1

    def parse_expression():
        nonlocal pos
        skip_whitespace()
        value = parse_term()

        while True:
            skip_whitespace()
            if pos < n and s[pos] in "+-":
                op = s[pos]
                pos += 1
                right = parse_term()
                if op == "+":
                    value += right
                else:
                    value -= right
            else:
                break

        return value

    def parse_term():
        nonlocal pos
        skip_whitespace()
        value = parse_factor()

        while True:
            skip_whitespace()
            if pos < n and s[pos] in "*/":
                op = s[pos]
                pos += 1
                right = parse_factor()
                if op == "*":
                    value *= right
                else:
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    value /= right
            else:
                break

        return value

    def parse_factor():
        nonlocal pos
        skip_whitespace()

        if pos >= n:
            raise ValueError("unexpected end of expression")

        char = s[pos]
        if char in "+-":
            pos += 1
            value = parse_factor()
            return value if char == "+" else -value

        return parse_primary()

    def parse_primary():
        nonlocal pos
        skip_whitespace()

        if pos >= n:
            raise ValueError("unexpected end of expression")

        char = s[pos]

