class _ExpressionParser:
    def __init__(self, expression):
        if not isinstance(expression, str):
            raise TypeError("expression must be a string")
        self.expression = expression
        self.length = len(expression)
        self.pos = 0

    def parse(self):
        self._skip_whitespace()
        if self.pos >= self.length:
            raise ValueError("Expression is empty")

        value = self._parse_expression()

        self._skip_whitespace()
        if self.pos != self.length:
            raise ValueError(
                f"Unexpected character at position {self.pos}: "
                f"{self.expression[self.pos]!r}"
            )

        return self._normalize(value)

    def _skip_whitespace(self):
        while self.pos < self.length and self.expression[self.pos].isspace():
            self.pos += 1

    def _parse_expression(self):
        value = self._parse_term()

        while True:
            self._skip_whitespace()
            if self.pos < self.length and self.expression[self.pos] in "+-":
                op = self.expression[self.pos]
                self.pos += 1
                rhs = self._parse_term()

                if op == "+":
                    value += rhs
                else:
                    value -= rhs
            else:
                return value

    def _parse_term(self):
        value = self._parse_factor()

        while True:
            self._skip_whitespace()
            if self.pos < self.length and self.expression[self.pos] in "*/":
                op = self.expression[self.pos]
                self.pos += 1
                rhs = self._parse_factor()

                if op == "*":
                    value *= rhs
                else:
                    if rhs == 0:
                        raise ZeroDivisionError("division by zero")
                    value /= rhs
            else:
                return value

    def _parse_factor(self):
        self._skip_whitespace()

        sign = 1
        while self.pos < self.length and self.expression[self.pos] in "+-":
            if self.expression[self.pos] == "-":
                sign = -sign
            self.pos += 1
            self._skip_whitespace()

        value = self._parse_primary()
        return sign * value

    def _parse_primary(self):
        self._skip_whitespace()

        if self.pos >= self.length:
            raise ValueError("Unexpected end of expression")

        ch = self.expression[self.pos]

        if ch == "(":
            self.pos += 1
            value = self._parse_expression()
            self._skip_whitespace()

            if self.pos >= self.length or self.expression[self.pos] != ")":
                raise ValueError("Mismatched parentheses")

            self.pos += 1
            return value

        if "0" <= ch <= "9" or ch == ".":
            return self._parse_number()

        raise ValueError(
            f"Unexpected character at position {self.pos}: {ch!r}"
        )

    def _parse_number(self):
        start = self.pos
        saw_digit = False

        while self.pos < self.length and "0" <= self.expression[self.pos] <= "9":
            self.pos += 1
            saw_digit = True

        if self.pos < self.length and self.expression[self.pos] == ".":
            self.pos += 1
            while self.pos < self.length and "0" <= self.expression[self.pos] <= "9":
                self.pos += 1
                saw_digit = True

        if not saw_digit:
            raise ValueError(f"Invalid number at position {start}")

        token = self.expression[start:self.pos]

        try:
            if "." in token:
                return float(token)
            return int(token)
        except (ValueError, OverflowError) as exc:
            raise ValueError(f"Invalid number at position {start}") from exc

    @staticmethod
    def _normalize(value):
        if isinstance(value, float) and value.is_integer():
            return int(value)
        return value


def evaluate_expression(expression):
    return _ExpressionParser(expression).parse()
