```python
import re


def evaluate_expression(expression):
    """Safely evaluate an arithmetic expression string.

    Supports digits, whitespace, '+', '-', '*', '/' and parentheses.
    Raises ValueError for malformed input and ZeroDivisionError for
    division by zero. Never uses eval/exec/compile.
    """
    if not isinstance(expression, str):
        raise TypeError("expression must be a string")

    # Tokenize: numbers (with optional decimal part), operators, parentheses.
    tokens = re.findall(r"\d+\.\d+|\d+|[+\-*/()]", expression)

    # Reject anything that wasn't recognized as a valid token.
    stripped = re.sub(r"\s+", "", expression)
    if "".join(tokens) != stripped:
        raise ValueError("Invalid characters in expression: %r" % (expression,))
    if not tokens:
        raise ValueError("Empty expression")

    pos = [0]

    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None

    def advance():
        tok = tokens[pos[0]]
        pos[0] += 1
        return tok

    def parse_expr():
        value = parse_term()
        while peek() in ("+", "-"):
            op = advance()
            rhs = parse_term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def parse_term():
        value = parse_factor()
        while peek() in ("*", "/"):
            op = advance()
            rhs = parse_factor()
            if op == "*":
                value *= rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                value /= rhs
        return value

    def parse_factor():
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if tok == "(":
            advance()
            value = parse_expr()
            if peek() != ")":
                raise ValueError("Missing closing parenthesis")
            advance()
            return value
        if tok == "-":
            advance()
            return -parse_factor()
        if tok == "+":
            advance()
            return parse_factor()
        if tok in ("+", "-", "*", "/", ")"):
            raise ValueError("Unexpected token: %r" % (tok,))
        advance()
        return float(tok) if "." in tok else int(tok)

    result = parse_expr()
    if pos[0] != len(tokens):
        raise ValueError("Unexpected token: %r" % (tokens[pos[0]],))

    if isinstance(result, float) and result.is_integer():
        return int(result)
    return result
