import ast
import operator

_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
}

_UNARY_OPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
}


def _eval_node(node):
    """Recursively evaluate a validated AST node."""
    if isinstance(node, ast.Expression):
        return _eval_node(node.body)

    if isinstance(node, ast.Constant):
        value = node.value
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError(f"Unsupported constant: {value!r}")
        return value

    if isinstance(node, ast.BinOp):
        op = _BIN_OPS.get(type(node.op))
        if op is None:
            raise ValueError(f"Unsupported operator: {type(node.op).__name__}")
        return op(_eval_node(node.left), _eval_node(node.right))

    if isinstance(node, ast.UnaryOp):
        op = _UNARY_OPS.get(type(node.op))
        if op is None:
            raise ValueError(
                f"Unsupported unary operator: {type(node.op).__name__}"
            )
        return op(_eval_node(node.operand))

    raise ValueError(f"Unsupported expression element: {type(node).__name__}")


def execute_command(command):
    """Safely evaluate an arithmetic expression and return its numeric result.

    Supports digits, whitespace, '+', '-', '*', '/', and parentheses.
    Raises TypeError for non-string input, ValueError for malformed or
    unsupported expressions.
    """
    if not isinstance(command, str):
        raise TypeError("command must be a string")

    try:
        tree = ast.parse(command, mode="eval")
    except SyntaxError as exc:
        raise ValueError(f"Invalid arithmetic expression: {command!r}") from exc

    return _eval_node(tree)
