def calculate_submatrix_sum(matrix, row1, col1, row2, col2, k):
    if not matrix or not matrix[0]:
        raise ValueError("Matrix cannot be empty.")

    num_rows = len(matrix)
    num_cols = len(matrix[0])

    # Validate indices (CWE-125 mitigation)
    if not (0 <= row1 < num_rows and 0 <= row2 < num_rows and row1 <= row2):
        raise IndexError("Row indices are out of bounds or invalid.")
    if not (0 <= col1 < num_cols and 0 <= col2 < num_cols and col1 <= col2):
        raise IndexError("Column indices are out of bounds or invalid.")

    submatrix_sum = 0
    for r in range(row1, row2 + 1):
        if len(matrix[r]) != num_cols:
            raise ValueError("Matrix must be rectangular.")
        for c in range(col1, col2 + 1):
            submatrix_sum += matrix[r][c]

    return submatrix_sum == k
