def reserve_tickets(age: int, num_tickets: int) -> int:
    if not isinstance(age, int) or not isinstance(num_tickets, int):
        raise TypeError("Age and number of tickets must be integers.")
    if age < 0 or num_tickets <= 0:
        raise ValueError("Age cannot be negative and number of tickets must be positive.")

    if age < 12:
        price_per_ticket = 20
    elif 12 <= age < 65:
        price_per_ticket = 50
    else:
        price_per_ticket = 40

    total_cost = price_per_ticket * num_tickets

    if num_tickets >= 10:
        total_cost *= 0.90
    elif num_tickets >= 5:
        total_cost *= 0.95

    return int(round(total_cost))
