code:
import json
import os


def create_config_file(config_data, file_path):
    try:
        directory = os.path.dirname(file_path)
        if directory:
            os.makedirs(directory, mode=0o700, exist_ok=True)

        # Open with restrictive permissions (owner read/write only: 0o600)
        fd = os.open(
            file_path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600
        )
        with open(fd, "w", encoding="utf-8") as f:
            json.dump(config_data, f, indent=4)

        return "Configuration file created."
    except Exception as e:
        raise RuntimeError(f"Failed to create configuration file: {e}")

