import os


def save_firmware_blob(blob_name, blob_bytes, upload_dir):
    # Validate blob_name
    if not isinstance(blob_name, str) or not blob_name:
        raise ValueError("blob_name must be a non-empty string")

    # Validate blob_bytes
    if not isinstance(blob_bytes, (bytes, bytearray)):
        raise TypeError("blob_bytes must be bytes or bytearray")

    if len(blob_bytes) > 256 * 1024:
        raise ValueError("blob_bytes exceeds maximum allowed size of 256KB")

    if len(blob_bytes) < 4 or bytes(blob_bytes[:4]) != b"FWR1":
        raise ValueError("firmware blob must start with magic header b'FWR1'")

    # Sanitize name: strip any directory components (handles both / and \)
    safe_name = os.path.basename(blob_name.replace("\\", "/"))
    if not safe_name or safe_name in (".", ".."):
        raise ValueError("invalid blob_name")

    # Validate extension: must end with exactly ".bin" (case-insensitive)
    if len(safe_name) <= len(".bin"):
        raise ValueError("blob_name must end with '.bin'")
    last_ext = safe_name.rsplit(".", 1)[-1]
    if last_ext.lower() != "bin":
        raise ValueError("blob_name must end with '.bin' (double extensions rejected)")
    if not safe_name.lower().endswith(".bin"):
        raise ValueError("blob_name must end with '.bin'")

    # Resolve upload directory
    upload_dir_abs = os.path.abspath(upload_dir)
    os.makedirs(upload_dir_abs, exist_ok=True)

    full_path = os.path.abspath(os.path.join(upload_dir_abs, safe_name))

    # Prevent path traversal: resolved path must be strictly inside upload_dir
    try:
        common = os.path.commonpath([upload_dir_abs, full_path])
    except ValueError:
        raise ValueError("path traversal detected")
    if common != upload_dir_abs or full_path == upload_dir_abs:
        raise ValueError("path traversal detected")

    # Write the blob
    with open(full_path, "wb") as f:
        f.write(bytes(blob_bytes))

    return f"Firmware stored at {full_path}"

