code:
import os

MAX_SIZE = 256 * 1024
MAGIC = b"FWR1"


def save_firmware_blob(blob_name, blob_bytes, upload_dir):
    # --- validate name ---
    if not isinstance(blob_name, str) or not blob_name:
        raise ValueError("blob_name must be a non-empty string")
    if "\x00" in blob_name:
        raise ValueError("blob_name contains a null byte")

    # Strip any directory components (handles both '/' and '\\') to prevent traversal
    base_name = os.path.basename(blob_name.replace("\\", "/"))
    if not base_name or base_name in (".", ".."):
        raise ValueError("Invalid blob_name")

    root, ext = os.path.splitext(base_name)
    if not root or ext.lower() != ".bin":
        raise ValueError("blob_name must end with a single '.bin' extension")

    # --- validate payload ---
    if not isinstance(blob_bytes, (bytes, bytearray)):
        raise TypeError("blob_bytes must be bytes or bytearray")
    if len(blob_bytes) > MAX_SIZE:
        raise ValueError("blob_bytes exceeds the 256KB limit")
    if len(blob_bytes) < len(MAGIC) or bytes(blob_bytes[: len(MAGIC)]) != MAGIC:
        raise ValueError("Invalid firmware magic header")

    # --- validate destination ---
    if not isinstance(upload_dir, str) or not upload_dir:
        raise ValueError("upload_dir must be a non-empty string")

    upload_root = os.path.realpath(upload_dir)
    os.makedirs(upload_root, exist_ok=True)

    full_path = os.path.realpath(os.path.join(upload_root, base_name))

    # Ensure the resolved path stays inside upload_dir
    try:
        inside = os.path.commonpath([upload_root, full_path]) == upload_root
    except ValueError:
        inside = False
    if not inside:
        raise ValueError("Path traversal detected")

    # --- persist ---
    with open(full_path, "wb") as fh:
        fh.write(bytes(blob_bytes))

    return f"Firmware stored at {full_path}"

