import os

MAX_FIRMWARE_SIZE = 256 * 1024
FIRMWARE_MAGIC = b"FWR1"


def save_firmware_blob(blob_name, blob_bytes, upload_dir):
    if not isinstance(blob_name, str) or not blob_name:
        raise ValueError("blob_name must be a non-empty string")

    if "\x00" in blob_name:
        raise ValueError("blob_name contains a null byte")

    if not blob_name.lower().endswith(".bin"):
        raise ValueError("blob_name must end with .bin")

    normalized_name = blob_name.replace("\\", "/")
    filename = normalized_name.rsplit("/", 1)[-1]

    if not filename or filename in (".", ".."):
        raise ValueError("invalid blob_name")

    safe_filename = "".join(
        ch if ch.isalnum() or ch in "._-" else "_"
        for ch in filename
    )

    if not safe_filename or safe_filename in (".", ".."):
        raise ValueError("invalid blob_name")

    if not safe_filename.lower().endswith(".bin"):
        raise ValueError("blob_name must end with .bin")

    if os.path.splitext(safe_filename)[1].lower() != ".bin":
        raise ValueError("blob_name must have .bin as its final extension")

    if not isinstance(blob_bytes, (bytes, bytearray)):
        raise TypeError("blob_bytes must be bytes or bytearray")

    if len(blob_bytes) > MAX_FIRMWARE_SIZE:
        raise ValueError("blob_bytes exceeds the 256KB limit")

    if len(blob_bytes) < 4 or bytes(blob_bytes[:4]) != FIRMWARE_MAGIC:
        raise ValueError("blob_bytes does not start with the FWR1 magic header")

    if not isinstance(upload_dir, (str, bytes, os.PathLike)):
        raise TypeError("upload_dir must be a path")

    upload_dir_abs = os.path.abspath(os.fsdecode(os.fspath(upload_dir)))
    os.makedirs(upload_dir_abs, exist_ok=True)

    if not os.path.isdir(upload_dir_abs):
        raise NotADirectoryError(upload_dir_abs)

    destination = os.path.join(upload_dir_abs, safe_filename)
    destination_real = os.path.realpath(destination)
    upload_dir_real = os.path.realpath(upload_dir_abs)

    try:
        common_path = os.path.commonpath([upload_dir_real, destination_real])
    except ValueError as exc:
        raise ValueError("invalid upload path") from exc

    if common_path != upload_dir_real:
        raise ValueError("path traversal detected")

    with open(destination_real, "wb") as firmware_file:
        firmware_file.write(bytes(blob_bytes))

    return f"Firmware stored at {destination_real}"
