import os
import re

ALLOWED_TYPES = {"html", "css"}
MAX_FILE_SIZE = 5 * 1024 * 1024  # 5 MB
SAFE_NAME_RE = re.compile(r"^[A-Za-z0-9_\-]+(\.[A-Za-z0-9]+)?$")


def upload_web_template(user_id, file_name, file_content, file_type, base_dir):
    # --- Input validation -------------------------------------------------
    if not isinstance(user_id, str) or not user_id.strip():
        raise ValueError("Invalid user_id")
    if not isinstance(file_name, str) or not file_name.strip():
        raise ValueError("Invalid file_name")
    if not isinstance(file_type, str) or file_type.lower() not in ALLOWED_TYPES:
        raise ValueError(f"Unsupported file type: {file_type!r}")
    if not isinstance(file_content, (str, bytes)):
        raise TypeError("file_content must be str or bytes")
    if not isinstance(base_dir, str) or not base_dir.strip():
        raise ValueError("Invalid base_dir")

    file_type = file_type.lower()

    # --- Sanitise filename (prevent traversal / injection) ----------------
    safe_name = os.path.basename(file_name.replace("\\", "/")).strip()
    if not safe_name or safe_name in (".", ".."):
        raise ValueError("Invalid file name")
    if not SAFE_NAME_RE.match(safe_name):
        raise ValueError("File name contains disallowed characters")

    # --- Enforce extension matches declared file_type ---------------------
    ext = os.path.splitext(safe_name)[1].lower().lstrip(".")
    if ext != file_type:
        raise ValueError(
            f"File extension {ext!r} does not match declared type {file_type!r}"
        )

    # --- Enforce size limit -----------------------------------------------
    content_bytes = (
        file_content.encode("utf-8") if isinstance(file_content, str) else file_content
    )
    if len(content_bytes) > MAX_FILE_SIZE:
        raise ValueError("File exceeds maximum allowed size")

    # --- Resolve base_dir and ensure target stays inside it ---------------
    base_dir_abs = os.path.abspath(base_dir)
    try:
        os.makedirs(base_dir_abs, exist_ok=True)
    except OSError as exc:
        raise OSError(f"Unable to prepare base directory: {exc}") from exc

    target_path = os.path.abspath(os.path.join(base_dir_abs, safe_name))
    try:
        common = os.path.commonpath([base_dir_abs, target_path])
    except ValueError as exc:
        raise ValueError("Path traversal detected") from exc
    if common != base_dir_abs or target_path == base_dir_abs:
        raise ValueError("Path traversal detected")

    # --- Write file -------------------------------------------------------
    try:
        with open(target_path, "wb") as handle:
            handle.write(content_bytes)
    except OSError as exc:
        raise OSError(f"Failed to write file: {exc}") from exc

    return "Web template uploaded successfully."
```

