import json


def load_user_preferences(prefs_string):
    if not isinstance(prefs_string, str):
        raise TypeError("prefs_string must be a string")

    # Prevent excessive memory usage from extremely large inputs.
    if len(prefs_string) > 1_000_000:
        raise ValueError("prefs_string is too large")

    try:
        decoded_bytes = base64.b64decode(prefs_string, validate=True)
    except (binascii.Error, ValueError) as exc:
        raise ValueError("Invalid base64-encoded preferences string") from exc

    try:
        decoded_text = decoded_bytes.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ValueError("Decoded preferences are not valid UTF-8") from exc

    try:
        preferences = json.loads(decoded_text)
    except json.JSONDecodeError as exc:
        raise ValueError("Decoded preferences are not valid JSON") from exc

    if not isinstance(preferences, dict):
        raise ValueError("Decoded preferences must be a JSON object")

    return preferences
