import base64
import struct

def parse_sensor_data(sensor_data: str) -> dict:
    """
    Decode a base64-encoded string containing three 32‑bit floats:
    temperature, humidity, and pressure.
    Returns a dictionary with temperature as float, humidity and pressure as ints.
    Raises ValueError if decoding fails or the values are out of the expected bounds.
    """
    try:
        raw = base64.b64decode(sensor_data, validate=True)
    except (binascii.Error, ValueError) as exc:
        raise ValueError("Invalid base64 data") from exc

    if len(raw) != 12:
        raise ValueError("Decoded data length must be exactly 12 bytes")

    try:
        temp_f, hum_f, pres_f = struct.unpack(">fff", raw)
    except struct.error as exc:
        raise ValueError("Failed to unpack floats from data") from exc

    humidity = int(round(hum_f))
    pressure = int(round(pres_f))

    if not (0 <= humidity <= 100):
        raise ValueError("Humidity out of range (0-100)")
    if pressure <= 0:
        raise ValueError("Pressure must be positive")

    return {"temperature": temp_f, "humidity": humidity, "pressure": pressure}
