    try:
        decoded_bytes = base64.b64decode(sensor_data, validate=True)
    except Exception as e:
        raise ValueError("Invalid base64 encoding") from e

    if len(decoded_bytes) != 12:
        raise ValueError("Invalid data length: expected 12 bytes")

    try:
