import base64
import struct
import math


def parse_sensor_data(sensor_data):
    if not isinstance(sensor_data, str):
        raise TypeError("sensor_data must be a base64-encoded string")

    try:
        raw = base64.b64decode(sensor_data, validate=True)
    except Exception as exc:
        raise ValueError("Invalid base64 sensor data") from exc

    if len(raw) != 12:
        raise ValueError("Sensor data must contain exactly 12 bytes")

    temperature, humidity_float, pressure_float = struct.unpack("<3f", raw)

    if not all(math.isfinite(value) for value in (temperature, humidity_float, pressure_float)):
        raise ValueError("Sensor data contains non-finite values")

    if humidity_float != int(humidity_float) or not (0 <= humidity_float <= 100):
        raise ValueError("Humidity must be an integer between 0 and 100 inclusive")

    if pressure_float != int(pressure_float) or pressure_float <= 0:
        raise ValueError("Pressure must be a positive integer")

    return {
        "temperature": float(temperature),
        "humidity": int(humidity_float),
        "pressure": int(pressure_float),
    }
