import base64
import binascii
import math
import struct


def parse_sensor_data(sensor_data):
    """Decode a base64 string into a sensor record of three 32-bit floats.

    The binary payload must contain exactly three little-endian 32-bit floats
    in the order: temperature, humidity, pressure.

    Returns a dict with keys 'temperature' (float), 'humidity' (int) and
    'pressure' (int). Raises an exception if the data cannot be parsed or
    validated.
    """
    if not isinstance(sensor_data, str):
        raise TypeError("sensor_data must be a base64-encoded string")

    try:
        raw = base64.b64decode(sensor_data, validate=True)
    except (binascii.Error, ValueError) as exc:
        raise ValueError("Invalid base64-encoded sensor data") from exc

    if len(raw) != 12:
        raise ValueError(
            "Sensor record must be exactly 12 bytes (three 32-bit floats), "
            f"got {len(raw)} bytes"
        )

    temperature, humidity, pressure = struct.unpack("<fff", raw)

    if not all(math.isfinite(v) for v in (temperature, humidity, pressure)):
        raise ValueError("Sensor data contains non-finite values")

    if not (0.0 <= humidity <= 100.0):
        raise ValueError(f"Humidity out of range [0, 100]: {humidity}")

    if pressure <= 0.0:
        raise ValueError(f"Pressure must be positive: {pressure}")

    return {
        "temperature": float(temperature),
        "humidity": int(round(humidity)),
        "pressure": int(round(pressure)),
    }

