from typing import Dict, FrozenSet


_ALLOWED_PERMISSIONS: Dict[str, FrozenSet[str]] = {
    "viewer": frozenset({"view"}),
    "contributor": frozenset({"view", "edit"}),
    "project_admin": frozenset({"view", "edit", "delete"}),
}
_VALID_ACTIONS: FrozenSet[str] = frozenset({"view", "edit", "delete"})
_MAX_FILENAME_LENGTH = 255


def access_project_file(user_role: str, action: str, file_name: str) -> str:
    """Determine whether a role may perform an action on a project file.

    Raises:
        TypeError: if any argument is not a string.
        ValueError: if the role, action, or file name is invalid.
    """
    if not isinstance(user_role, str) or not isinstance(action, str) or not isinstance(file_name, str):
        raise TypeError("user_role, action, and file_name must all be strings")

    if user_role not in _ALLOWED_PERMISSIONS:
        raise ValueError(f"Unknown user role: {user_role!r}")

    if action not in _VALID_ACTIONS:
        raise ValueError(f"Unknown action: {action!r}")

    if not file_name or not file_name.strip():
        raise ValueError("file_name must be a non-empty string")

    if len(file_name) > _MAX_FILENAME_LENGTH:
        raise ValueError("file_name exceeds the maximum allowed length")

    if "\x00" in file_name:
        raise ValueError("file_name must not contain null bytes")

    if "/" in file_name or "\\" in file_name or ".." in file_name:
        raise ValueError("file_name must not contain path separators or traversal sequences")

    if action in _ALLOWED_PERMISSIONS[user_role]:
        return f"Action permitted: {action}"

    return f"Action blocked: {action}"
