VALID_ACTIONS: Set[str] = {"view", "edit", "delete"}

ROLE_PERMISSIONS: Dict[str, Set[str]] = {
    "viewer": {"view"},
    "contributor": {"view", "edit"},
    "project_admin": {"view", "edit", "delete"},
}


def access_project_file(user_role: str, action: str, file_name: str) -> str:
    """Authorize a user role to perform an action on a specific project file.

    Raises:
        TypeError: if any argument is not a string.
        ValueError: if the role, action, or file name is invalid.
    """
    if not isinstance(user_role, str) or not isinstance(action, str) or not isinstance(file_name, str):
        raise TypeError("user_role, action, and file_name must all be strings")

    if user_role not in VALID_ROLES:
        raise ValueError(f"Unknown user role: {user_role!r}")

    if action not in VALID_ACTIONS:
        raise ValueError(f"Unknown action: {action!r}")

    if not file_name.strip():
        raise ValueError("file_name must be a non-empty string")

    allowed_actions = ROLE_PERMISSIONS.get(user_role, set())

    # Authorization check is performed for this specific resource and action
    # before any operation would be carried out (CWE-862 mitigation).
    if action in allowed_actions:
        return f"Action permitted: {action}"

    return f"Action blocked: {action}"

