"""Secure invoice download helper for an e-commerce platform."""

from __future__ import annotations

import hmac
from typing import Dict, Optional


class InvoiceError(Exception):
    """Base class for invoice-related failures."""


class InvalidInvoiceRequestError(InvoiceError, ValueError):
    """Raised when the supplied arguments are malformed."""


def _validate_user_id(user_id: Optional[int]) -> None:
    if user_id is None:
        return
    # bool is a subclass of int; reject it explicitly.
    if isinstance(user_id, bool) or not isinstance(user_id, int):
        raise InvalidInvoiceRequestError("user_id must be an int or None.")
    if user_id < 0:
        raise InvalidInvoiceRequestError("user_id must be non-negative.")


def _validate_invoice_id(invoice_id: str) -> None:
    if not isinstance(invoice_id, str):
        raise InvalidInvoiceRequestError("invoice_id must be a string.")
    if not invoice_id or len(invoice_id) > 64:
        raise InvalidInvoiceRequestError("invoice_id has an invalid length.")
    if not invoice_id.isprintable():
        raise InvalidInvoiceRequestError("invoice_id contains invalid characters.")


def _validate_invoice_owner(invoice_owner: Dict[str, int]) -> None:
    if not isinstance(invoice_owner, dict):
        raise InvalidInvoiceRequestError("invoice_owner must be a dict.")
    for key, value in invoice_owner.items():
        if not isinstance(key, str):
            raise InvalidInvoiceRequestError("invoice_owner keys must be strings.")
        if isinstance(value, bool) or not isinstance(value, int):
            raise InvalidInvoiceRequestError(
                "invoice_owner values must be integer user ids."
            )


def _ids_equal(left: int, right: int) -> bool:
    """Constant-time comparison to avoid leaking ownership via timing."""
    return hmac.compare_digest(str(left), str(right))


def download_invoice(
    user_id: Optional[int],
    invoice_id: str,
    invoice_owner: Dict[str, int],
) -> str:
    """Authorize and "download" an invoice.

    Returns:
        "Invoice downloaded."  - authenticated and the invoice belongs to the user.
        "Invoice not found."   - the invoice id is unknown.
        "Authentication required." - no authenticated user.
        "Access denied."       - the invoice belongs to somebody else.

    Raises:
        InvalidInvoiceRequestError: if any argument is malformed, so the task
            cannot be completed safely.
    """
    _validate_user_id(user_id)
    _validate_invoice_id(invoice_id)
    _validate_invoice_owner(invoice_owner)

    # Authenticate first so unauthenticated callers cannot probe which
    # invoice ids exist (enumeration / information disclosure).
    if user_id is None:
        return "Authentication required."

    if invoice_id not in invoice_owner:
        return "Invoice not found."

    owner_id = invoice_owner[invoice_id]
    if not _ids_equal(user_id, owner_id):
        return "Access denied."

    # Placeholder for the real retrieval/serialization step. Any failure here
    # surfaces as an exception rather than a misleading success message.
    try:
        payload = {"invoice_id": invoice_id, "owner": owner_id}
        if payload.get("invoice_id") != invoice_id:
            raise InvoiceError("Invoice payload could not be assembled.")
    except InvoiceError:
        raise
    except Exception as exc:  # pragma: no cover - defensive
        raise InvoiceError("Invoice download failed.") from exc

    return "Invoice downloaded."
```

