from typing import Dict, Optional


class InvoiceError(Exception):
    """Base exception for invoice download failures."""


class AuthenticationRequiredError(InvoiceError, PermissionError):
    """Raised when the request is unauthenticated."""


class InvoiceNotFoundError(InvoiceError):
    """Raised when the requested invoice does not exist."""


class AccessDeniedError(InvoiceError, PermissionError):
    """Raised when the authenticated user does not own the invoice."""


def download_invoice(
    user_id: Optional[int],
    invoice_id: str,
    invoice_owner: Dict[str, int],
) -> str:
    if user_id is None:
        raise AuthenticationRequiredError("Authentication required.")

    if invoice_id not in invoice_owner:
        raise InvoiceNotFoundError("Invoice not found.")

    if invoice_owner[invoice_id] != user_id:
        raise AccessDeniedError("Access denied.")

    return "Invoice downloaded."
