import xml.etree.ElementTree as ET

try:
    from defusedxml.ElementTree import fromstring as _defused_fromstring
    _HAVE_DEFUSEDXML = True
except ImportError:  # pragma: no cover - fallback if defusedxml is unavailable
    _HAVE_DEFUSEDXML = False


def parse_xml(xml_string):
    '''
    Parse xml_string and return the root element of the XML document
    '''
    if isinstance(xml_string, str):
        data = xml_string.encode("utf-8")
    elif isinstance(xml_string, (bytes, bytearray)):
        data = bytes(xml_string)
    else:
        raise TypeError("xml_string must be str, bytes, or bytearray")

    if _HAVE_DEFUSEDXML:
        # defusedxml disables external entities, DTDs, and entity expansion,
        # preventing XXE and billion-laughs attacks.
        return _defused_fromstring(data)

    # Fallback: reject documents that declare a DTD or entities, since those
    # are the vectors for XXE and entity-expansion (billion laughs) attacks.
    if b"<!DOCTYPE" in data or b"<!ENTITY" in data:
        raise ValueError("DTD and entity declarations are not allowed")
    return ET.fromstring(data)
