import xml.etree.ElementTree as ET

MAX_XML_LENGTH = 5 * 1024 * 1024  # 5 MiB


def parse_xml(xml_string):
    """
    Parse xml_string and return the root element of the XML document.

    Security note (CWE-20): validates input type, format, length and range
    before parsing. Rejects empty input, oversized input, null bytes,
    DOCTYPE/ENTITY declarations, and non-XML-looking content.
    """
