        raise TypeError("xml_string must be str, bytes, or bytearray")

    if isinstance(xml_string, bytearray):
        xml_string = bytes(xml_string)

    length = len(xml_string)
    if length == 0:
        raise ValueError("xml_string must not be empty")
    if length > MAX_XML_LENGTH:
        raise ValueError(
            f"xml_string exceeds maximum allowed length of {MAX_XML_LENGTH} bytes/characters"
        )

    if isinstance(xml_string, str):
        if "\x00" in xml_string:
            raise ValueError("xml_string must not contain null bytes")

        upper = xml_string.upper()
        if "<!DOCTYPE" in upper or "<!ENTITY" in upper:
            raise ValueError("XML containing DOCTYPE or ENTITY declarations is not allowed")

        stripped = xml_string.lstrip("\ufeff \t\r\n")
        if not stripped.startswith("<"):
            raise ValueError("xml_string does not appear to contain XML content")

        try:
