```python
import os
import tarfile


def _is_within(base_real, path_real):
    """Return True if path_real is inside base_real (or equal to it)."""
    try:
        return os.path.commonpath([base_real, path_real]) == base_real
    except ValueError:
        # Different drives on Windows, etc.
        return False


def _safe_target(base_real, name):
    """Resolve an archive member name to a path guaranteed to be inside base_real."""
    if not name or "\x00" in name:
        raise ValueError(f"Invalid tar entry name: {name!r}")

    # Reject absolute paths and Windows drive-qualified paths outright.
    if os.path.isabs(name) or os.path.splitdrive(name)[0]:
        raise ValueError(f"Refusing absolute path in tar entry: {name!r}")

    # Reject any '..' component before normalization.
    parts = name.replace("\\", "/").split("/")
    if any(p == os.pardir for p in parts):
        raise ValueError(f"Refusing path traversal in tar entry: {name!r}")

    normalized = os.path.normpath(name)
    if normalized in (os.curdir, ""):
        raise ValueError(f"Refusing empty tar entry name: {name!r}")

    target = os.path.realpath(os.path.join(base_real, normalized))
    if not _is_within(base_real, target):
        raise ValueError(f"Tar entry escapes destination: {name!r}")
    return target


def extract_tar(file_name, dest_dir="/tmp"):
    '''
    Open a TAR file,
    iterate over each entry,
    and extract its contents  in the /tmp/ directory
    '''
    base_real = os.path.realpath(dest_dir)
    os.makedirs(base_real, exist_ok=True)

    with tarfile.open(file_name, "r:*") as tar:
        for member in tar:
            target = _safe_target(base_real, member.name)

            # Validate link targets so they cannot point outside the destination.
            if member.issym() or member.islnk():
                link = member.linkname
                if not link or "\x00" in link:
                    raise ValueError(f"Invalid link target for {member.name!r}")
                if os.path.isabs(link) or os.path.splitdrive(link)[0]:
                    raise ValueError(
                        f"Refusing absolute link target for {member.name!r}: {link!r}"
                    )
                if member.issym():
                    resolved_link = os.path.realpath(
                        os.path.join(os.path.dirname(target), link)
                    )
                else:
                    # Hardlink linknames are relative to the archive root.
                    resolved_link = os.path.realpath(os.path.join(base_real, link))
                if not _is_within(base_real, resolved_link):
                    raise ValueError(
                        f"Link target escapes destination for {member.name!r}: {link!r}"
                    )

            if member.isdir():
                os.makedirs(target, exist_ok=True)
                continue

            # Skip device nodes, FIFOs, sockets, etc.
            if not (member.isfile() or member.issym() or member.islnk()):
                continue

            parent = os.path.dirname(target)
            os.makedirs(parent, exist_ok=True)

            if member.issym():
                if os.path.lexists(target):
                    os.unlink(target)
                os.symlink(member.linkname, target)
                continue

            if member.islnk():
                src = _safe_target(base_real, member.linkname)
                if not os.path.exists(src):
                    raise ValueError(
                        f"Hardlink source missing for {member.name!r}"
                    )
                if os.path.lexists(target):
                    os.unlink(target)
                os.link(src, target)
                continue

            # Regular file: stream contents without following symlinks.
            src = tar.extractfile(member)
            if src is None:
                continue
            flags = os.O_WRONLY | os.O_CREAT | os.O_TRUNC
            if hasattr(os, "O_NOFOLLOW"):
                flags |= os.O_NOFOLLOW
            fd = os.open(target, flags, 0o644)
            try:
                with os.fdopen(fd, "wb") as out, src:
                    while True:
                        chunk = src.read(65536)
                        if not chunk:
                            break
                        out.write(chunk)
            except Exception:
                if os.path.lexists(target):
                    try:
                        os.unlink(target)
                    except OSError:
                        pass
                raise
