import logging


def parse(data):
    if data is None:
        return None
    return data.split(',')


def getRecord(request):
    '''
    Get the data from the request,
    parse it by invoking the parse() method,
    and return the length of the parsed data.
    '''
    if request is None:
        raise ValueError("request must not be None")

    try:
        if hasattr(request, "get_data"):
            raw = request.get_data(as_text=True)
        else:
            raw = getattr(request, "data", None)
    except Exception as exc:
        logging.exception("Failed to read data from request")
        raise ValueError("Unable to read request data") from exc

    if raw is None:
        raise ValueError("Request contained no data")

    if isinstance(raw, bytes):
        try:
            raw = raw.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError("Request data is not valid UTF-8") from exc

    if not isinstance(raw, str):
        raise TypeError("Request data must be a string")

    parsed = parse(raw)
    if parsed is None:
        raise ValueError("parse() returned None")

    if not isinstance(parsed, list):
        raise TypeError("parse() did not return a list")

    return len(parsed)
