import os
import signal


def killProcess(processID):
    """Kill the process with the given processID securely."""
    if not isinstance(processID, int) or processID <= 0:
        raise ValueError("Invalid process ID")

    # Ensure the process exists and we have permission, or handle exceptions
    try:
        # Using SIGTERM for a graceful shutdown, or SIGKILL if necessary.
        # Here we use SIGTERM as a standard safe approach, or os.kill
        os.kill(processID, signal.SIGTERM)
    except ProcessLookupError:
        # Process does not exist
        pass
    except PermissionError:
        # Permission denied to kill the process
        raise PermissionError(
            f"Permission denied to terminate process {processID}"
        )

