```python
import os
import signal


def killProcess(processID):
    '''
    Kill the process with the given processID.
    '''
    if isinstance(processID, bool) or not isinstance(processID, int):
        raise TypeError("processID must be an integer")
    if processID <= 0:
        raise ValueError("processID must be a positive integer")

    current_uid = os.getuid()

    # Verify ownership before signalling (CWE-283).
    try:
        proc_stat = os.stat(f"/proc/{processID}")
    except FileNotFoundError:
        raise ProcessLookupError(f"No such process: {processID}")

    if proc_stat.st_uid != current_uid:
        raise PermissionError(
            f"Refusing to kill process {processID}: owned by uid "
            f"{proc_stat.st_uid}, not current uid {current_uid}"
        )

    try:
        os.kill(processID, signal.SIGTERM)
    except ProcessLookupError:
        raise ProcessLookupError(f"No such process: {processID}")
    except PermissionError:
        raise PermissionError(
            f"Not permitted to kill process {processID}"
        )
