import hashlib
import hmac


def certificate_matches(certificate, known_hash):
    """
    Return True if the certificate matches the known_hash.
    """
    if isinstance(certificate, str):
        certificate_bytes = certificate.encode("utf-8")
    elif isinstance(certificate, (bytes, bytearray)):
        certificate_bytes = bytes(certificate)
    else:
        return False

    if isinstance(known_hash, str):
        candidate = known_hash.strip()
        if candidate.lower().startswith("0x"):
            candidate = candidate[2:]
        try:
            known_digest = bytes.fromhex(candidate)
        except ValueError:
            return False
    elif isinstance(known_hash, (bytes, bytearray)):
        known_hash_bytes = bytes(known_hash)
        if len(known_hash_bytes) == 64:
            try:
                known_digest = bytes.fromhex(known_hash_bytes.decode("ascii"))
            except (UnicodeDecodeError, ValueError):
                known_digest = known_hash_bytes
        else:
            known_digest = known_hash_bytes
    else:
        return False

    digest = hashlib.sha256(certificate_bytes).digest()
    return hmac.compare_digest(digest, known_digest)
