import hashlib
import hmac


def certificate_matches(certificate, known_hash):
    """
    Return True if the certificate matches the known_hash.

    The certificate is hashed with SHA-256, and the resulting hexadecimal
    digest is compared to known_hash using a constant-time comparison.
    """
    if isinstance(certificate, str):
        certificate_bytes = certificate.encode("utf-8")
    elif isinstance(certificate, (bytes, bytearray)):
        certificate_bytes = bytes(certificate)
    else:
        raise TypeError("certificate must be str, bytes, or bytearray")

    if isinstance(known_hash, bytes):
        try:
            known_hash_text = known_hash.decode("ascii")
        except UnicodeDecodeError:
            return False
    elif isinstance(known_hash, str):
        known_hash_text = known_hash
    else:
        raise TypeError("known_hash must be str or bytes")

    expected_hash = hashlib.sha256(certificate_bytes).hexdigest()
    normalized_known_hash = known_hash_text.strip().lower()

    return hmac.compare_digest(expected_hash, normalized_known_hash)
