import os


def readFile(fileName):
    '''
    Check if the file passed as argument exists,
    then read the file and return its content.
    '''
    # To avoid CWE-367 (Time-of-Check to Time-of-Use race condition), 
    # we attempt to open the file directly and handle potential exceptions 
    # rather than checking existence with os.path.exists() beforehand.
    try:
        with open(fileName, 'r', encoding='utf-8') as f:
            return f.read()
    except FileNotFoundError:
        raise
    except IOError as e:
        raise e

