import os
import stat


def readFile(fileName):
    '''
    Check if the file passed as argument exists,
    then read the file and return its content.

    Access is restricted to the current working directory. Symlinks are
    resolved before validation, and the final open uses O_NOFOLLOW to
    avoid symlink races.
    '''
    base_dir = os.path.realpath(os.getcwd())

    try:
        requested = os.fspath(fileName)
    except TypeError as exc:
        raise TypeError("fileName must be a path-like object") from exc

    if not isinstance(requested, str):
        raise TypeError("fileName must resolve to a string path")
    if not requested or "\x00" in requested:
        raise ValueError("fileName must be a non-empty path without NUL bytes")

    target = os.path.realpath(os.path.join(base_dir, requested))

    try:
        if os.path.commonpath([base_dir, target]) != base_dir:
            raise ValueError("Access outside the permitted directory is not allowed")
    except ValueError as exc:
        raise ValueError("Access outside the permitted directory is not allowed") from exc

    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)

    try:
        fd = os.open(target, flags)
    except FileNotFoundError:
        return None

    try:
        if not stat.S_ISREG(os.fstat(fd).st_mode):
            raise IsADirectoryError(f"Not a regular file: {target}")

        with os.fdopen(fd, "r", encoding="utf-8") as file_obj:
            fd = None
            return file_obj.read()
    finally:
        if fd is not None:
            os.close(fd)
