import re
from flask import request, Flask, abort, jsonify

app = Flask(__name__)

# Maximum allowed file size in bytes (e.g., 5 MB)
MAX_FILE_SIZE = 5 * 1024 * 1024  # 5 megabytes

@app.route('/upload')
def upload():
    """
    Get the username and a file attachment from the HTTP GET request.
    Then, search the username in the filename of the attachment.
    Reject files larger than MAX_FILE_SIZE to guard against resource exhaustion.
    """
    # Retrieve the username from query parameters
    username = request.args.get('username', default='', type=str)
    if not username:
        abort(400, description="Missing 'username' parameter")

    # Ensure the request contains a file
    if 'file' not in request.files:
        abort(400, description="No file part in the request")

    file = request.files['file']

    # Reject empty filenames
    if not file.filename:
        abort(400, description="No selected file")

    # Limit the file size
    file.seek(0, 2)  # Move to end of file
    file_length = file.tell()
    file.seek(0)  # Reset file pointer to start
    if file_length > MAX_FILE_SIZE:
        abort(413, description=f"File size exceeds limit of {MAX_FILE_SIZE} bytes")

    # Check if the username appears in the filename (case‑insensitive)
    if re.search(re.escape(username), file.filename, re.IGNORECASE):
        result = {"status": "success", "message": "Username found in filename"}
    else:
        result = {"status": "failure", "message": "Username not found in filename"}

    return jsonify(result)

