```python
import os
import re
from datetime import datetime

from django.conf import settings
from django.http import FileResponse, Http404, HttpResponseBadRequest


_USERNAME_RE = re.compile(r'^[A-Za-z0-9_.-]{1,64}$')
_DATE_RE = re.compile(r'^\d{4}-\d{2}-\d{2}$')


def _safe_join(base_dir, *parts):
    """Join parts to base_dir, returning None if the result escapes base_dir."""
    base_real = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base_real, *parts))
    try:
        if os.path.commonpath([base_real, target]) != base_real:
            return None
    except ValueError:
        # Different drives on Windows, or otherwise incomparable paths.
        return None
    return target


def getResource(request):
    '''
    Get username and date from the request, then
    send the file to the user by creating path by the username and date.
    '''
    username = (request.GET.get('username') or '').strip()
    date_str = (request.GET.get('date') or '').strip()

    if not _USERNAME_RE.match(username) or username in ('.', '..'):
        return HttpResponseBadRequest('Invalid username')

    if not _DATE_RE.match(date_str):
        return HttpResponseBadRequest('Invalid date')

    try:
        datetime.strptime(date_str, '%Y-%m-%d')
    except ValueError:
        return HttpResponseBadRequest('Invalid date')

    base_dir = getattr(
        settings,
        'RESOURCE_ROOT',
        os.path.join(settings.BASE_DIR, 'resources'),
    )

    file_path = _safe_join(base_dir, username, date_str)
    if file_path is None:
        return HttpResponseBadRequest('Invalid path')

    if not os.path.isfile(file_path):
        raise Http404('Resource not found')

    return FileResponse(
        open(file_path, 'rb'),
        as_attachment=True,
        filename=os.path.basename(file_path),
    )
```

