```python
import os
import re
from datetime import datetime

from django.conf import settings
from django.http import (
    HttpResponse,
    HttpResponseBadRequest,
    HttpResponseForbidden,
    Http404,
)


def getResource(request):
    '''
    Get username and date from the request, then
    send the file to the user by creating path by the username and date.
    '''
    username = request.GET.get("username")
    date = request.GET.get("date")

    if not username or not date:
        return HttpResponseBadRequest("Missing username or date")

    # CWE-425: authorize every resource request, not just navigation.
    if not request.user.is_authenticated or request.user.get_username() != username:
        return HttpResponseForbidden("Not authorized")

    # Validate the date strictly to prevent path manipulation.
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", date):
        return HttpResponseBadRequest("Invalid date")

    try:
        datetime.strptime(date, "%Y-%m-%d")
    except ValueError:
        return HttpResponseBadRequest("Invalid date")

    # Validate username as a single safe path component.
    if (
        username in (".", "..")
        or "/" in username
        or "\\" in username
        or os.path.basename(username) != username
    ):
        return HttpResponseBadRequest("Invalid username")

    base_dir = os.path.realpath(
        getattr(settings, "RESOURCE_ROOT", settings.MEDIA_ROOT)
    )
    file_path = os.path.realpath(os.path.join(base_dir, username, date))

    # Ensure the resolved path remains inside the resource root.
    if os.path.commonpath([base_dir, file_path]) != base_dir:
        return HttpResponseForbidden("Not authorized")

    if not os.path.isfile(file_path):
        raise Http404("Resource not found")

    with open(file_path, "rb") as resource_file:
        response = HttpResponse(
            resource_file.read(),
            content_type="application/octet-stream",
        )

    response["Content-Disposition"] = (
        f'attachment; filename="{os.path.basename(file_path)}"'
    )
    return response
