import os
import uuid
from werkzeug.utils import secure_filename

app = Flask(__name__)

UPLOAD_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'uploads')
ALLOWED_EXTENSIONS = {'.pdf'}
ALLOWED_MIMETYPES = {'application/pdf', 'application/x-pdf'}
MAX_FILE_SIZE = 5 * 1024 * 1024  # 5 MB

app.config['MAX_CONTENT_LENGTH'] = MAX_FILE_SIZE


def _is_valid_pdf(file_storage):
    filename = file_storage.filename or ''
    ext = os.path.splitext(filename)[1].lower()
    if ext not in ALLOWED_EXTENSIONS:
        return False

    mimetype = (file_storage.mimetype or '').lower()
    if mimetype not in ALLOWED_MIMETYPES:
        return False

    header = file_storage.stream.read(5)
    file_storage.stream.seek(0)
    return header == b'%PDF-'


@app.route('/pdf/upload', methods=['POST'])
def upload_pdf():
    if 'file' not in request.files:
        abort(400, description='No file part in request')

    file = request.files['file']
    if not file or not file.filename:
        abort(400, description='No file selected')

    if not _is_valid_pdf(file):
        abort(400, description='Only valid PDF files are allowed')

    os.makedirs(UPLOAD_DIR, exist_ok=True)

    safe_name = secure_filename(file.filename)
    base, ext = os.path.splitext(safe_name)
    if not base:
        base = 'document'
    filename = f"{uuid.uuid4().hex}_{base}{ext.lower()}"

    destination = os.path.join(UPLOAD_DIR, filename)

    upload_root = os.path.abspath(UPLOAD_DIR)
    dest_abs = os.path.abspath(destination)
    if os.path.commonpath([upload_root, dest_abs]) != upload_root:
        abort(400, description='Invalid filename')

    file.save(destination)
    return redirect('/pdf/view')

