def admin_access(request):
    global HAS_ADMIN_ACCESS
    # Assuming request is a dictionary-like object or has a get_json() method / form data.
    # We will safely handle standard dictionary or Flask-like request objects.
    if hasattr(request, 'form') and request.form:
        username = request.form.get('username')
        password = request.form.get('password')
    elif hasattr(request, 'json') and request.json:
        username = request.json.get('username')
        password = request.json.get('password')
    elif isinstance(request, dict):
        username = request.get('username')
        password = request.get('password')
    else:
        username = None
        password = None

    # Simple hardcoded validation for demonstration purposes
    if username == 'admin' and password == 'adminpassword':
        HAS_ADMIN_ACCESS = True
    else:
        HAS_ADMIN_ACCESS = False

    return HAS_ADMIN_ACCESS

