import io
import pickle


class _SafeUnpickler(pickle.Unpickler):
    """Unpickler that only permits inert built-in data types."""

    _SAFE_BUILTINS = {
        "dict", "list", "tuple", "set", "frozenset",
        "int", "float", "complex", "bool", "str", "bytes", "bytearray",
        "NoneType", "object",
    }

    _SAFE_MODULES = {"builtins", "__builtin__", "collections"}

    def find_class(self, module, name):
        if module in self._SAFE_MODULES and name in self._SAFE_BUILTINS:
            return super().find_class(module, name)
        raise pickle.UnpicklingError(
            f"Refusing to deserialize disallowed global: {module}.{name}"
        )


def getPickleData(pickled):
    '''
    Return deserialized data.

    Deserialization is restricted to inert built-in containers and
    primitives so that a malicious payload cannot execute arbitrary code.
    '''
    if isinstance(pickled, str):
        pickled = pickled.encode("latin-1")
    if not isinstance(pickled, (bytes, bytearray)):
        raise TypeError("pickled data must be bytes or bytearray")

    return _SafeUnpickler(io.BytesIO(pickled)).load()
