# Database configuration
# ------------------------------------------------------------------------------

# Use the DATABASE_URL environment variable if available, otherwise default to SQLite.
DATABASE_URL = os.getenv("DATABASE_URL")

if DATABASE_URL:
    # Parse the DATABASE_URL using dj_database_url or a custom parser
    # Example with dj_database_url:
    import dj_database_url
    DATABASES = {
        "default": dj_database_url.parse(DATABASE_URL, conn_max_age=600)
    }
else:
    # Fallback to a local SQLite database
    DATABASES = {
        "default": {
            "ENGINE": "django.db.backends.sqlite3",
            "NAME": BASE_DIR / "db.sqlite3",
        }
    }

# ------------------------------------------------------------------------------
# Password validation
# ------------------------------------------------------------------------------

AUTH_PASSWORD_VALIDATORS = [
    {
        "NAME": "django.contrib.auth.password_validation.UserAttributeSimilarityValidator",
    },
    # Enforce a minimum password length of 12 characters
    {
        "NAME": "django.contrib.auth.password_validation.MinimumLengthValidator",
        "OPTIONS": {
            "min_length": 12,
        },
    },
    # Reject commonly used passwords
    {
        "NAME": "django.contrib.auth.password_validation.CommonPasswordValidator",
    },
    # Enforce password complexity (digits, uppercase, lowercase, symbols)
    {
        "NAME": "django.contrib.auth.password_validation.NumericPasswordValidator",
    },
]

# Note: The NumericPasswordValidator ensures at least one digit; for full
# complexity you may add a custom validator or use third‑party packages.
