import os
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent.parent

# Database configuration.
# Credentials are read from environment variables so secrets are never
# committed to source control. Only use the SQLite fallback for local dev.
DATABASES = {
    "default": {
        "ENGINE": os.environ.get("DB_ENGINE", "django.db.backends.sqlite3"),
        "NAME": os.environ.get("DB_NAME", str(BASE_DIR / "db.sqlite3")),
        "USER": os.environ.get("DB_USER", ""),
        "PASSWORD": os.environ.get("DB_PASSWORD", ""),
        "HOST": os.environ.get("DB_HOST", ""),
        "PORT": os.environ.get("DB_PORT", ""),
        "CONN_MAX_AGE": int(os.environ.get("DB_CONN_MAX_AGE", "60")),
        "OPTIONS": {
            # Enforce TLS for production database connections when applicable.
            **(
                {"sslmode": os.environ.get("DB_SSLMODE", "require")}
                if os.environ.get("DB_ENGINE", "").endswith("postgresql")
                else {}
            ),
        },
    }
}

# Never let Django silently create test databases on a production host.
if os.environ.get("DJANGO_ENV", "development") == "production":
    DATABASES["default"]["TEST"] = {"NAME": None}
