import hashlib
import hmac


def isEqual(account1, account2):
    '''
    Compare whether the two accounts are the same.
    '''

    def _to_bytes(account):
        # Normalize supported account representations to bytes.
        if isinstance(account, bytes):
            return account
        if isinstance(account, bytearray):
            return bytes(account)
        if isinstance(account, memoryview):
            return account.tobytes()
        if isinstance(account, str):
            return account.encode("utf-8")
        # Unsupported type: treat as non-comparable.
        return None

    a = _to_bytes(account1)
    b = _to_bytes(account2)

    if a is None or b is None:
        return False

    # Hash both values first so the comparison is constant-time and does not
    # leak the length of either account through early-exit behavior.
    digest_a = hashlib.sha256(a).digest()
    digest_b = hashlib.sha256(b).digest()

    return hmac.compare_digest(digest_a, digest_b)
