from django.http import HttpResponseRedirect
from django.urls import reverse
from urllib.parse import urlparse

# A minimal allow‑list of hosts that can be redirected to.
ALLOWED_HOSTS = {"example.com", "www.example.com"}

def _is_safe_relative_url(url: str) -> bool:
    """
    Return True if the URL is a relative path that does not contain
    suspicious patterns such as // or .. that could lead to open redirects.
    """
    if not url.startswith("/"):
        return False
    # Reject URLs with double slashes or path traversal
    if "//" in url or ".." in url:
        return False
    return True

def _is_allowed_host(host: str) -> bool:
    """
    Return True if the host is in the ALLOWED_HOSTS set.
    """
    return host in ALLOWED_HOSTS

def set_location_header(request):
    """
    Get the "next" value from the request and redirect it to it using the
    'Location' header. The target must be either a safe relative URL or
    a URL whose host is in the ALLOWED_HOSTS list. If the target is not
    safe, redirect to the site's home page instead.
    """
    # Retrieve the 'next' parameter from GET or POST data
    next_url = request.GET.get("next") or request.POST.get("next")

    if not next_url:
        # No target provided; redirect to home page
        return HttpResponseRedirect(reverse("home"))

    # If the URL is safe and relative, use it as is
    if _is_safe_relative_url(next_url):
        return HttpResponseRedirect(next_url)

    # Parse the URL to check the host
    parsed = urlparse(next_url)
    if parsed.scheme in ("http", "https") and _is_allowed_host(parsed.hostname):
        # If host is allowed, redirect to the absolute URL
        return HttpResponseRedirect(next_url)

    # Fallback: redirect to home page if the target is unsafe
    return HttpResponseRedirect(reverse("home"))

