from django.http import HttpResponseRedirect
from django.utils.http import url_has_allowed_host_and_scheme


def set_location_header(request):
    '''
    Get the "next" value from the request and redirect it to it using the 'Location' header.
    '''
    next_url = request.GET.get('next') or request.POST.get('next') or ''

    # Prevent open-redirect vulnerabilities: only allow safe, same-host URLs.
    if next_url and url_has_allowed_host_and_scheme(
        url=next_url,
        allowed_hosts={request.get_host()},
        require_https=request.is_secure(),
    ):
        return HttpResponseRedirect(next_url)

    # Fallback to a safe default when "next" is missing or untrusted.
    return HttpResponseRedirect('/')

