    Security note (CWE-601): Only relative paths or hosts in an allow-list
    are permitted. Raw user-supplied URLs are never redirected to directly.
    """
    next_url = request.GET.get("next") or request.POST.get("next") or ""
    next_url = next_url.strip()

    if not next_url:
        return HttpResponse("Missing redirect target", status=400)

    allowed_hosts = set(getattr(settings, "ALLOWED_REDIRECT_HOSTS", ()))

    try:
        host = request.get_host()
        allowed_hosts.add(host)
        # Also allow the host without a port, if present.
        allowed_hosts.add(host.rsplit(":", 1)[0])
    except Exception:
        pass

    if not url_has_allowed_host_and_scheme(
        url=next_url,
        allowed_hosts=allowed_hosts,
        require_https=request.is_secure(),
    ):
        return HttpResponse("Invalid redirect target", status=400)

