import xml.sax
from xml.sax.handler import ContentHandler, feature_external_ges, feature_external_pes


class _RootElement:
    __slots__ = ("tag", "attrib", "children")

    def __init__(self, tag, attrib):
        self.tag = tag
        self.attrib = attrib
        self.children = []

    def __repr__(self):
        return f"_RootElement(tag={self.tag!r}, attrib={self.attrib!r}, children={self.children!r})"


class _TreeBuilder(ContentHandler):
    def __init__(self):
        super().__init__()
        self.root = None
        self._stack = []

    def startElement(self, name, attrs):
        element = _RootElement(name, dict(attrs))
        if self._stack:
            self._stack[-1].children.append(element)
        else:
            self.root = element
        self._stack.append(element)

    def endElement(self, name):
        self._stack.pop()


def get_root():
    '''
    Create an XML parser,
    parse the file 'resources/config.xml' and return the parsed result.
    '''
    parser = xml.sax.make_parser()

    # Harden the parser: disable external entity resolution (XXE) and
    # external parameter entities.
    for feature in (feature_external_ges, feature_external_pes):
        try:
            parser.setFeature(feature, False)
        except (xml.sax.SAXNotSupportedException, xml.sax.SAXNotRecognizedException):
            pass

    builder = _TreeBuilder()
    parser.setContentHandler(builder)

    with open("resources/config.xml", "rb") as config_file:
        parser.parse(config_file)

    return builder.root

