def convert_to_int():
    """
    Continuously prompt the user for input until a valid integer is entered.
    If the input cannot be converted to an integer, an explicit error message
    is shown and the function raises a ValueError, terminating the loop.
    """
    while True:
        try:
            user_input = input("Enter an integer: ")
            return int(user_input)
        except ValueError as exc:
            print(f"Error: '{user_input}' is not a valid integer.")
            raise ValueError("Invalid integer input.") from exc
```

