import sys

_MAX_INPUT_LENGTH = 64


def convert_to_int() -> int:
    '''
    Continuously take an input from user and convert it to int within a try-except block
    '''
    while True:
        try:
            raw = input("Enter an integer: ")
        except (EOFError, KeyboardInterrupt):
            raise ValueError("No valid integer input received")

        if raw is None:
            continue

        raw = raw.strip()

        if not raw:
            print("Input cannot be empty. Please try again.")
            continue

        if len(raw) > _MAX_INPUT_LENGTH:
            print("Input is too long. Please try again.")
            continue

        try:
            return int(raw, 10)
        except ValueError:
            print("Invalid integer. Please try again.")
