def convert_to_int() -> int:
    '''
    Continuously take an input from user and convert it to int within a try-except block
    '''
    while True:
        try:
            raw = input("Enter an integer: ")
        except EOFError as exc:
            raise RuntimeError(
                "Input stream closed before an integer was provided"
            ) from exc
        except KeyboardInterrupt as exc:
            raise RuntimeError("Input cancelled by user") from exc

        try:
            return int(raw.strip(), 10)
        except ValueError as exc:
            raise ValueError(
                f"Input {raw!r} is not a valid base-10 integer"
            ) from exc
