def getFibonacci(n):
    """
    Compute the n-th Fibonacci number (0-indexed) using an iterative loop.
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

