```python
def find_median_sorted_arrays(nums1, nums2):
    if not isinstance(nums1, (list, tuple)) or not isinstance(nums2, (list, tuple)):
        raise TypeError("nums1 and nums2 must be lists or tuples of numbers")

    if not nums1 and not nums2:
        raise ValueError("Cannot find the median of two empty arrays")

    # Ensure nums1 is the smaller array so the binary search runs in
    # O(log(min(m, n))) time and O(1) extra space. This avoids the
    # memory-exhaustion (DoS) risk of materialising a merged list.
    if len(nums1) > len(nums2):
        nums1, nums2 = nums2, nums1

    m, n = len(nums1), len(nums2)
    total = m + n
    half = (total + 1) // 2

    lo, hi = 0, m
    while lo <= hi:
        i = (lo + hi) // 2
        j = half - i

        left1 = nums1[i - 1] if i > 0 else float("-inf")
        right1 = nums1[i] if i < m else float("inf")
        left2 = nums2[j - 1] if j > 0 else float("-inf")
        right2 = nums2[j] if j < n else float("inf")

        if left1 <= right2 and left2 <= right1:
            if total % 2 == 1:
                return max(left1, left2)
            return (max(left1, left2) + min(right1, right2)) / 2.0
        elif left1 > right2:
            hi = i - 1
        else:
            lo = i + 1

    raise ValueError("Input arrays must be sorted")
