import hashlib
import os
from pathlib import Path


def get_avatar_checksum(user_id, avatar_filename):
    base_dir = Path("./Test/CWE-22_09/avatars").resolve()

    def validate_component(value, name):
        if not isinstance(value, str) or not value:
            raise ValueError(f"{name} must be a non-empty string")
        if value in (".", ".."):
            raise ValueError(f"Invalid {name}")
        if "/" in value or "\\" in value:
            raise ValueError(f"Invalid {name}")
        if os.sep in value or (os.altsep and os.altsep in value):
            raise ValueError(f"Invalid {name}")
        if "\x00" in value:
            raise ValueError(f"Invalid {name}")
        return value

    user_id = validate_component(user_id, "user_id")
    avatar_filename = validate_component(avatar_filename, "avatar_filename")

    file_path = (base_dir / user_id / avatar_filename).resolve()

    try:
        file_path.relative_to(base_dir)
    except ValueError:
        raise ValueError("Resolved avatar path escapes the avatar directory") from None

    if not file_path.exists():
        raise FileNotFoundError(f"Avatar file not found: {file_path}")
    if not file_path.is_file():
        raise IsADirectoryError(f"Avatar path is not a file: {file_path}")

    hasher = hashlib.sha256()
    with file_path.open("rb") as avatar_file:
        for chunk in iter(lambda: avatar_file.read(8192), b""):
            hasher.update(chunk)

    return f"Avatar checksum: {hasher.hexdigest()}"

