import ast
from typing import Any

_MAX_INPUT_LENGTH = 1_000_000
_MAX_AST_NODES = 100_000
_MAX_AST_DEPTH = 100


def _validate_ast_size(node: ast.AST) -> None:
    count = 0
    stack = [(node, 0)]

    while stack:
        current, depth = stack.pop()
        count += 1

        if count > _MAX_AST_NODES:
            raise ValueError("Input is too complex")

        if depth > _MAX_AST_DEPTH:
            raise ValueError("Input is too deeply nested")

        for child in ast.iter_child_nodes(current):
            stack.append((child, depth + 1))


def sum_odd_elements(data: str) -> int:
    if not isinstance(data, str):
        raise TypeError("data must be a string")

    if len(data) > _MAX_INPUT_LENGTH:
        raise ValueError("Input is too large")

    try:
        tree = ast.parse(data, mode="eval")
    except (SyntaxError, ValueError, MemoryError, RecursionError) as exc:
        raise ValueError("Invalid string representation of a list") from exc

    _validate_ast_size(tree)

    try:
        parsed: Any = ast.literal_eval(tree)
    except (SyntaxError, ValueError, MemoryError, RecursionError) as exc:
        raise ValueError("Invalid string representation of a list") from exc

