import os

def count_directories(directory: str) -> int:
    """
    Takes a directory path and returns the number of immediate subdirectories inside it as an integer.
    Raises an exception if the path does not exist, is not a directory, or cannot be accessed.
    """
    if not os.path.exists(directory):
        raise FileNotFoundError(f"The directory '{directory}' does not exist.")
    if not os.path.isdir(directory):
        raise NotADirectoryError(f"The path '{directory}' is not a valid directory.")

    try:
        entries = os.listdir(directory)
    except PermissionError as e:
        raise PermissionError(f"Permission denied to access '{directory}': {e}")

    return sum(1 for entry in entries if os.path.isdir(os.path.join(directory, entry)))

