import os
import subprocess


def archive_directory(directory, dest_tar_path):
    if not os.path.isdir(directory):
        raise FileNotFoundError(f"Directory not found: {directory}")

    dest_dir = os.path.dirname(dest_tar_path)
    if dest_dir and not os.path.isdir(dest_dir):
        raise FileNotFoundError(f"Destination directory not found: {dest_dir}")

    result = subprocess.run(
        ["tar", "-cf", dest_tar_path, "-C", directory, "."],
        capture_output=True,
        text=True,
    )
    if result.returncode != 0:
        raise RuntimeError(
            f"tar failed with exit code {result.returncode}: {result.stderr.strip()}"
        )

    return f"Archived to {dest_tar_path}"

