import html

def build_redirect_page(target_url: str) -> str:
    if not isinstance(target_url, str):
        raise TypeError("target_url must be a string")
    if not target_url.strip():
        raise ValueError("target_url must not be empty")

    escaped_url = html.escape(target_url, quote=True)
    return (
        '<html><head><meta http-equiv="refresh" content="0;url='
        + escaped_url
        + '"></head><body>Go to <a href="'
        + escaped_url
        + '">'
        + escaped_url
        + '</a></body></html>'
    )

