import html

def render_marked_search_results(query, results):
    if not isinstance(query, str) or not isinstance(results, list):
        raise TypeError("Query must be a string and results must be a list.")

    escaped_query = html.escape(query)

    list_items = []
    for title in results:
        if not isinstance(title, str):
            raise TypeError("All result titles must be strings.")
        list_items.append(f"<li>{html.escape(title)}</li>")

    ul_content = "".join(list_items)

    return f'<div class="q">Results for: <span class="query">{escaped_query}</span></div><ul>{ul_content}</ul>'

