```python
def evaluate_expression(expression):
    if not isinstance(expression, str):
        raise TypeError("expression must be a string")

    s = expression
    n = len(s)
    pos = 0

    prec = {"+": 1, "-": 1, "*": 2, "/": 2, "u+": 3, "u-": 3}

    output = []
    ops = []
    expect_operand = True

    def skip_whitespace():
        nonlocal pos
        while pos < n and s[pos].isspace():
            pos += 1

    skip_whitespace()
    if pos >= n:
        raise ValueError("empty expression")

    while True:
        skip_whitespace()
        if pos >= n:
            break
        char = s[pos]

        if "0" <= char <= "9":
            if not expect_operand:
                raise ValueError(f"unexpected character: {char!r}")
            start = pos
            while pos < n and "0" <= s[pos] <= "9":
                pos += 1
            output.append(("num", int(s[start:pos])))
            expect_operand = False

        elif char == "(":
            if not expect_operand:
                raise ValueError(f"unexpected character: {char!r}")
            ops.append("(")
            pos += 1
            expect_operand = True

        elif char == ")":
            if expect_operand:
                raise ValueError(f"unexpected character: {char!r}")
            while ops and ops[-1] != "(":
                output.append(("op", ops.pop()))
            if not ops:
                raise ValueError(f"unexpected character: {char!r}")
            ops.pop()
            pos += 1
            expect_operand = False

        elif char in "+-":
            if expect_operand:
                ops.append("u" + char)
            else:
                while ops and ops[-1] != "(" and prec[ops[-1]] >= prec[char]:
                    output.append(("op", ops.pop()))
                ops.append(char)
            pos += 1
            expect_operand = True

        elif char in "*/":
            if expect_operand:
                raise ValueError(f"unexpected character: {char!r}")
            while ops and ops[-1] != "(" and prec[ops[-1]] >= prec[char]:
                output.append(("op", ops.pop()))
            ops.append(char)
            pos += 1
            expect_operand = True

        else:
            raise ValueError(f"unexpected character: {char!r}")

