import ast
import operator

# Mapping of AST operator nodes to actual Python functions
_OPERATORS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.Pow: operator.pow,
}

def _eval(node):
    """Recursively evaluate an AST node representing a numeric expression."""
    if isinstance(node, ast.Num):  # Python <3.8
        return node.n
    if isinstance(node, ast.Constant):  # Python 3.8+
        if isinstance(node.value, (int, float)):
            return node.value
        raise ValueError(f"Unsupported constant type: {type(node.value).__name__}")
    if isinstance(node, ast.BinOp):
        left = _eval(node.left)
        right = _eval(node.right)
        op_type = type(node.op)
        if op_type in _OPERATORS:
            return _OPERATORS[op_type](left, right)
        raise ValueError(f"Unsupported binary operator: {op_type.__name__}")
    if isinstance(node, ast.UnaryOp):
        operand = _eval(node.operand)
        if isinstance(node.op, ast.UAdd):
            return +operand
        if isinstance(node.op, ast.USub):
            return -operand
        raise ValueError(f"Unsupported unary operator: {type(node.op).__name__}")
    if isinstance(node, ast.Expression):
        return _eval(node.body)
    if isinstance(node, ast.Paren):
        return _eval(node.value)
    raise ValueError(f"Unsupported expression: {ast.dump(node)}")

def execute_command(command: str):
    """
    Evaluate a simple arithmetic expression given as a string.

    Parameters
    ----------
    command : str
        A string containing digits, whitespace, '+', '-', '*', '/', and parentheses.

    Returns
    -------
    numeric
        The numeric result of evaluating the expression.

    Raises
    ------
    ValueError
        If the expression contains unsupported syntax or operations.
    ZeroDivisionError
        If division by zero occurs.
    """
    try:
        expr_ast = ast.parse(command, mode='eval')
    except SyntaxError as exc:
        raise ValueError(f"Invalid syntax in command: {command}") from exc

    return _eval(expr_ast)

