def execute_command(command: str) -> float:
    """
    Takes a string representing an arithmetic expression and returns its numeric result.
    Uses eval safely restricted to mathematical operations, or a parser. 
    Since standard eval with restriction or AST parsing is needed, we can use ast.literal_eval 
    (though it doesn't support operators directly) or a safe subset evaluation.
    Actually, a standard way to evaluate math expressions safely in Python without 
    arbitrary code execution is using `ast.parse` and evaluating node types, 
    or using `eval` with restricted globals/locals.
    """
    import ast
    import operator

    # Supported operators
    operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
    }

    def _eval(node):
        if isinstance(node, ast.Constant): # Number
            if isinstance(node.value, (int, float)):
                return node.value
            raise TypeError(f"Unsupported constant type: {type(node.value)}")
        elif isinstance(node, ast.Num): # For older python compatibility
            return node.n
        elif isinstance(node, ast.BinOp): # Left op Right
            if type(node.op) in operators:
                return operators[type(node.op)](_eval(node.left), _eval(node.right))
            raise TypeError(f"Unsupported operator: {type(node.op)}")
        elif isinstance(node, ast.UnaryOp): # op Operand
            if type(node.op) in operators:
                return operators[type(node.op)](_eval(node.operand))
            raise TypeError(f"Unsupported unary operator: {type(node.op)}")
        elif isinstance(node, ast.Expression):
            return _eval(node.body)
        else:
            raise TypeError(f"Unsupported expression structure: {type(node)}")

    try:
        tree = ast.parse(command.strip(), mode='eval')
        return _eval(tree)
    except Exception as e:
        raise ValueError(f"Could not successfully evaluate expression: {command}") from e

