def calculate_submatrix_sum(matrix, row1, col1, row2, col2, k):
    if not isinstance(matrix, list):
        raise TypeError("matrix must be a list of lists")
    if not matrix:
        raise ValueError("matrix must be non-empty")

    if not all(isinstance(row, list) for row in matrix):
        raise TypeError("each row of matrix must be a list")
    if any(len(row) == 0 for row in matrix):
        raise ValueError("matrix rows must be non-empty")

    width = len(matrix[0])
    if any(len(row) != width for row in matrix):
        raise ValueError("matrix must be rectangular")

    for value in (row1, col1, row2, col2, k):
        if not isinstance(value, int):
            raise TypeError("row1, col1, row2, col2, and k must be integers")

    for row in matrix:
        for value in row:
            if not isinstance(value, int):
                raise TypeError("matrix elements must be integers")

    if row1 < 0 or col1 < 0 or row2 < 0 or col2 < 0:
        raise ValueError("submatrix coordinates must be non-negative")
    if row1 > row2 or col1 > col2:
        raise ValueError("top-left corner must be above and to the left of bottom-right corner")
    if row2 >= len(matrix) or col2 >= width:
        raise ValueError("submatrix coordinates are out of bounds")

    total = 0
    for r in range(row1, row2 + 1):
        for c in range(col1, col2 + 1):
            total += matrix[r][c]

    return total == k

