        raise TypeError("age must be an integer")
    if not isinstance(num_tickets, int) or isinstance(num_tickets, bool):
        raise TypeError("num_tickets must be an integer")
    if age < 0:
        raise ValueError("age must be non-negative")
    if num_tickets <= 0:
        raise ValueError("num_tickets must be a positive integer")

    if age < 12:
        price = 20
    elif age < 65:
        price = 50
    else:
        price = 40

    total = price * num_tickets

    if 5 <= num_tickets <= 9:
        total = total * 95 // 100
    elif num_tickets >= 10:
        total = total * 90 // 100

    return int(total)

