import os


def save_firmware_blob(blob_name, blob_bytes, upload_dir):
    if not isinstance(blob_name, str) or not blob_name:
        raise ValueError("blob_name must be a non-empty string")
    if "\x00" in blob_name:
        raise ValueError("invalid blob_name")

    if not isinstance(blob_bytes, (bytes, bytearray)):
        raise TypeError("blob_bytes must be bytes or bytearray")
    if len(blob_bytes) > 256 * 1024:
        raise ValueError("blob_bytes exceeds maximum allowed size of 256KB")
    if len(blob_bytes) < 4 or bytes(blob_bytes[:4]) != b"FWR1":
        raise ValueError("firmware blob must start with magic header b'FWR1'")

    safe_name = os.path.basename(blob_name.replace("\\", "/"))
    if not safe_name or safe_name in (".", "..") or "\x00" in safe_name:
        raise ValueError("invalid blob_name")

    if len(safe_name) <= len(".bin"):
        raise ValueError("blob_name must end with '.bin'")
    if not safe_name.lower().endswith(".bin"):
        raise ValueError("blob_name must end with '.bin'")
    last_ext = safe_name.rsplit(".", 1)[-1]
    if last_ext.lower() != "bin":
        raise ValueError("blob_name must end with '.bin' (double extensions rejected)")

    upload_dir_abs = os.path.abspath(upload_dir)
    upload_dir_real = os.path.realpath(upload_dir_abs)
    os.makedirs(upload_dir_real, exist_ok=True)
    if not os.path.isdir(upload_dir_real):
        raise ValueError("upload_dir must be a directory")

    full_path = os.path.abspath(os.path.join(upload_dir_abs, safe_name))
    resolved_full_path = os.path.realpath(full_path)
    secure_path = os.path.join(upload_dir_real, safe_name)

    try:
        common = os.path.commonpath(
            [os.path.normcase(upload_dir_real), os.path.normcase(resolved_full_path)]
        )
    except ValueError:
        raise ValueError("path traversal detected")

    if (
        common != os.path.normcase(upload_dir_real)
        or os.path.normcase(resolved_full_path) == os.path.normcase(upload_dir_real)
    ):
        raise ValueError("path traversal detected")

    data = bytes(blob_bytes)
    flags = os.O_WRONLY | os.O_CREAT | os.O_TRUNC
    flags |= getattr(os, "O_NOFOLLOW", 0)
    flags |= getattr(os, "O_BINARY", 0)
    flags |= getattr(os, "O_CLOEXEC", 0)

    fd = None
    dir_fd = None
    try:
        try:
            dir_fd = os.open(
                upload_dir_real,
                os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
            )
            fd = os.open(safe_name, flags, 0o600, dir_fd=dir_fd)
        except (TypeError, NotImplementedError):
            if dir_fd is not None:
                os.close(dir_fd)
                dir_fd = None
            fd = os.open(secure_path, flags, 0o600)
        finally:
            if dir_fd is not None:
                os.close(dir_fd)
                dir_fd = None

        with os.fdopen(fd, "wb") as f:
            fd = None
            f.write(data)
    finally:
        if fd is not None:
            try:
                os.close(fd)
            except OSError:
                pass

    return f"Firmware stored at {full_path}"
