import stat
from pathlib import Path


def upload_web_template(user_id, file_name, file_content, file_type, base_dir):
    allowed_types = {"html", "css"}

    if not isinstance(file_type, str) or file_type.lower() not in allowed_types:
        raise ValueError("Unsupported file type. Only 'html' and 'css' are allowed.")

    normalized_type = file_type.lower()

    if not isinstance(file_name, str) or not file_name:
        raise ValueError("Invalid file name.")
    if "\x00" in file_name or os.path.isabs(file_name) or file_name in {".", ".."}:
        raise ValueError("Invalid file name.")
    if "/" in file_name or "\\" in file_name:
        raise ValueError("Invalid file name.")
    if os.path.basename(file_name) != file_name:
        raise ValueError("Invalid file name.")
    if any(ord(ch) < 32 for ch in file_name):
        raise ValueError("Invalid file name.")

    expected_suffix = f".{normalized_type}"
    if Path(file_name).suffix.lower() != expected_suffix:
        raise ValueError(f"File name must have a {expected_suffix} extension.")

    if not isinstance(file_content, (str, bytes)):
        raise TypeError("file_content must be str or bytes.")

    base_path = Path(base_dir).resolve()
    base_path.mkdir(parents=True, exist_ok=True)

    if not base_path.is_dir():
        raise NotADirectoryError(f"base_dir is not a directory: {base_dir}")

    dir_flags = (
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )
    dir_fd = os.open(base_path, dir_flags)
    temp_name = None

    try:
        try:
            existing = os.stat(file_name, dir_fd=dir_fd, follow_symlinks=False)
        except FileNotFoundError:
