import base64
import json

def load_user_preferences(prefs_string):
    try:
        decoded_bytes = base64.b64decode(prefs_string, validate=True)
        decoded_str = decoded_bytes.decode('utf-8')
        preferences = json.loads(decoded_str)
        if not isinstance(preferences, dict):
            raise ValueError("Decoded JSON is not a dictionary.")
        return preferences
    except Exception as e:
        raise ValueError(f"Failed to load user preferences: {e}")

