import base64
import json


def load_user_preferences(prefs_string):
    if not isinstance(prefs_string, str):
        raise TypeError("prefs_string must be a base64-encoded string")

    try:
        decoded_bytes = base64.b64decode(prefs_string, validate=True)
    except Exception as exc:
        raise ValueError("Invalid base64-encoded string") from exc

    try:
        decoded_str = decoded_bytes.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ValueError("Decoded content is not valid UTF-8") from exc

    try:
        preferences = json.loads(decoded_str)
    except json.JSONDecodeError as exc:
        raise ValueError("Decoded content is not valid JSON") from exc

    if not isinstance(preferences, dict):
        raise ValueError("Decoded JSON must represent an object (dictionary)")

    return preferences

