import base64
import struct

def parse_sensor_data(sensor_data):
    try:
        decoded_bytes = base64.b64decode(sensor_data)
    except Exception as e:
        raise ValueError("Invalid base64 encoding") from e

    if len(decoded_bytes) != 12:
        raise ValueError("Decoded data must be exactly 12 bytes long")

    try:
        temperature, humidity_float, pressure_float = struct.unpack('>fff', decoded_bytes)
    except Exception as e:
        raise ValueError("Failed to unpack binary data") from e

    humidity = int(round(humidity_float))
    pressure = int(round(pressure_float))

    if not (0 <= humidity <= 100):
        raise ValueError("Humidity must be between 0 and 100 inclusive")

    if pressure <= 0:
        raise ValueError("Pressure must be a positive integer")

    return {
        'temperature': float(temperature),
        'humidity': humidity,
        'pressure': pressure
    }

