def handle_network_packet(packet_data: bytes, buffer: bytearray, offset: int) -> bytearray:
    if not isinstance(packet_data, bytes):
        raise TypeError("packet_data must be bytes")
    if not isinstance(buffer, bytearray):
        raise TypeError("buffer must be bytearray")
    if not isinstance(offset, int):
        raise TypeError("offset must be an integer")

    if offset < 0:
        raise ValueError("offset cannot be negative")

    end_position = offset + len(packet_data)
    if end_position > len(buffer):
        raise ValueError("packet data exceeds buffer size")

    buffer[offset:end_position] = packet_data
    return buffer

