def handle_network_packet(packet_data, buffer, offset):
    if not isinstance(packet_data, (bytes, bytearray)):
        raise TypeError("packet_data must be a bytes object")
    if not isinstance(buffer, bytearray):
        raise TypeError("buffer must be a bytearray")
    if not isinstance(offset, int) or isinstance(offset, bool):
        raise TypeError("offset must be an integer")
    if offset < 0:
        raise ValueError("offset must be non-negative")
    end = offset + len(packet_data)
    if end > len(buffer):
        raise ValueError(
            f"packet_data of length {len(packet_data)} does not fit in buffer "
            f"of length {len(buffer)} at offset {offset}"
        )
    buffer[offset:end] = packet_data
    return buffer

