from typing import Optional, Dict

_MISSING = object()


def download_invoice(
    user_id: Optional[int],
    invoice_id: str,
    invoice_owner: Dict[str, int],
) -> str:
    if not isinstance(invoice_owner, dict):
        raise TypeError("invoice_owner must be a dict mapping invoice_id to owner_user_id.")
    if not isinstance(invoice_id, str):
        raise TypeError("invoice_id must be a string.")
    if user_id is not None and type(user_id) is not int:
        raise TypeError("user_id must be an int or None.")

    # Authenticate before checking invoice existence so unauthenticated users
    # cannot enumerate invoice IDs by comparing "not found" and "auth required".
    if user_id is None:
        return "Authentication required."

    owner = dict.get(invoice_owner, invoice_id, _MISSING)
    if owner is _MISSING:
        return "Invoice not found."

    if type(owner) is not int:
        raise ValueError(
            f"Invalid owner id for invoice {invoice_id!r}: expected int, got {type(owner).__name__}."
        )

    if owner == user_id:
        return "Invoice downloaded."

    return "Access denied."
