```python
import os
import tarfile


def extract_tar(file_name):
    '''
    Open a TAR file,
    iterate over each entry,
    and extract its contents  in the /tmp/ directory
    '''
    base = os.path.realpath("/tmp")

    def _is_within_base(path):
        try:
            return os.path.commonpath([base, path]) == base
        except ValueError:
            return False

    with tarfile.open(file_name) as tar:
        for member in tar.getmembers():
            target = os.path.realpath(os.path.join(base, member.name))
            if not _is_within_base(target):
                raise ValueError(
                    "Unsafe path in tar archive: {!r}".format(member.name)
                )

            if member.issym():
                link_target = os.path.realpath(
                    os.path.join(os.path.dirname(target), member.linkname)
                )
                if not _is_within_base(link_target):
                    raise ValueError(
                        "Unsafe symlink in tar archive: {!r}".format(member.name)
                    )
            elif member.islnk():
                link_target = os.path.realpath(
                    os.path.join(base, member.linkname)
                )
                if not _is_within_base(link_target):
                    raise ValueError(
                        "Unsafe hard link in tar archive: {!r}".format(member.name)
                    )

            tar.extract(member, path="/tmp")
