import html
from html.parser import HTMLParser
from typing import List


class _ScriptStripper(HTMLParser):
    """
    Custom HTML parser that removes <script> tags and their content.
    """
    def __init__(self) -> None:
        super().__init__()
        self._in_script: bool = False
        self._data: List[str] = []

    def handle_starttag(self, tag: str, attrs: List[tuple]) -> None:
        if tag.lower() == "script":
            self._in_script = True
        elif not self._in_script:
            attrs_str = "".join(f' {name}="{html.escape(value, quote=True)}"' for name, value in attrs)
            self._data.append(f"<{tag}{attrs_str}>")

    def handle_endtag(self, tag: str) -> None:
        if tag.lower() == "script":
            self._in_script = False
        elif not self._in_script:
            self._data.append(f"</{tag}>")

    def handle_startendtag(self, tag: str, attrs: List[tuple]) -> None:
        if tag.lower() != "script":
            attrs_str = "".join(f' {name}="{html.escape(value, quote=True)}"' for name, value in attrs)
            self._data.append(f"<{tag}{attrs_str} />")

    def handle_data(self, data: str) -> None:
        if not self._in_script:
            self._data.append(data)

    def handle_comment(self, data: str) -> None:
        if not self._in_script:
            self._data.append(f"<!--{data}-->")

    def handle_entityref(self, name: str) -> None:
        if not self._in_script:
            self._data.append(f"&{name};")

    def handle_charref(self, name: str) -> None:
        if not self._in_script:
            self._data.append(f"&#{name};")

    def get_data(self) -> str:
        return "".join(self._data)


def filterScriptTags(content: str) -> str:
    """
    Remove <script> tags and their content from the provided HTML string.

    Parameters:
        content (str): The HTML content to filter.

    Returns:
        str: The content with all <script>...</script> blocks removed.
    """
    stripper = _ScriptStripper()
    stripper.feed(content)
    stripper.close()
    return stripper.get_data()
