code:
import re

_SCRIPT_PAIR_RE = re.compile(
    r'<script\b[^>]*>.*?</script\s*>',
    re.IGNORECASE | re.DOTALL,
)
_SCRIPT_UNCLOSED_RE = re.compile(
    r'<script\b.*\Z',
    re.IGNORECASE | re.DOTALL,
)


def filterScriptTags(content):
    '''
    Remove <script> tags from the content argument.
    '''
    while True:
        new_content = _SCRIPT_PAIR_RE.sub('', content)
        if new_content == content:
            break
        content = new_content
    return _SCRIPT_UNCLOSED_RE.sub('', content)

