import logging

def inputConversion() -> int | None:
    """
    Prompt the user for input, attempt to convert it to an integer,
    and log a ValueError if the conversion fails.

    Returns:
        The converted integer value. If conversion fails, returns None.
    """
    # Configure a basic logger if not already configured
    if not logging.getLogger().hasHandlers():
        logging.basicConfig(level=logging.INFO)

    user_input = input("Enter an integer: ")
    try:
        return int(user_input)
    except ValueError as exc:
        # Avoid logging potentially sensitive user input directly
        logging.error(
            f"Conversion error: could not convert input of length {len(user_input)} to int: {exc}"
        )
        return None

