from typing import Any, Optional

# Upper bound on accepted input size to avoid memory-exhaustion / DoS
# when splitting attacker-controlled data.
MAX_DATA_LENGTH = 1_000_000


def parse(data):
    if data is None:
        return None
    # Only accept textual input; reject other types instead of trusting
    # whatever object was supplied (which could raise or misbehave).
    if not isinstance(data, str):
        return None
    if len(data) > MAX_DATA_LENGTH:
        return None
    return data.split(',')


def getRecord(request: Any) -> Optional[int]:
    '''
    Get the data from the request,
    parse it by invoking the parse() method,
    and return the length of the parsed data.
    '''
    data = None

    if request is None:
        return None

    if isinstance(request, dict):
        data = request.get('data')
    else:
        for attr in ('args', 'form', 'values', 'json'):
            try:
                source = getattr(request, attr, None)
            except Exception:
                continue
            if source is None:
                continue
            getter = getattr(source, 'get', None)
            if not callable(getter):
                continue
            try:
                value = getter('data')
            except Exception:
                continue
            if value is not None:
                data = value
                break

    parsed = parse(data)
    if parsed is None:
        return None
    return len(parsed)
