    """Load the JWT verification key from the environment.

    Supports either a JWK (JSON) via JWT_JWK or a shared secret via JWT_SECRET.
    """
    jwk_json = os.environ.get("JWT_JWK")
    if jwk_json:
        jwk_data = json.loads(jwk_json)
        if not isinstance(jwk_data, dict):
            raise RuntimeError("JWT_JWK must be a JSON object.")
        return jwk.JWK(**jwk_data)

    secret = os.environ.get("JWT_SECRET")
    if secret:
        return secret

    raise RuntimeError(
        "No JWT verification key configured; set JWT_JWK or JWT_SECRET."
    )


def _allowed_algs_for_key(key):
    """Return only the algorithms valid for the configured key type."""
    if isinstance(key, (str, bytes)):
        return ["HS256", "HS384", "HS512"]

    if isinstance(key, jwk.JWK):
        key_type = key.key_type

        if key_type == "oct":
            return ["HS256", "HS384", "HS512"]

        if key_type == "RSA":
            return [
                "RS256", "RS384", "RS512",
                "PS256", "PS384", "PS512",
            ]

        if key_type == "EC":
            return ["ES256", "ES384", "ES512"]

        raise RuntimeError(f"Unsupported JWT key type: {key_type}")

    raise RuntimeError("Unsupported JWT verification key type.")


def verifyJWTToken(jwt_token):
    '''
    Verify the JWT Token and return it.
    '''
    key = _load_verification_key()
    allowed_algs = _allowed_algs_for_key(key)

    header, claims = jwt.verify_jwt(jwt_token, key, allowed_algs)
