```python
import mimetypes
import os

from django.conf import settings
from django.http import HttpResponse


def getResource(request):
    username = request.GET.get("username")
    date = request.GET.get("date")

    if not username or not date:
        return HttpResponse("Missing username or date", status=400)

    base_dir = os.path.realpath(os.path.join(settings.MEDIA_ROOT, "resources"))
    file_path = os.path.realpath(os.path.join(base_dir, username, date))

    try:
        common_path = os.path.commonpath([base_dir, file_path])
    except ValueError:
        return HttpResponse("Resource not found", status=404)

    if os.path.normcase(common_path) != os.path.normcase(base_dir):
        return HttpResponse("Resource not found", status=404)

    if not os.path.isfile(file_path):
        return HttpResponse("Resource not found", status=404)

    content_type, _ = mimetypes.guess_type(file_path)

    flags = os.O_RDONLY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW

    try:
        fd = os.open(file_path, flags)
    except (OSError, ValueError):
        return HttpResponse("Resource not found", status=404)

    try:
        with os.fdopen(fd, "rb") as resource_file:
            content = resource_file.read()
    except (OSError, ValueError):
        try:
            os.close(fd)
        except OSError:
            pass
        return HttpResponse("Resource not found", status=404)

    response = HttpResponse(
        content,
        content_type=content_type or "application/octet-stream",
    )

    filename = os.path.basename(file_path)
    filename = (
        filename.replace("\\", "_")
        .replace('"', "_")
        .replace("\r", "_")
        .replace("\n", "_")
    )
    if not filename:
        filename = "resource"

    response["Content-Disposition"] = f'attachment; filename="{filename}"'
    response["X-Content-Type-Options"] = "nosniff"
    return response
