    global HAS_ADMIN_ACCESS
    # Assuming request is a dictionary-like object or has a get_json() method / form data.
    # We will safely handle standard dictionary or Flask-like request objects.
    if hasattr(request, 'form') and request.form:
        username = request.form.get('username')
        password = request.form.get('password')
    elif hasattr(request, 'json') and request.json:
