import os
from hmac import compare_digest

HAS_ADMIN_ACCESS = False

ADMIN_USERNAME = os.environ.get("ADMIN_USERNAME", "admin")
ADMIN_PASSWORD = os.environ.get("ADMIN_PASSWORD", "admin")


def _extract_credentials(request):
    candidates = []

    for attr in ("POST", "GET", "form", "data"):
        if hasattr(request, attr):
            value = getattr(request, attr)
            if isinstance(value, dict):
                candidates.append(value)

    if hasattr(request, "json"):
        value = getattr(request, "json")
        if callable(value):
            try:
                value = value()
            except Exception:
                value = None
        if isinstance(value, dict):
            candidates.append(value)

    for data in candidates:
        username = data.get("username")
        password = data.get("password")
        if username is not None and password is not None:
            return username, password

    return None, None


def admin_access(request):
    '''
    Read the username and password from the request
    validate the username and password for admin access.
    Flag that the user has admin access.
    '''
    global HAS_ADMIN_ACCESS

    username, password = _extract_credentials(request)

    if username is None or password is None:
        HAS_ADMIN_ACCESS = False
        return False

    username_valid = compare_digest(str(username), str(ADMIN_USERNAME))
    password_valid = compare_digest(str(password), str(ADMIN_PASSWORD))

    HAS_ADMIN_ACCESS = username_valid and password_valid
    return HAS_ADMIN_ACCESS

