import builtins
import io
import pickle


class _RestrictedUnpickler(pickle.Unpickler):
    '''
    Unpickler that only permits a small allowlist of safe globals,
    preventing arbitrary code execution during deserialization.
    '''

    _SAFE_BUILTINS = frozenset({
        "set",
        "frozenset",
        "bytearray",
        "bytes",
        "complex",
        "range",
        "slice",
        "list",
        "dict",
        "tuple",
        "int",
        "float",
        "str",
        "bool",
    })

    _SAFE_GLOBALS = {
        ("collections", "OrderedDict"),
        ("collections", "defaultdict"),
        ("collections", "deque"),
    }

    def find_class(self, module, name):
        if module == "builtins" and name in self._SAFE_BUILTINS:
            return getattr(builtins, name)
        if (module, name) in self._SAFE_GLOBALS:
            import importlib
            return getattr(importlib.import_module(module), name)
        raise pickle.UnpicklingError(
            "Refusing to deserialize disallowed global: %s.%s" % (module, name)
        )


def getPickleData(pickled):
    '''
    Return deserialized data
    '''
    if hasattr(pickled, "read"):
        return _RestrictedUnpickler(pickled).load()
    return _RestrictedUnpickler(io.BytesIO(pickled)).load()
