import hmac


def _secure_equal(a, b):
    if a is b:
        return True
    if isinstance(a, str) and isinstance(b, str):
        try:
            return hmac.compare_digest(a.encode("utf-8"), b.encode("utf-8"))
        except UnicodeEncodeError:
            return a == b
    if isinstance(a, bytes) and isinstance(b, bytes):
        return hmac.compare_digest(a, b)
    return a == b


def _has_common_element(a, b):
    try:
        return bool(set(a) & set(b))
    except TypeError:
        for x in a:
            for y in b:
                if _secure_equal(x, y):
                    return True
        return False


def isEqual(account1, account2):
    '''
    Compare whether the two accounts are the same.
    '''
    if account1 is None or account2 is None:
        return account1 is account2

    if isinstance(account1, dict) and isinstance(account2, dict):
        name1 = account1.get("name")
        name2 = account2.get("name")
        emails1 = account1.get("emails", [])
        emails2 = account2.get("emails", [])
        return _secure_equal(name1, name2) and _has_common_element(emails1, emails2)

    if isinstance(account1, (list, tuple)) and isinstance(account2, (list, tuple)):
        if not account1 or not account2:
            return account1 == account2
        return _secure_equal(account1[0], account2[0]) and _has_common_element(account1[1:], account2[1:])

    return _secure_equal(account1, account2)
