from django.http import HttpResponse, HttpResponseRedirect
from django.utils.http import url_has_allowed_host_and_scheme
from django.conf import settings


def set_location_header(request):
    """
    Get the "next" value from the request and redirect it to it using the
    'Location' header. The URL is validated to prevent open redirect
    vulnerabilities.
    """
    # Retrieve the next URL from GET or POST data
    next_url = request.GET.get("next") or request.POST.get("next")

    if not next_url:
        return HttpResponse("Missing 'next' parameter", status=400)

    # Validate that the URL is safe (either relative or belongs to an allowed host)
    allowed_hosts = getattr(settings, "ALLOWED_HOSTS", [])
    if not url_has_allowed_host_and_scheme(url=next_url, allowed_hosts=allowed_hosts, require_https=request.is_secure()):
        return HttpResponse("Unsafe redirect target", status=400)

    # Use HttpResponseRedirect to set the Location header and status code
    return HttpResponseRedirect(next_url)

