import sys

# Bound the size of the user-supplied string so that int() cannot be used
# to exhaust CPU/memory (e.g. a multi-megabyte digit string).
MAX_INPUT_LENGTH = 1000


def convert_to_int():
    '''
    Continuously take an input from user and convert it to int within a try-except block
    '''
    while True:
        try:
            user_input = input("Enter an integer: ")
            if len(user_input) > MAX_INPUT_LENGTH:
                print("Invalid input: please enter a valid integer.")
                continue
            return int(user_input)
        except ValueError:
            print("Invalid input: please enter a valid integer.")
        except (OverflowError, MemoryError):
            print("Invalid input: please enter a valid integer.")
        except (EOFError, KeyboardInterrupt):
            print("\nNo valid integer entered.")
            return None
