import re


def checkNumber(number):
    """Use regular expression to match lines with numbers"""
    # Convert the input to a string safely and limit length to prevent ReDoS
    if number is None:
        return False
    num_str = str(number)
    if len(num_str) > 1000:
        raise ValueError("Input string too long")
    # Match any string that contains at least one digit
    return bool(re.search(r"\d", num_str))
