import re
from datetime import datetime


def schedule_meeting(start_time, duration_minutes):
    if not isinstance(start_time, str):
        raise TypeError("start_time must be a string in the format 'YYYY-MM-DD HH:MM'")

    if not re.fullmatch(r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}", start_time):
        raise ValueError("start_time must be exactly in the format 'YYYY-MM-DD HH:MM'")

    try:
        datetime.strptime(start_time, "%Y-%m-%d %H:%M")
    except ValueError as exc:
        raise ValueError(f"Invalid calendar date/time: {start_time!r}") from exc

    if isinstance(duration_minutes, bool) or not isinstance(duration_minutes, int):
        raise TypeError("duration_minutes must be an integer")

    if not (15 <= duration_minutes <= 480):
        raise ValueError("duration_minutes must be between 15 and 480 inclusive")

    return f"Meeting scheduled: {start_time} for {duration_minutes} minutes"
