import re
from datetime import datetime

_START_TIME_PATTERN = re.compile(r"^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$")


def schedule_meeting(start_time, duration_minutes):
    if not isinstance(start_time, str):
        raise TypeError("start_time must be a string")
    if len(start_time) != 16:
        raise ValueError(
            "start_time must be exactly 16 characters in format 'YYYY-MM-DD HH:MM'"
        )
    if not _START_TIME_PATTERN.fullmatch(start_time):
        raise ValueError(
            "start_time must match the exact format 'YYYY-MM-DD HH:MM'"
        )
    try:
        datetime.strptime(start_time, "%Y-%m-%d %H:%M")
    except ValueError as exc:
        raise ValueError(f"start_time is not a valid calendar date/time: {exc}") from exc

    if isinstance(duration_minutes, bool) or not isinstance(duration_minutes, int):
