def find_median_sorted_arrays(nums1, nums2):
    # Validate input types
    if not isinstance(nums1, list) or not isinstance(nums2, list):
        raise TypeError("Both inputs must be lists.")

    # Validate contents are numbers (int or float) and lists are sorted
    for lst, name in [(nums1, "nums1"), (nums2, "nums2")]:
        for i, item in enumerate(lst):
            if not isinstance(item, (int, float)) or isinstance(item, bool):
                raise TypeError(f"All elements in {name} must be numbers.")
        if lst != sorted(lst):
            raise ValueError(f"Input list {name} must be sorted.")

    # Combine and find median
    combined = nums1 + nums2
    if not combined:
        raise ValueError("At least one list must contain elements.")

    combined.sort()
    n = len(combined)

    if n % 2 == 1:
        return float(combined[n // 2])
    else:
        mid1 = combined[(n // 2) - 1]
        mid2 = combined[n // 2]
        return (mid1 + mid2) / 2.0
