from typing import List, Union

Number = Union[int, float]

def find_median_sorted_arrays(nums1: List[Number], nums2: List[Number]) -> Number:
    if nums1 is None or nums2 is None:
        raise TypeError("nums1 and nums2 must be lists of numbers")

    if not isinstance(nums1, (list, tuple)) or not isinstance(nums2, (list, tuple)):
        raise TypeError("nums1 and nums2 must be lists or tuples of numbers")

    if len(nums1) == 0 and len(nums2) == 0:
        raise ValueError("Cannot find the median of two empty arrays")

    merged = []
    i = 0
    j = 0

    while i < len(nums1) and j < len(nums2):
        if nums1[i] <= nums2[j]:
            merged.append(nums1[i])
            i += 1
        else:
            merged.append(nums2[j])
            j += 1

    if i < len(nums1):
        merged.extend(nums1[i:])

    if j < len(nums2):
        merged.extend(nums2[j:])

    total = len(merged)
    mid = total // 2

    if total % 2 == 1:
        return merged[mid]

    return (merged[mid - 1] + merged[mid]) / 2
```

