from numbers import Real


def find_median_sorted_arrays(nums1, nums2):
    """
    Return the median of two sorted lists of real numbers.

    Raises:
        TypeError: If inputs are not lists/tuples or contain non-real values.
        ValueError: If both inputs are empty or an input is not sorted.
    """
    if not isinstance(nums1, (list, tuple)) or not isinstance(nums2, (list, tuple)):
        raise TypeError("nums1 and nums2 must be lists or tuples of real numbers")

    if len(nums1) == 0 and len(nums2) == 0:
        raise ValueError("At least one input array must contain a number")

    for values in (nums1, nums2):
        previous = None
        for index, value in enumerate(values):
            if isinstance(value, bool) or not isinstance(value, Real):
                raise TypeError("All values must be real numbers")
            if index > 0 and value < previous:
                raise ValueError("Input arrays must be sorted in ascending order")
            previous = value

    merged = []
    i = 0
    j = 0
    n = len(nums1)
    m = len(nums2)

    while i < n and j < m:
        if nums1[i] <= nums2[j]:
            merged.append(nums1[i])
            i += 1
        else:
            merged.append(nums2[j])
            j += 1

    if i < n:
        merged.extend(nums1[i:])
    if j < m:
        merged.extend(nums2[j:])

    total = len(merged)
    middle = total // 2

    if total % 2 == 1:
        return merged[middle]

    return (merged[middle - 1] + merged[middle]) / 2
```

