import math


def _validate_sorted_numbers(values, name):
    if not isinstance(values, list):
        raise TypeError(f"{name} must be a list of numbers")

    previous = None
    for index, value in enumerate(values):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(
                f"{name}[{index}] must be an int or float, "
                f"not {type(value).__name__}"
            )

        if isinstance(value, float) and not math.isfinite(value):
            raise ValueError(f"{name}[{index}] must be a finite number")

        if previous is not None and value < previous:
            raise ValueError(f"{name} must be sorted in non-decreasing order")

        previous = value


def find_median_sorted_arrays(nums1, nums2):
    _validate_sorted_numbers(nums1, "nums1")
    _validate_sorted_numbers(nums2, "nums2")

    if not nums1 and not nums2:
        raise ValueError("At least one input list must contain a number")

    total = len(nums1) + len(nums2)
    middle_left_index = (total - 1) // 2
    middle_right_index = total // 2

    i = 0
    j = 0
    left_middle = None
    right_middle = None

    for combined_index in range(total):
        if i < len(nums1) and (j >= len(nums2) or nums1[i] <= nums2[j]):
            value = nums1[i]
            i += 1
        else:
            value = nums2[j]
            j += 1

        if combined_index == middle_left_index:
            left_middle = value

        if combined_index == middle_right_index:
            right_middle = value
            break

    if total % 2 == 1:
        return right_middle

    return (left_middle + right_middle) / 2.0
```

