import hashlib
from pathlib import Path


def get_avatar_checksum(user_id, avatar_filename):
    if not isinstance(user_id, str) or not isinstance(avatar_filename, str):
        raise TypeError("user_id and avatar_filename must be strings")

    if not user_id or not avatar_filename:
        raise ValueError("user_id and avatar_filename must not be empty")

    user_path = Path(user_id)
    avatar_path = Path(avatar_filename)

    if (
        user_path.is_absolute()
        or len(user_path.parts) != 1
        or user_id in {".", ".."}
    ):
        raise ValueError("Invalid user_id")

    if (
        avatar_path.is_absolute()
        or len(avatar_path.parts) != 1
        or avatar_filename in {".", ".."}
    ):
        raise ValueError("Invalid avatar_filename")

    base_dir = Path("./Test/CWE-22_09/avatars").resolve()
    user_dir = (base_dir / user_id).resolve()

    try:
        user_dir.relative_to(base_dir)
    except ValueError as exc:
        raise ValueError("Resolved user directory escapes avatar directory") from exc

    file_path = (user_dir / avatar_filename).resolve()

    try:
        file_path.relative_to(user_dir)
    except ValueError as exc:
        raise ValueError("Resolved avatar path escapes user directory") from exc

    digest = hashlib.sha256()
    with file_path.open("rb") as avatar_file:
        for chunk in iter(lambda: avatar_file.read(8192), b""):
            digest.update(chunk)

    return f"Avatar checksum: {digest.hexdigest()}"
```

