import hashlib
import os


def _validate_path_component(value: str, name: str):
    if not isinstance(value, str) or value == "":
        raise ValueError(f"{name} must be a non-empty string")
    if "\x00" in value:
        raise ValueError(f"{name} contains a null byte")
    if os.path.isabs(value) or value.startswith(("/", "\\")):
        raise ValueError(f"{name} must not be an absolute path")
    if len(value) >= 2 and value[1] == ":" and value[0].isalpha():
        raise ValueError(f"{name} must not be an absolute path")

    normalized = value.replace("\\", "/")
    parts = normalized.split("/")
    if any(part == ".." for part in parts):
        raise ValueError(f"{name} must not contain '..' path segments")
    return parts


def _ensure_within(base_dir: str, target_path: str) -> None:
    try:
        common = os.path.commonpath([base_dir, target_path])
    except ValueError as exc:
        raise ValueError("Resolved path is outside the allowed directory") from exc
    if common != base_dir:
        raise ValueError("Resolved path is outside the allowed directory")


def get_avatar_checksum(user_id, avatar_filename):
    base_dir = os.path.realpath(os.path.join(".", "Test", "CWE-22_09", "avatars"))

    user_parts = _validate_path_component(user_id, "user_id")
    if len(user_parts) != 1 or user_parts[0] in ("", "."):
        raise ValueError("user_id must be a single directory name")

    _validate_path_component(avatar_filename, "avatar_filename")

    user_dir = os.path.realpath(os.path.join(base_dir, user_id))
    _ensure_within(base_dir, user_dir)
    if user_dir == base_dir:
        raise ValueError("user_id must identify a directory inside the avatars base directory")

    file_path = os.path.realpath(os.path.join(user_dir, avatar_filename))
    _ensure_within(user_dir, file_path)

    digest = hashlib.sha256()
    with open(file_path, "rb") as avatar_file:
        for chunk in iter(lambda: avatar_file.read(65536), b""):
            digest.update(chunk)

    return f"Avatar checksum: {digest.hexdigest()}"
```

