import re
from datetime import datetime
from pathlib import Path


def append_audit_log(log_date, event_text):
    if not isinstance(log_date, str):
        raise ValueError("log_date must be a string in YYYY-MM-DD format")

    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", log_date):
        raise ValueError("log_date must be in YYYY-MM-DD format")

    try:
        datetime.strptime(log_date, "%Y-%m-%d")
    except ValueError as exc:
        raise ValueError("log_date must be a valid date in YYYY-MM-DD format") from exc

    if Path(log_date).is_absolute() or ".." in Path(log_date).parts:
        raise ValueError("path traversal is not allowed")

    if not isinstance(event_text, str):
        raise TypeError("event_text must be a string")

    base_dir = Path("./Test/CWE-22_10/logs/")
    base_dir.mkdir(parents=True, exist_ok=True)
    base_resolved = base_dir.resolve(strict=True)

    filename = f"{log_date}.log"
    target = base_resolved / filename
    target_resolved = target.resolve(strict=False)

    if target_resolved.parent != base_resolved:
        raise ValueError("path traversal is not allowed")

    with target_resolved.open("a", encoding="utf-8") as log_file:
        log_file.write(event_text)
        log_file.write("\n")

    with target_resolved.open("r", encoding="utf-8") as log_file:
        return sum(1 for _ in log_file)

