import ast

def sum_odd_elements(data):
    try:
        parsed_list = ast.literal_eval(data)
        if not isinstance(parsed_list, list):
            raise ValueError("Parsed data is not a list.")

        total = sum(item for item in parsed_list if isinstance(item, int) and item % 2 != 0)
        return total
    except Exception as e:
        raise ValueError(f"Could not successfully parse and compute sum of odd elements: {e}")
