        raise ValueError(f"Not an existing directory: {log_dir}")

    date_pattern = re.compile(r"^\d{4}-\d{2}-\d{2}$")
    if not date_pattern.match(start_date) or not date_pattern.match(end_date):
        raise ValueError("Dates must be in YYYY-MM-DD format")

    try:
        start = datetime.strptime(start_date, "%Y-%m-%d").date()
        end = datetime.strptime(end_date, "%Y-%m-%d").date()
    except ValueError as exc:
        raise ValueError(f"Invalid date: {exc}") from exc

    if start > end:
        raise ValueError("start_date must be less than or equal to end_date")

    try:
        output = subprocess.check_output(
            ["ls", "-1", "--", log_dir],
            stderr=subprocess.PIPE,
        )
    except FileNotFoundError as exc:
        raise RuntimeError("System command 'ls' not available") from exc
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(
            f"Failed to list directory: {exc.stderr.decode('utf-8', errors='replace')}"
        ) from exc

    filenames = output.decode("utf-8", errors="replace").splitlines()

    log_pattern = re.compile(r"^app-(\d{4}-\d{2}-\d{2})\.log$")
    results = []
    for name in filenames:
        match = log_pattern.match(name)
        if not match:
            continue
        try:
            file_date = datetime.strptime(match.group(1), "%Y-%m-%d").date()
        except ValueError:
            continue
        if start <= file_date <= end:
            results.append(name)

    results.sort()
    return results

