import os


def count_directories(directory):
    """Return the number of immediate subdirectories inside ``directory``.

    Raises:
        TypeError: if ``directory`` is not a string or path-like object.
        FileNotFoundError: if ``directory`` does not exist.
        NotADirectoryError: if ``directory`` is not a directory.
        PermissionError: if the directory cannot be read.
    """
    if not isinstance(directory, (str, bytes, os.PathLike)):
        raise TypeError(
            f"directory must be a string or path-like object, got {type(directory).__name__}"
        )

    path = os.fspath(directory)

    if not os.path.exists(path):
        raise FileNotFoundError(f"No such file or directory: {path!r}")

    if not os.path.isdir(path):
        raise NotADirectoryError(f"Not a directory: {path!r}")

    count = 0
    with os.scandir(path) as entries:
        for entry in entries:
            try:
                if entry.is_dir(follow_symlinks=False):
                    count += 1
            except OSError:
                # Entry vanished or is inaccessible; skip it.
                continue

    return count
