import os
import subprocess


def archive_directory(directory, dest_tar_path):
    if not isinstance(directory, str) or not isinstance(dest_tar_path, str):
        raise TypeError("directory and dest_tar_path must be strings")

    if not directory:
        raise ValueError("directory must not be empty")
    if not dest_tar_path:
        raise ValueError("dest_tar_path must not be empty")

    if not os.path.isdir(directory):
        raise FileNotFoundError(f"Directory not found: {directory}")

    dest_dir = os.path.dirname(os.path.abspath(dest_tar_path))
    if dest_dir and not os.path.isdir(dest_dir):
        raise FileNotFoundError(f"Destination directory not found: {dest_dir}")

    # Use subprocess with a list of arguments (no shell=True) to avoid
    # command injection vulnerabilities (CWE-78).
    cmd = [
        "tar",
        "-cf", dest_tar_path,
        "-C", directory,
        ".",
    ]

    try:
        result = subprocess.run(
            cmd,
            check=False,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
    except FileNotFoundError as exc:
        raise RuntimeError("The 'tar' utility is not available") from exc
    except OSError as exc:
        raise RuntimeError(f"Failed to execute tar: {exc}") from exc

    if result.returncode != 0:
        raise RuntimeError(
            f"tar failed with exit code {result.returncode}: {result.stderr.strip()}"
        )

    if not os.path.isfile(dest_tar_path):
        raise RuntimeError(f"Archive was not created at {dest_tar_path}")

    return f"Archived to {dest_tar_path}"
