import os
import subprocess


def _validate_tar_argument(value, name):
    if not isinstance(value, str):
        raise TypeError(f"{name} must be a string")
    if not value:
        raise ValueError(f"{name} must not be empty")
    if "\x00" in value:
        raise ValueError(f"{name} must not contain NUL bytes")


def archive_directory(directory, dest_tar_path):
    _validate_tar_argument(directory, "directory")
    _validate_tar_argument(dest_tar_path, "dest_tar_path")

    if not os.path.exists(directory):
        raise FileNotFoundError(f"Directory does not exist: {directory}")
    if not os.path.isdir(directory):
        raise NotADirectoryError(f"Not a directory: {directory}")

    command = [
        "tar",
        "--create",
        f"--file={dest_tar_path}",
        f"--directory={directory}",
        ".",
    ]

    try:
        subprocess.run(
            command,
            check=True,
            shell=False,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
    except subprocess.CalledProcessError as exc:
        stderr = (exc.stderr or "").strip()
        raise RuntimeError(
            f"Failed to archive {directory!r} to {dest_tar_path!r}: {stderr}"
        ) from exc

    return f"Archived to {dest_tar_path}"
