import html
from urllib.parse import urlparse


def build_redirect_page(target_url):
    if not isinstance(target_url, str):
        raise TypeError("target_url must be a string")

    if not target_url:
        raise ValueError("target_url must not be empty")

    if target_url != target_url.strip():
        raise ValueError("target_url must not contain leading or trailing whitespace")

    if any(ord(ch) < 0x20 or ord(ch) == 0x7F for ch in target_url):
        raise ValueError("target_url must not contain control characters")

    parsed = urlparse(target_url)
    if parsed.scheme.lower() not in ("http", "https"):
        raise ValueError("target_url must use the http or https scheme")

    if not parsed.netloc:
        raise ValueError("target_url must include a valid host")

    escaped_url = html.escape(target_url, quote=True)

    return (
        '<html><head><meta http-equiv="refresh" content="0;url='
        + escaped_url
        + '"></head><body>Go to <a href="'
        + escaped_url
        + '">'
        + escaped_url
        + "</a></body></html>"
    )
```

