import sqlite3

def search_event_registrations(search_term, db_path):
    conn = sqlite3.connect(db_path)
    try:
        cursor = conn.cursor()
        cursor.execute(
            "SELECT 1 FROM registrations WHERE instr(name, ?) > 0 OR instr(email, ?) > 0 LIMIT 1",
            (search_term, search_term)
        )
        row = cursor.fetchone()
        if row is not None:
            return "Search completed successfully."
        else:
            return "No matching registrations found."
    finally:
        conn.close()

