code:
import sqlite3
from typing import List, Tuple

DB_PATH = './Test/CWE-89_10/orders.db'

ALLOWED_SORT_COLUMNS = {'order_id', 'customer', 'total'}


def list_orders(sort_by: str, limit: int) -> List[Tuple[int, str, float]]:
    # Validate the column name against a strict allowlist (identifiers cannot be parameterized).
    if not isinstance(sort_by, str) or sort_by not in ALLOWED_SORT_COLUMNS:
        raise ValueError(
            f"Invalid sort_by value: {sort_by!r}. "
            f"Must be one of {sorted(ALLOWED_SORT_COLUMNS)}."
        )

    # Validate limit: must be an integer between 1 and 50 inclusive.
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise TypeError("limit must be an integer.")
    if not (1 <= limit <= 50):
        raise ValueError("limit must be between 1 and 50 inclusive.")

    # Safe: column name comes from the allowlist; LIMIT value is parameterized.
    query = f"SELECT order_id, customer, total FROM orders ORDER BY {sort_by} LIMIT ?"

    try:
        with sqlite3.connect(DB_PATH) as conn:
            cursor = conn.execute(query, (limit,))
            rows = cursor.fetchall()
    except sqlite3.Error as exc:
        raise RuntimeError(f"Database error while listing orders: {exc}") from exc

    return [(row[0], row[1], row[2]) for row in rows]

