```python
import ast
import operator

def evaluate_expression(expression: str) -> float:
    """
    Evaluate a simple arithmetic expression containing digits, whitespace,
    '+', '-', '*', '/', and parentheses.
    Raises a ValueError if the expression is invalid or contains unsupported
    operations.
    """
    # Define supported operators
    ops = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
    }

    def _eval(node: ast.AST) -> float:
        if isinstance(node, ast.Expression):
            return _eval(node.body)
        elif isinstance(node, ast.BinOp):
            left = _eval(node.left)
            right = _eval(node.right)
            op_type = type(node.op)
            if op_type not in ops:
                raise ValueError(f"Unsupported operator: {op_type.__name__}")
            return ops[op_type](left, right)
        elif isinstance(node, ast.UnaryOp):
            if isinstance(node.op, ast.UAdd):
                return +_eval(node.operand)
            elif isinstance(node.op, ast.USub):
                return -_eval(node.operand)
            else:
                raise ValueError(f"Unsupported unary operator: {type(node.op).__name__}")
        elif isinstance(node, ast.Num):  # For Python < 3.8
            return node.n
        elif isinstance(node, ast.Constant):  # For Python >= 3.8
            if isinstance(node.value, (int, float)):
                return node.value
            else:
                raise ValueError(f"Unsupported constant type: {type(node.value).__name__}")
        elif isinstance(node, ast.Paren):
            return _eval(node.value)
        else:
            raise ValueError(f"Unsupported expression type: {type(node).__name__}")

    try:
        # Parse the expression into an AST
        parsed = ast.parse(expression, mode='eval')
        # Ensure the AST contains only allowed nodes
        for node in ast.walk(parsed):
            if not isinstance(node, (ast.Expression, ast.BinOp, ast.UnaryOp,
                                    ast.Num, ast.Constant, ast.Add, ast.Sub,
                                    ast.Mult, ast.Div, ast.USub, ast.UAdd,
                                    ast.Load, ast.Expr, ast.Paren, ast.Tuple,
                                    ast.List, ast.Name, ast.Call, ast.Subscript,
                                    ast.Index, ast.Slice, ast.Attribute, ast.Module)):
                # Allow only the nodes we explicitly handle
                if not isinstance(node, (ast.Expression, ast.BinOp, ast.UnaryOp,
                                        ast.Num, ast.Constant, ast.Add, ast.Sub,
                                        ast.Mult, ast.Div, ast.USub, ast.UAdd,
                                        ast.Load, ast.Expr, ast.Paren)):
                    raise ValueError(f"Unsupported syntax element: {type(node).__name__}")
        return _eval(parsed)
    except Exception as e:
        raise ValueError(f"Invalid expression: {expression}. Reason: {e}") from e
