```python
import ast
import operator

# Supported operators mapping
OPERATORS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.USub: operator.neg,
    ast.UAdd: operator.pos,
}

def evaluate_expression(expression: str) -> float:
    """
    Evaluate a simple arithmetic expression containing integers, +, -, *, /, and parentheses.
    Raises ValueError for unsupported syntax or division by zero.
    """
    try:
        # Strip whitespace to avoid accidental leading/trailing spaces
        cleaned_expr = expression.strip()
        # Parse the expression into an AST
        node = ast.parse(cleaned_expr, mode='eval')
    except SyntaxError as exc:
        raise ValueError(f"Invalid expression: {exc}") from exc

    def _eval(node):
        if isinstance(node, ast.Expression):
            return _eval(node.body)
        elif isinstance(node, ast.Num):  # For Python <3.8
            return node.n
        elif isinstance(node, ast.Constant):  # For Python >=3.8
            if isinstance(node.value, (int, float)):
                return node.value
            raise ValueError(f"Unsupported constant type: {type(node.value)}")
        elif isinstance(node, ast.BinOp):
            left = _eval(node.left)
            right = _eval(node.right)
            op_type = type(node.op)
            if op_type not in OPERATORS:
                raise ValueError(f"Unsupported binary operator: {op_type.__name__}")
            try:
                result = OPERATORS[op_type](left, right)
            except ZeroDivisionError as exc:
                raise ZeroDivisionError("Division by zero") from exc
            return result
        elif isinstance(node, ast.UnaryOp):
            operand = _eval(node.operand)
            op_type = type(node.op)
            if op_type not in OPERATORS:
                raise ValueError(f"Unsupported unary operator: {op_type.__name__}")
            return OPERATORS[op_type](operand)
        elif isinstance(node, ast.Paren):  # Not a real node, but keep for clarity
            return _eval(node.value)
        else:
            raise ValueError(f"Unsupported expression component: {type(node).__name__}")

    return _eval(node)
```

