import re
from typing import Iterator, Tuple

def evaluate_expression(expression: str) -> float:
    """
    Evaluate a mathematical expression consisting of integers, '+', '-', '*', '/',
    whitespace, and parentheses.

    Parameters
    ----------
    expression : str
        The arithmetic expression to evaluate.

    Returns
    -------
    float
        The numeric result of the expression.

    Raises
    ------
    ValueError
        If the expression contains invalid syntax or division by zero occurs.
    """

    # Tokenize the input string
    token_pattern = re.compile(r"\s*(?:(\d+)|(.))")
    tokens: Iterator[Tuple[str, str]] = iter(
        (num, op) for num, op in token_pattern.findall(expression)
    )

    def next_token() -> Tuple[str, str]:
        try:
            return next(tokens)
        except StopIteration:
            return ("", "")

    def parse_factor() -> float:
        num, op = next_token()
        if op:
            if op == '(':
                val = parse_expr()
                closing_num, closing_op = next_token()
                if closing_op != ')':
                    raise ValueError("Mismatched parentheses")
                return val
            else:
                raise ValueError(f"Unexpected token: {op}")
        if not num:
            raise ValueError("Expected number but got end of expression")
        return float(num)

    def parse_term() -> float:
        result = parse_factor()
        while True:
            num, op = next_token()
            if op in ('*', '/'):
                rhs = parse_factor()
                if op == '*':
                    result *= rhs
                else:
                    if rhs == 0:
                        raise ValueError("Division by zero")
                    result /= rhs
            else:
                # Put back the token that is not part of the term
                # by using a generator that yields it again
                tokens = ( (num, op), ) + tuple(tokens)
                break
        return result

    def parse_expr() -> float:
        result = parse_term()
        while True:
            num, op = next_token()
            if op in ('+', '-'):
                rhs = parse_term()
                if op == '+':
                    result += rhs
                else:
                    result -= rhs
            else:
                # Put back the token that is not part of the expression
                tokens = ( (num, op), ) + tuple(tokens)
                break
        return result

    # Start parsing
    result = parse_expr()

    # Ensure no remaining tokens
    remaining_num, remaining_op = next_token()
    if remaining_num or remaining_op:
        raise ValueError("Unexpected trailing characters")

    return result
```

