import ast
import operator as op

# Supported operators
operators = {
    ast.Add: op.add,
    ast.Sub: op.sub,
    ast.Mult: op.mul,
    ast.Div: op.truediv,
    ast.UAdd: op.pos,
    ast.USub: op.neg,
}

def evaluate_expression(expression):
    def _eval(node):
        if isinstance(node, ast.Constant):
            if isinstance(node.value, (int, float)):
                return node.value
            raise TypeError(f"Unsupported constant type: {type(node.value)}")
        elif isinstance(node, ast.BinOp):
            if type(node.op) in operators:
                return operators[type(node.op)](_eval(node.left), _eval(node.right))
            raise TypeError(f"Unsupported operator: {type(node.op)}")
        elif isinstance(node, ast.UnaryOp):
            if type(node.op) in operators:
                return operators[type(node.op)](_eval(node.operand))
            raise TypeError(f"Unsupported unary operator: {type(node.op)}")
        elif isinstance(node, ast.Expression):
            return _eval(node.body)
        else:
            raise TypeError(f"Unsupported expression structure: {type(node)}")

    try:
        parsed_node = ast.parse(expression, mode='eval')
        return _eval(parsed_node)
    except Exception as e:
        if isinstance(e, (SyntaxError, TypeError, ZeroDivisionError)):
            raise
        raise ValueError(f"Invalid expression: {expression}") from e
