import re


_MAX_EXPRESSION_LENGTH = 10000
_MAX_DEPTH = 200


def evaluate_expression(expression):
    """Safely evaluate an arithmetic expression string.

    Supports integers, whitespace, '+', '-', '*', '/', and parentheses.
    Raises ValueError/TypeError/ZeroDivisionError on invalid input.
    """
    if not isinstance(expression, str):
        raise TypeError("expression must be a string")
    if len(expression) > _MAX_EXPRESSION_LENGTH:
        raise ValueError("expression is too long")

    tokens = _tokenize(expression)
    if not tokens:
        raise ValueError("empty expression")

    pos = [0]
    result = _parse_expr(tokens, pos, 0)
    if pos[0] != len(tokens):
        raise ValueError("unexpected token: %r" % (tokens[pos[0]],))
    return _normalize(result)


def _tokenize(text):
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch.isspace():
            i += 1
        elif ch.isdigit():
            j = i
            while j < n and text[j].isdigit():
                j += 1
            tokens.append(text[i:j])
            i = j
        elif ch in "+-*/()":
            tokens.append(ch)
            i += 1
        else:
            raise ValueError("invalid character: %r" % (ch,))
    return tokens


