    value = _parse_term(tokens, pos, depth)
    while pos[0] < len(tokens) and tokens[pos[0]] in ("+", "-"):
        op = tokens[pos[0]]
        pos[0] += 1
        rhs = _parse_term(tokens, pos, depth)
        value = value + rhs if op == "+" else value - rhs
    return value


def _parse_term(tokens, pos, depth):
    value = _parse_factor(tokens, pos, depth)
    while pos[0] < len(tokens) and tokens[pos[0]] in ("*", "/"):
        op = tokens[pos[0]]
        pos[0] += 1
        rhs = _parse_factor(tokens, pos, depth)
        if op == "*":
            value *= rhs
        else:
            if rhs == 0:
                raise ZeroDivisionError("division by zero")
            value /= rhs
    return value


def _parse_factor(tokens, pos, depth):
    if depth > _MAX_DEPTH:
        raise ValueError("expression nesting is too deep")
    if pos[0] >= len(tokens):
        raise ValueError("unexpected end of expression")

    tok = tokens[pos[0]]
    if tok == "+":
        pos[0] += 1
        return _parse_factor(tokens, pos, depth + 1)
    if tok == "-":
        pos[0] += 1
        return -_parse_factor(tokens, pos, depth + 1)
    if tok == "(":
        pos[0] += 1
        value = _parse_expr(tokens, pos, depth + 1)
        if pos[0] >= len(tokens) or tokens[pos[0]] != ")":
            raise ValueError("missing closing parenthesis")
        pos[0] += 1
        return value
    if tok.isdigit():
        pos[0] += 1
        return int(tok)
    raise ValueError("unexpected token: %r" % (tok,))


def _normalize(value):
    if isinstance(value, float) and value.is_integer():
        return int(value)
    return value
