```python
import ast
import operator

# Supported binary operators mapped to their functions
_bin_ops = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
}

# Supported unary operators mapped to their functions
_unary_ops = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
}

def _eval(node):
    """Recursively evaluate an AST node representing an arithmetic expression."""
    if isinstance(node, ast.Num):  # Python <3.8
        return node.n
    if isinstance(node, ast.Constant):  # Python 3.8+
        if isinstance(node.value, (int, float)):
            return node.value
        raise ValueError(f"Unsupported constant type: {type(node.value).__name__}")
    if isinstance(node, ast.BinOp):
        left = _eval(node.left)
        right = _eval(node.right)
        op_type = type(node.op)
        if op_type in _bin_ops:
            return _bin_ops[op_type](left, right)
        raise ValueError(f"Unsupported binary operator: {op_type.__name__}")
    if isinstance(node, ast.UnaryOp):
        operand = _eval(node.operand)
        op_type = type(node.op)
        if op_type in _unary_ops:
            return _unary_ops[op_type](operand)
        raise ValueError(f"Unsupported unary operator: {op_type.__name__}")
    if isinstance(node, ast.Expression):
        return _eval(node.body)
    if isinstance(node, ast.Paren):
        return _eval(node.value)
    raise ValueError(f"Unsupported expression element: {type(node).__name__}")

def execute_command(command: str):
    """
    Evaluate a simple arithmetic expression.

    Parameters
    ----------
    command : str
        A string containing digits, whitespace, '+', '-', '*', '/', and parentheses.

    Returns
    -------
    int | float
        The numerical result of the expression.

    Raises
    ------
    ValueError
        If the expression contains unsupported characters or operators.
    ZeroDivisionError
        If division by zero occurs during evaluation.
    """
    # Ensure only allowed characters are present
    allowed_chars = set("0123456789+-*/() .\t\n\r")
    if not set(command).issubset(allowed_chars):
        raise ValueError("Expression contains invalid characters")

    try:
        # Parse the expression into an AST
        tree = ast.parse(command, mode="eval")
        # Evaluate the parsed AST
        return _eval(tree)
    except ZeroDivisionError:
        raise
    except Exception as exc:
        raise ValueError(f"Failed to evaluate expression: {exc}") from exc
