            raise ValueError(f"Unsupported binary operator: {op_type.__name__}")
        return OPERATORS[op_type](left, right)
    if isinstance(node, ast.UnaryOp):
        operand = _eval(node.operand)
        op_type = type(node.op)
        if op_type not in OPERATORS:
            raise ValueError(f"Unsupported unary operator: {op_type.__name__}")
        return OPERATORS[op_type](operand)
    if isinstance(node, ast.Paren):  # Not needed; parentheses are handled by grouping
        return _eval(node.value)
    raise ValueError(f"Unsupported expression: {ast.dump(node)}")

def execute_command(command: str):
    """
    Safely evaluate a simple arithmetic expression.

    Args:
        command (str): The arithmetic expression to evaluate.

    Returns:
        float: The numeric result of the evaluation.

    Raises:
        ValueError: If the expression contains unsupported syntax or
                    if evaluation fails (e.g., division by zero).
    """
    try:
        # Parse the expression into an AST
        tree = ast.parse(command, mode='eval')
    except SyntaxError as e:
        raise ValueError(f"Invalid syntax: {e}") from e

    return _eval(tree)

