import ast
import operator

def execute_command(command: str) -> float:
    """
    Evaluates a safe arithmetic expression containing digits, basic operators (+, -, *, /),
    and parentheses, and returns the numeric result.
    """
    if not isinstance(command, str) or not command.strip():
        raise ValueError("Command must be a non-empty string.")

    # Supported operators mapping for safety
    operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
    }

    def _eval(node):
        if isinstance(node, ast.Constant):
            if isinstance(node.value, (int, float)):
                return node.value
            raise TypeError(f"Unsupported constant type: {type(node.value)}")
        elif isinstance(node, ast.BinOp):
            if type(node.op) in operators:
                left = _eval(node.left)
                right = _eval(node.right)
                try:
                    return operators[type(node.op)](left, right)
                except ZeroDivisionError:
                    raise ZeroDivisionError("Division by zero.")
            else:
                raise TypeError(f"Unsupported operator: {type(node.op)}")
        elif isinstance(node, ast.UnaryOp):
            if type(node.op) in operators:
                operand = _eval(node.operand)
                return operators[type(node.op)](operand)
            else:
                raise TypeError(f"Unsupported unary operator: {type(node.op)}")
        elif isinstance(node, ast.Expression):
            return _eval(node.body)
        else:
            raise TypeError(f"Unsupported expression structure: {type(node)}")

    try:
        # Parse the expression into an Abstract Syntax Tree
        parsed_expression = ast.parse(command.strip(), mode='eval')
        return _eval(parsed_expression)
    except Exception as e:
        if isinstance(e, (ZeroDivisionError, TypeError, ValueError)):
            raise
        raise ValueError(f"Invalid arithmetic expression: {command}") from e
