import math


class _ArithmeticParser:
    def __init__(self, expression: str) -> None:
        self.expression = expression
        self.position = 0
        self.length = len(expression)

    def parse(self):
        self._skip_whitespace()
        if self.position >= self.length:
            raise ValueError("Empty arithmetic expression")

        result = self._parse_expression()
        self._skip_whitespace()

        if self.position != self.length:
            raise ValueError(
                f"Unexpected character {self.expression[self.position]!r} "
                f"at position {self.position}"
            )

        return result

    def _skip_whitespace(self) -> None:
        while self.position < self.length and self.expression[self.position].isspace():
            self.position += 1

    def _parse_expression(self):
        value = self._parse_term()

        while True:
            self._skip_whitespace()
            if self.position >= self.length:
                break

            operator = self.expression[self.position]
            if operator not in ("+", "-"):
                break

            self.position += 1
            right = self._parse_term()

            if operator == "+":
                value += right
            else:
                value -= right

        return value

    def _parse_term(self):
        value = self._parse_factor()

        while True:
            self._skip_whitespace()
            if self.position >= self.length:
                break

            operator = self.expression[self.position]
            if operator not in ("*", "/"):
                break

            self.position += 1
            right = self._parse_factor()

            if operator == "*":
                value *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                value /= right

        return value

    def _parse_factor(self):
        self._skip_whitespace()

        if self.position >= self.length:
            raise ValueError("Unexpected end of expression")

        character = self.expression[self.position]

        if character == "+":
            self.position += 1
            return self._parse_factor()

        if character == "-":
            self.position += 1
            return -self._parse_factor()

        if character == "(":
            self.position += 1
            value = self._parse_expression()
            self._skip_whitespace()

            if self.position >= self.length or self.expression[self.position] != ")":
                raise ValueError("Missing closing parenthesis")

            self.position += 1
            return value

        if "0" <= character <= "9":
            start = self.position
            while (
                self.position < self.length
                and "0" <= self.expression[self.position] <= "9"
            ):
                self.position += 1

            return int(self.expression[start:self.position])

        raise ValueError(
            f"Unexpected character {character!r} at position {self.position}"
        )


def execute_command(command):
    if not isinstance(command, str):
        raise TypeError("command must be a string")

    parser = _ArithmeticParser(command)
    result = parser.parse()

    if isinstance(result, float) and math.isfinite(result) and result.is_integer():
        return int(result)

    return result
