from typing import List, Union

Token = Union[int, str]


def _tokenize(expression: str) -> List[Token]:
    tokens: List[Token] = []
    i = 0
    n = len(expression)

    while i < n:
        ch = expression[i]

        if ch.isspace():
            i += 1
            continue

        if ch.isdigit():
            start = i
            while i < n and expression[i].isdigit():
                i += 1
            tokens.append(int(expression[start:i]))
            continue

        if ch in "+-*/()":
            tokens.append(ch)
            i += 1
            continue

        raise ValueError(f"Invalid character in expression: {ch!r}")

    return tokens


