        while self._peek() in ("+", "-"):
            operator = self._consume()
            right = self._parse_term()

            if operator == "+":
                value += right
            else:
                value -= right

        return value

    def _parse_term(self) -> float | int:
        value = self._parse_factor()

        while self._peek() in ("*", "/"):
            operator = self._consume()
            right = self._parse_factor()

            if operator == "*":
                value *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                value /= right

        return value

    def _parse_factor(self) -> float | int:
        token = self._peek()

        if token in ("+", "-"):
            operator = self._consume()
            value = self._parse_factor()
            return value if operator == "+" else -value

        return self._parse_primary()

    def _parse_primary(self) -> float | int:
        token = self._peek()

        if isinstance(token, int):
