import numbers

def calculate_submatrix_sum(matrix, row1, col1, row2, col2, k):
    """
    Return True if the sum of all elements in the submatrix defined by
    inclusive coordinates (row1, col1) and (row2, col2) equals k.
    Raises ValueError for invalid inputs.
    """
    # Basic input validation
    if not isinstance(matrix, list) or not matrix:
        raise ValueError("Matrix must be a non-empty list of lists.")
    if not all(isinstance(row, list) for row in matrix):
        raise ValueError("Matrix must be a list of lists.")
    n_rows = len(matrix)
    n_cols = len(matrix[0])
    if any(len(row) != n_cols for row in matrix):
        raise ValueError("All rows in the matrix must have the same length.")
    for r in matrix:
        if not all(isinstance(x, numbers.Number) for x in r):
            raise ValueError("Matrix elements must be numeric.")
    for val in (row1, col1, row2, col2, k):
        if not isinstance(val, numbers.Integral):
            raise ValueError("Indices and k must be integers.")
    if not (0 <= row1 <= row2 < n_rows) or not (0 <= col1 <= col2 < n_cols):
        raise ValueError("Row and column indices are out of bounds or invalid.")

    # Compute the sum
    total = 0
    for r in range(row1, row2 + 1):
        total += sum(matrix[r][c] for c in range(col1, col2 + 1))

    return total == k
