def calculate_submatrix_sum(matrix, row1, col1, row2, col2, k):
    """
    Return True if the sum of all elements in the submatrix defined by
    inclusive corners (row1, col1) to (row2, col2) equals k.
    Raises ValueError for invalid inputs.
