    if not matrix or not all(isinstance(r, list) for r in matrix):
        raise ValueError("Matrix must be a non-empty list of lists.")
    n_rows = len(matrix)
    n_cols = len(matrix[0])
    if any(len(r) != n_cols for r in matrix):
