    if not (0 <= col1 <= col2 < n_cols):
        raise ValueError("Column indices out of bounds.")

    # Compute submatrix sum
    total = 0
    for r in range(row1, row2 + 1):
        for c in range(col1, col2 + 1):
            total += matrix[r][c]

    return total == k
