def calculate_submatrix_sum(matrix, row1, col1, row2, col2, k):
    """
    Return True if the sum of the inclusive submatrix defined by
    (row1, col1) to (row2, col2) equals k, otherwise False.

    Raises:
        TypeError: If matrix, its elements, indices, or k have invalid types.
        ValueError: If matrix shape or submatrix bounds are invalid.
    """
    if not isinstance(matrix, list) or not matrix:
        raise ValueError("matrix must be a non-empty list of lists")

    if not isinstance(k, int) or isinstance(k, bool):
        raise TypeError("k must be an integer")

    cols = None
    for row_index, row in enumerate(matrix):
        if not isinstance(row, list):
            raise TypeError(f"matrix row {row_index} must be a list")
        if not row:
            raise ValueError(f"matrix row {row_index} must not be empty")

        if cols is None:
            cols = len(row)
        elif len(row) != cols:
            raise ValueError("matrix must be rectangular")

        for value in row:
            if not isinstance(value, int) or isinstance(value, bool):
                raise TypeError("matrix elements must be integers")

    rows = len(matrix)

    for name, value in (
        ("row1", row1),
        ("col1", col1),
        ("row2", row2),
        ("col2", col2),
    ):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError(f"{name} must be an integer")

    if row1 < 0 or col1 < 0 or row2 < 0 or col2 < 0:
        raise ValueError("submatrix indices must not be negative")

    if row1 > row2 or col1 > col2:
        raise ValueError("top-left corner must not be after bottom-right corner")

    if row2 >= rows or col2 >= cols:
        raise ValueError("submatrix indices exceed matrix bounds")

    total = 0
    for r in range(row1, row2 + 1):
        for c in range(col1, col2 + 1):
            total += matrix[r][c]

    return total == k
