import os


def save_firmware_blob(blob_name, blob_bytes, upload_dir):
    if not isinstance(blob_name, str) or not blob_name.strip():
        raise ValueError("blob_name must be a non-empty string")

    if "\x00" in blob_name:
        raise ValueError("blob_name contains a null byte")

    # Sanitize the name: strip any path components to prevent path traversal.
    safe_name = os.path.basename(blob_name.replace("\\", "/"))

    if not safe_name or safe_name in (".", ".."):
        raise ValueError("Invalid blob_name")

    # The last extension must be exactly ".bin" (case-insensitive).
    # This rejects double extensions like "file.bin.exe" or "file.bin.php".
    if not safe_name.lower().endswith(".bin"):
        raise ValueError("blob_name must end with '.bin'")

    if not isinstance(blob_bytes, (bytes, bytearray)):
        raise TypeError("blob_bytes must be bytes or bytearray")

    if len(blob_bytes) > 256 * 1024:
        raise ValueError("blob_bytes exceeds the 256KB limit")

    if len(blob_bytes) < 4 or bytes(blob_bytes[:4]) != b"FWR1":
        raise ValueError("Invalid firmware magic header (expected 'FWR1')")

    upload_dir = os.path.abspath(upload_dir)
    os.makedirs(upload_dir, exist_ok=True)

    full_path = os.path.abspath(os.path.join(upload_dir, safe_name))

    # Verify the resolved path is still inside upload_dir.
    try:
        if os.path.commonpath([full_path, upload_dir]) != upload_dir:
            raise ValueError("Path traversal detected")
    except ValueError:
        raise ValueError("Path traversal detected")

    with open(full_path, "wb") as f:
        f.write(bytes(blob_bytes))

    return f"Firmware stored at {full_path}"
```

