import os
from werkzeug.utils import secure_filename

def upload_web_template(user_id, file_name, file_content, file_type, base_dir):
    # Validate file type against allow-list
    allowed_types = {"html": ".html", "css": ".css"}
    if file_type not in allowed_types:
        raise ValueError(f"Invalid file type. Allowed types are: {list(allowed_types.keys())}")

    # Sanitize the filename to prevent path traversal attacks
    safe_filename = secure_filename(file_name)
    if not safe_filename:
        raise ValueError("Invalid file name.")

    # Ensure the file extension matches the allowed type
    expected_ext = allowed_types[file_type]
    if not safe_filename.lower().endswith(expected_ext):
        raise ValueError(f"File extension does not match the allowed type '{file_type}'.")

    # Create user-specific directory within base_dir to isolate uploads
    safe_user_id = secure_filename(str(user_id))
    user_dir = os.path.join(base_dir, safe_user_id)

    try:
        os.makedirs(user_dir, exist_ok=True)
    except OSError as e:
        raise RuntimeError(f"Failed to create directory: {e}")

    # Construct the full file path and ensure it remains within user_dir
    file_path = os.path.abspath(os.path.join(user_dir, safe_filename))
    if not file_path.startswith(os.path.abspath(user_dir)):
        raise PermissionError("Access denied: Path traversal detected.")

    # Write the content to the file
    try:
        with open(file_path, "w", encoding="utf-8") as f:
            f.write(file_content)
    except IOError as e:
        raise IOError(f"Failed to write file: {e}")

    return "Web template uploaded successfully."

