```python
import os
import tempfile


def upload_web_template(user_id, file_name, file_content, file_type, base_dir):
    if not isinstance(user_id, str) or not user_id:
        raise ValueError("Invalid user_id.")

    if not isinstance(file_name, str) or not file_name:
        raise ValueError("Invalid file name.")
    if "\x00" in file_name or any(ord(ch) < 32 for ch in file_name):
        raise ValueError("Invalid file name.")
    if os.path.isabs(file_name) or os.path.basename(file_name) != file_name:
        raise ValueError("Invalid file name.")
    if file_name in (".", "..") or "/" in file_name or "\\" in file_name:
        raise ValueError("Invalid file name.")

    if not isinstance(file_type, str):
        raise ValueError("Invalid file type.")
    file_type = file_type.lower()
    if file_type not in ("html", "css"):
        raise ValueError("Unsupported file type.")

    expected_extension = "." + file_type
    if os.path.splitext(file_name)[1].lower() != expected_extension:
        raise ValueError("File extension does not match file type.")

    if isinstance(file_content, str):
        content = file_content.encode("utf-8")
    elif isinstance(file_content, (bytes, bytearray)):
        content = bytes(file_content)
    else:
        raise TypeError("file_content must be str or bytes.")

    base_dir = os.path.realpath(os.fspath(base_dir))
    os.makedirs(base_dir, exist_ok=True)
    if not os.path.isdir(base_dir):
        raise NotADirectoryError(base_dir)

    target_path = os.path.join(base_dir, file_name)
    if os.path.commonpath([base_dir, os.path.realpath(target_path)]) != base_dir:
        raise ValueError("Invalid file path.")

    fd = None
    temp_path = None
    try:
        fd, temp_path = tempfile.mkstemp(prefix=".upload-", dir=base_dir)
        with os.fdopen(fd, "wb") as temp_file:
            fd = None
            temp_file.write(content)
        os.replace(temp_path, target_path)
        temp_path = None
    finally:
        if fd is not None:
            os.close(fd)
        if temp_path is not None:
            try:
                os.unlink(temp_path)
            except FileNotFoundError:
                pass

    return "Web template uploaded successfully."
```

