import os
import re

_ALLOWED_FILE_TYPES = {"html", "css"}
_MAX_UPLOAD_SIZE = 5 * 1024 * 1024
_SAFE_FILENAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,254}$")


def upload_web_template(user_id, file_name, file_content, file_type, base_dir):
    if not isinstance(file_name, str) or not file_name:
        raise ValueError("file_name must be a non-empty string")

    if not isinstance(file_type, str):
        raise TypeError("file_type must be a string")

    normalized_type = file_type.strip().lower()
    if normalized_type not in _ALLOWED_FILE_TYPES:
        raise ValueError(f"Unsupported file type: {file_type!r}")

    if "\x00" in file_name or os.path.basename(file_name) != file_name:
        raise ValueError("Invalid file name")

    if not _SAFE_FILENAME_RE.fullmatch(file_name):
        raise ValueError("Invalid file name")

    _, extension = os.path.splitext(file_name)
    if extension.lower() != f".{normalized_type}":
        raise ValueError("File extension does not match file_type")

    if isinstance(file_content, str):
        data = file_content.encode("utf-8")
    elif isinstance(file_content, (bytes, bytearray)):
        data = bytes(file_content)
    else:
        raise TypeError("file_content must be str or bytes")

    if len(data) > _MAX_UPLOAD_SIZE:
        raise ValueError("File content exceeds maximum allowed size")

    base_path = os.path.realpath(os.path.abspath(os.fspath(base_dir)))
    os.makedirs(base_path, exist_ok=True)

    target_path = os.path.realpath(os.path.join(base_path, file_name))
    try:
        if os.path.commonpath([base_path, target_path]) != base_path:
            raise ValueError("Target path escapes base_dir")
    except ValueError as exc:
        raise ValueError("Target path escapes base_dir") from exc

    flags = (
        os.O_WRONLY
        | os.O_CREAT
        | os.O_TRUNC
        | getattr(os, "O_BINARY", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )

    fd = os.open(target_path, flags, 0o644)
    try:
        with os.fdopen(fd, "wb") as file_handle:
            file_handle.write(data)
    except Exception:
        try:
            os.close(fd)
        except OSError:
            pass
        raise

    return "Web template uploaded successfully."
```

