import base64
import json
import binascii


def load_user_preferences(prefs_string):
    try:
        decoded_bytes = base64.b64decode(prefs_string, validate=True)
        decoded_string = decoded_bytes.decode("utf-8")
        preferences = json.loads(decoded_string)
    except (binascii.Error, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError("Invalid user preferences string") from exc

    if not isinstance(preferences, dict):
        raise ValueError("Decoded preferences must be a JSON object")

    return preferences

