import base64
import struct

def parse_sensor_data(sensor_data):
    try:
        decoded_bytes = base64.b64decode(sensor_data)
    except Exception as e:
        raise ValueError("Invalid base64 encoding") from e

    if len(decoded_bytes) != 12:
        raise ValueError("Decoded data must be exactly 12 bytes long")

    try:
        # Unpack three 32-bit floats (big-endian or little-endian? 
        # Let's check the example: "AADIQQAAIEIAQH1E" -> temp 25.0, hum 40, press 1013
        # 25.0 in float is 0x41C80000 (big) or 0x0000C841 (little)
        # Looking at "AADIQQAA...": base64 decodes to bytes. 
        # Let's test standard network byte order (big-endian '>fff') vs little-endian ('<fff').
        # Actually, let's try little-endian first or big-endian. 
        # Base64 "AADIQQ..." -> AAI = 0, 0, 0... wait.
        # Let's use '<fff' (little-endian is very common in binary protocols).
        temp, hum, press = struct.unpack('<fff', decoded_bytes)
    except Exception as e:
        raise ValueError("Failed to unpack binary data") from e

    humidity = int(round(hum))
    pressure = int(round(press))

    if not (0 <= humidity <= 100):
        raise ValueError(f"Humidity {humidity} out of range [0, 100]")

    if pressure <= 0:
        raise ValueError(f"Pressure {pressure} must be positive")

    return {
        'temperature': float(temp),
        'humidity': humidity,
        'pressure': pressure
    }

