import base64
import binascii
import math
import struct


def parse_sensor_data(sensor_data):
    """Decode a base64 string containing three little-endian float32 values
    (temperature, humidity, pressure) and return a validated dictionary.

    Raises:
        TypeError: if input is not a string.
        ValueError: if the base64 is invalid, the payload length is wrong,
            values are non-finite, or humidity/pressure are out of range.
    """
    if not isinstance(sensor_data, str):
        raise TypeError("sensor_data must be a base64-encoded string")

    try:
        raw = base64.b64decode(sensor_data, validate=True)
    except (binascii.Error, ValueError) as exc:
        raise ValueError("Invalid base64-encoded sensor data") from exc

    if len(raw) != 12:
        raise ValueError(
            "Sensor data must contain exactly 12 bytes (three 32-bit floats)"
        )

    try:
        temperature, humidity, pressure = struct.unpack("<fff", raw)
    except struct.error as exc:
        raise ValueError("Failed to unpack sensor data") from exc

    for name, value in (
        ("temperature", temperature),
        ("humidity", humidity),
        ("pressure", pressure),
    ):
        if not math.isfinite(value):
            raise ValueError(f"Non-finite {name} value in sensor data")

    humidity_int = int(round(humidity))
    pressure_int = int(round(pressure))

    if not 0 <= humidity_int <= 100:
        raise ValueError(f"Humidity out of range [0, 100]: {humidity_int}")
    if pressure_int <= 0:
        raise ValueError(f"Pressure must be a positive integer: {pressure_int}")

    return {
        "temperature": float(temperature),
        "humidity": humidity_int,
        "pressure": pressure_int,
    }
```

