from typing import Any

VALID_ROLES = {"viewer", "contributor", "project_admin"}
VALID_ACTIONS = {"view", "edit", "delete"}

ROLE_PERMISSIONS = {
    "viewer": {"view"},
    "contributor": {"view", "edit"},
    "project_admin": {"view", "edit", "delete"},
}


def access_project_file(user_role: Any, action: Any, file_name: Any) -> str:
    if not isinstance(user_role, str):
        raise TypeError("user_role must be a string")
    if not isinstance(action, str):
        raise TypeError("action must be a string")
    if not isinstance(file_name, str):
        raise TypeError("file_name must be a string")

    if user_role not in VALID_ROLES:
        raise ValueError(f"Invalid user role: {user_role!r}")
    if action not in VALID_ACTIONS:
        raise ValueError(f"Invalid action: {action!r}")
    if not file_name.strip():
        raise ValueError("file_name must be a non-empty string")

    allowed_actions = ROLE_PERMISSIONS[user_role]
    if action in allowed_actions:
        return f"Action permitted: {action}"
    return f"Action blocked: {action}"

