from typing import Any, Dict, Optional


class InvoiceDownloadError(Exception):
    """Base class for invoice download failures."""


class InvalidInvoiceRequestError(InvoiceDownloadError, ValueError):
    """Raised when the request arguments are malformed or unusable."""


def _validate_user_id(user_id: Optional[int]) -> None:
    if user_id is None:
        return
    # bool is a subclass of int; reject it explicitly.
    if isinstance(user_id, bool) or not isinstance(user_id, int):
        raise InvalidInvoiceRequestError("user_id must be an int or None.")


def _validate_invoice_id(invoice_id: str) -> None:
    if not isinstance(invoice_id, str) or not invoice_id.strip():
        raise InvalidInvoiceRequestError("invoice_id must be a non-empty string.")
    # Defensive: reject control characters / absurdly long identifiers.
    if len(invoice_id) > 128 or any(ord(ch) < 0x20 or ord(ch) == 0x7F for ch in invoice_id):
        raise InvalidInvoiceRequestError("invoice_id contains invalid characters.")


def _validate_invoice_owner(invoice_owner: Dict[str, int]) -> None:
    if not isinstance(invoice_owner, dict):
        raise InvalidInvoiceRequestError("invoice_owner must be a dict mapping invoice_id -> owner_user_id.")


def download_invoice(
    user_id: Optional[int],
    invoice_id: str,
    invoice_owner: Dict[str, int],
) -> str:
    """Authorize and perform an invoice download request.

    Returns one of the four contract status strings. Malformed input raises
    InvalidInvoiceRequestError instead of silently succeeding or failing.
    """
    _validate_user_id(user_id)
    _validate_invoice_id(invoice_id)
    _validate_invoice_owner(invoice_owner)

    # Authenticate before revealing anything about invoice existence, so that
    # unauthenticated callers cannot enumerate invoices.
    if user_id is None:
        return "Authentication required."

    if invoice_id not in invoice_owner:
        return "Invoice not found."

    owner = invoice_owner[invoice_id]
    if isinstance(owner, bool) or not isinstance(owner, int):
        # Corrupt ownership data is an operational error, not a client error.
        raise InvoiceDownloadError("Invoice ownership record is invalid.")

    if owner != user_id:
        return "Access denied."

    return "Invoice downloaded."
```

