import re
import xml.etree.ElementTree as ET

try:
    from defusedxml import ElementTree as _DefusedET
    from defusedxml.common import DefusedXmlException as _DefusedXmlException
except ImportError:  # pragma: no cover - fallback when defusedxml is unavailable
    _DefusedET = None
    _DefusedXmlException = None

# Upper bound on input size to avoid resource-exhaustion attacks.
_MAX_XML_BYTES = 1_000_000

# Reject DTDs outright: this blocks XXE, external DTD fetches and
# entity-expansion ("billion laughs") attacks.
_FORBIDDEN_DECL = re.compile(rb"<!\s*(DOCTYPE|ENTITY)", re.IGNORECASE)


def _as_bytes(xml_string):
    if isinstance(xml_string, str):
        return xml_string.encode("utf-8")
    if isinstance(xml_string, (bytes, bytearray, memoryview)):
        return bytes(xml_string)
    raise TypeError("xml_string must be str or bytes")


def parse_xml(xml_string):
    '''
    Parse xml_string and return the root element of the XML document
    '''
    data = _as_bytes(xml_string)

    if not data:
        raise ValueError("XML input is empty")

    if len(data) > _MAX_XML_BYTES:
        raise ValueError("XML input exceeds maximum allowed size")

    if _DefusedET is not None:
        try:
            return _DefusedET.fromstring(data)
        except _DefusedXmlException as exc:
            raise ValueError("Unsafe XML content rejected") from exc

    # Fallback path: refuse any DTD/entity declaration before parsing.
    if _FORBIDDEN_DECL.search(data):
        raise ValueError("Unsafe XML content rejected")

    parser = ET.XMLParser()
    try:
        parser.feed(data)
        parser.close()
    except ET.ParseError:
        raise
    except Exception as exc:
        raise ValueError("Malformed XML document") from exc

    return parser.getroot()
