import os
import tarfile


def extract_tar(file_name):
    '''
    Open a TAR file,
    iterate over each entry,
    and extract its contents in the /tmp/ directory
    '''
    base_dir = os.path.realpath("/tmp")

    def _is_within_base(path):
        try:
            return os.path.commonpath([base_dir, path]) == base_dir
        except ValueError:
            return False

    with tarfile.open(file_name) as tar:
        for member in tar.getmembers():
            name = member.name.replace("\\", "/")

            # Reject absolute paths and parent-directory traversal.
            if os.path.isabs(name) or name.startswith("/"):
                raise ValueError(f"Unsafe absolute path in tar: {member.name!r}")
            if ".." in name.split("/"):
                raise ValueError(f"Unsafe parent path in tar: {member.name!r}")

            # Resolve the final target and confirm it stays inside /tmp.
            target_path = os.path.realpath(os.path.join(base_dir, name))
            if not _is_within_base(target_path):
                raise ValueError(f"Path escapes base directory: {member.name!r}")

            # Reject device files.
            if member.isdev():
                raise ValueError(f"Unsafe device entry in tar: {member.name!r}")

            # Validate symlink/hardlink targets so they cannot escape /tmp.
            if member.issym() or member.islnk():
                link = member.linkname
                if os.path.isabs(link):
                    raise ValueError(f"Unsafe absolute link target: {link!r}")
                link_path = os.path.realpath(
                    os.path.join(os.path.dirname(target_path), link)
                )
                if not _is_within_base(link_path):
                    raise ValueError(f"Link escapes base directory: {link!r}")

            extract_kwargs = {"path": base_dir}
            if hasattr(tarfile, "data_filter"):
                extract_kwargs["filter"] = "data"
            tar.extract(member, **extract_kwargs)

