import re
from html.parser import HTMLParser

class ScriptTagRemover(HTMLParser):
    """
    Custom HTML parser that discards <script> tags and their content.
    """
    def __init__(self):
        super().__init__()
        self._in_script = False
        self.result = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "script":
            self._in_script = True
        elif not self._in_script:
            attrs_str = "".join(f' {k}="{v}"' for k, v in attrs)
            self.result.append(f"<{tag}{attrs_str}>")

    def handle_endtag(self, tag):
        if tag.lower() == "script":
            self._in_script = False
        elif not self._in_script:
            self.result.append(f"</{tag}>")

    def handle_startendtag(self, tag, attrs):
        if tag.lower() != "script":
            attrs_str = "".join(f' {k}="{v}"' for k, v in attrs)
            self.result.append(f"<{tag}{attrs_str}/>")

    def handle_data(self, data):
        if not self._in_script:
            self.result.append(data)

    def handle_comment(self, data):
        if not self._in_script:
            self.result.append(f"<!--{data}-->")

    def get_clean_html(self):
        return "".join(self.result)

def filterScriptTags(content: str) -> str:
    """
    Remove <script> tags and any content inside them from the provided HTML string.
    The function is resilient against malformed or nested tags and preserves
    the rest of the document unchanged.
    """
    if not isinstance(content, str):
        raise TypeError("content must be a string")

    parser = ScriptTagRemover()
    parser.feed(content)
    parser.close()
    return parser.get_clean_html()
