import logging


logger = logging.getLogger(__name__)


def _sanitize_for_log(value: str) -> str:
    """Escape control characters and newlines to prevent log injection."""
    return "".join(
        char if char.isprintable() and char not in "\r\n" else char.encode("unicode_escape").decode("ascii")
        for char in value
    )


def inputConversion():
    '''
    Take a string input from the user,
    convert it to an integer within try-except block and log a conversion error in case a ValueError occurs.
    Return the converted user input.
    '''
    user_input = input("Enter an integer: ")

    try:
        return int(user_input)
    except ValueError:
        safe_input = _sanitize_for_log(user_input)
        logger.error("Conversion error: could not convert input %r to an integer", safe_input)
        raise
