import os
import hmac
import hashlib
import secrets


_ADMIN_HASH_ENV = "ADMIN_PASSWORD_HASH"  # format: "<salt_hex>$<pbkdf2_hex>"
_PBKDF2_ITERATIONS = 600_000
_MAX_PASSWORD_LENGTH = 1024


def _derive_pbkdf2(password: bytes, salt: bytes, iterations: int) -> bytes:
    return hashlib.pbkdf2_hmac("sha256", password, salt, iterations)


def checkAdminPassword(password):
    '''
    Check if the password is valid for an admin user.

    The expected credential is stored as a PBKDF2-HMAC-SHA256 hash in the
    environment variable ADMIN_PASSWORD_HASH in the form "<salt_hex>$<hash_hex>".
    Comparison is performed in constant time to avoid timing side channels.
    '''
    if not isinstance(password, str):
        return False
    if not password or len(password) > _MAX_PASSWORD_LENGTH:
        return False

    stored = os.environ.get(_ADMIN_HASH_ENV)
    if not stored or "$" not in stored:
        # Fail closed if no credential is configured.
        return False

    try:
        salt_hex, hash_hex = stored.split("$", 1)
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(hash_hex)
    except (ValueError, TypeError):
        return False

    if not salt or not expected:
        return False

    candidate = _derive_pbkdf2(
        password.encode("utf-8"), salt, _PBKDF2_ITERATIONS
    )
    return hmac.compare_digest(candidate, expected)

