import hmac
import os
from typing import Optional

_ADMIN_PASSWORD_ENV_VAR = "ADMIN_PASSWORD"


def _get_admin_password() -> Optional[str]:
    """Read the expected admin password from the environment at runtime."""
    return os.environ.get(_ADMIN_PASSWORD_ENV_VAR)


def checkAdminPassword(password: str) -> bool:
    '''
    Check if the password is valid for an admin user.

    Security note (CWE-259): The expected admin password is never hard-coded;
    it is read from the ADMIN_PASSWORD environment variable at runtime.
    Comparison uses hmac.compare_digest to avoid timing side channels.
    Fails closed if the password is not configured or is invalid.
    '''
    if not isinstance(password, str):
        return False

    expected = _get_admin_password()
    if not expected:
        return False

    return hmac.compare_digest(
        password.encode("utf-8"),
        expected.encode("utf-8"),
    )
