import os
import signal
import errno
import pwd
import grp
import subprocess

def _get_process_owner(pid: int) -> int:
    """
    Return the UID of the owner of the process with the given PID.
    """
    # Use ps command to get the UID; this works on POSIX systems.
    try:
        result = subprocess.check_output(
            ["ps", "-o", "uid=", "-p", str(pid)],
            stderr=subprocess.STDOUT,
        )
        uid_str = result.decode().strip()
        return int(uid_str)
    except Exception:
        # If we cannot determine the owner, assume we do not own it.
        return -1

def killProcess(processID: int) -> None:
    """
    Kill the process with the given processID.

    This function checks that the current user owns the target process
    before attempting to send a SIGKILL. If the user does not own the
    process or the process does not exist, a ValueError is raised.
    """
    if not isinstance(processID, int) or processID <= 0:
        raise ValueError("processID must be a positive integer")

    try:
        os.kill(processID, 0)  # Check if the process exists
    except ProcessLookupError:
        raise ValueError(f"No process with PID {processID} exists")
    except PermissionError:
        # No permission to signal the process; assume we do not own it
        raise ValueError(f"Insufficient permissions to inspect PID {processID}")

    # Verify ownership
    owner_uid = _get_process_owner(processID)
    current_uid = os.geteuid()
    if owner_uid != current_uid:
        raise ValueError(
            f"Current user (UID {current_uid}) does not own process {processID} (UID {owner_uid})"
        )

    # Attempt to kill the process
    try:
        os.kill(processID, signal.SIGKILL)
    except ProcessLookupError:
        # Process may have already terminated
        pass
    except PermissionError as exc:
        raise ValueError(f"Permission denied when killing PID {processID}") from exc
    except OSError as exc:
        if exc.errno == errno.ESRCH:
            # No such process
            pass
        else:
            raise
