import os
import signal


def killProcess(processID):
    """Kill the process with the given processID securely."""
    if not isinstance(processID, int) or processID <= 0:
        raise ValueError("Invalid process ID")

    # Ensure we don't accidentally kill the init process or current process
    if processID == 1 or processID == os.getpid():
        raise PermissionError("Operation not permitted for this PID")

    try:
        os.kill(processID, signal.SIGKILL)
    except ProcessLookupError:
        # Process does not exist
        pass
    except PermissionError:
        # Insufficient privileges
        raise
