import os
import signal


def killProcess(processID):
    """Kill the process with the given processID after verifying ownership."""
    try:
        # Get the real user ID of the current process
        current_uid = os.getuid()

        # On Unix-like systems, we can check the process owner by reading /proc/[pid]/status
        # or by using os.kill with signal 0 to check existence and permissions first.
        # However, checking /proc/pid/status is more robust for ownership verification.
        status_path = f"/proc/{processID}/status"
        if os.path.exists(status_path):
            process_uid = None
            with open(status_path, "r") as f:
                for line in f:
                    if line.startswith("Uid:"):
                        # Uid line contains: Uid: real effective saved fs
                        parts = line.split()
                        process_uid = int(parts[1])
                        break

            # Verify ownership (allow if current user is owner or root)
            if process_uid is not None and (
                current_uid == 0 or current_uid == process_uid
            ):
                os.kill(processID, signal.SIGTERM)
            else:
                raise PermissionError(
                    f"Caller does not own process {processID}"
                )
        else:
            # Fallback if /proc is not available: use os.kill and catch PermissionError
            # Note: os.kill(pid, 0) checks if process exists and we have permission to send signals.
            os.kill(processID, 0)  # Check if we can signal it
            os.kill(processID, signal.SIGTERM)

    except ProcessLookupError:
        raise ValueError(f"Process with ID {processID} not found.")
    except PermissionError:
        raise PermissionError(
            f"Permission denied: Caller does not own process {processID}"
        )
