import os
import signal


def killProcess(processID):
    '''
    Kill the process with the given processID.
    '''
    # Validate input strictly to avoid injection / unexpected types.
    if isinstance(processID, bool) or not isinstance(processID, int):
        raise TypeError("processID must be an integer")

    # Reject non-positive PIDs (0 and negative values have special meanings).
    if processID <= 0:
        raise ValueError("processID must be a positive integer")

    # Never signal init (PID 1) or our own process.
    if processID == 1:
        raise PermissionError("Refusing to kill PID 1")
    if processID == os.getpid():
        raise PermissionError("Refusing to kill the current process")

    try:
        os.kill(processID, signal.SIGTERM)
    except ProcessLookupError:
        raise ProcessLookupError(f"No such process: {processID}")
    except PermissionError:
        raise PermissionError(f"Not permitted to kill process: {processID}")
    except OSError as exc:
        raise OSError(f"Failed to kill process {processID}: {exc}") from exc
