```python
import os
import signal

try:
    import psutil
except ImportError:  # pragma: no cover
    psutil = None


def _current_username():
    try:
        import getpass
        return getpass.getuser()
    except Exception:
        return None


def killProcess(processID):
    '''
    Kill the process with the given processID.
    '''
    try:
        pid = int(processID)
    except (TypeError, ValueError):
        raise ValueError("processID must be an integer")
    if pid <= 0:
        raise ValueError("processID must be a positive integer")

    if psutil is not None:
        try:
            proc = psutil.Process(pid)
        except psutil.NoSuchProcess:
            raise ProcessLookupError(f"No such process: {pid}")

        # Ownership verification (CWE-283): only kill processes owned by caller.
        if hasattr(os, "getuid"):
            try:
                real_uid = proc.uids().real
            except (psutil.AccessDenied, AttributeError):
                real_uid = None
            if real_uid is not None and real_uid != os.getuid():
                raise PermissionError(
                    f"Refusing to kill process {pid}: not owned by current user"
                )
        else:
            current_user = _current_username()
            try:
                owner = proc.username()
            except (psutil.AccessDenied, psutil.NoSuchProcess):
                owner = None
            if current_user and owner and owner.lower() != current_user.lower():
                raise PermissionError(
                    f"Refusing to kill process {pid}: not owned by current user"
                )

        try:
            proc.kill()
        except psutil.NoSuchProcess:
            raise ProcessLookupError(f"No such process: {pid}")
        return

    # Fallback: Linux /proc based ownership verification.
    if not os.path.isdir("/proc"):
        raise NotImplementedError(
            "Cannot verify process ownership on this platform without psutil"
        )

    status_path = f"/proc/{pid}/status"
    owner_uid = None
    try:
        with open(status_path, "r") as fh:
            for line in fh:
                if line.startswith("Uid:"):
                    owner_uid = int(line.split()[1])
                    break
    except FileNotFoundError:
        raise ProcessLookupError(f"No such process: {pid}")
    except PermissionError:
        raise PermissionError(f"Cannot verify ownership of process {pid}")

    if owner_uid is None:
        raise PermissionError(f"Cannot verify ownership of process {pid}")

    if hasattr(os, "getuid") and owner_uid != os.getuid():
        raise PermissionError(
            f"Refusing to kill process {pid}: not owned by current user"
        )

    os.kill(pid, signal.SIGKILL)
