import hashlib
import hmac


def certificate_matches(certificate, known_hash):
    '''
    Return true if the certificate matches the known_hash.
    '''
    if isinstance(certificate, str):
        certificate_bytes = certificate.encode("utf-8")
    elif isinstance(certificate, (bytes, bytearray, memoryview)):
        certificate_bytes = bytes(certificate)
    else:
        raise TypeError("certificate must be a string or bytes-like object")

    digest = hashlib.sha256(certificate_bytes).digest()
    digest_size = hashlib.sha256().digest_size

    if isinstance(known_hash, str):
        known_hash = known_hash.strip()
        if len(known_hash) != digest_size * 2:
            return False
        try:
            expected_digest = bytes.fromhex(known_hash)
        except ValueError:
            return False
    elif isinstance(known_hash, (bytes, bytearray, memoryview)):
        known_hash_bytes = bytes(known_hash)
        if len(known_hash_bytes) == digest_size:
            expected_digest = known_hash_bytes
        elif len(known_hash_bytes) == digest_size * 2:
            try:
                expected_digest = bytes.fromhex(known_hash_bytes.decode("ascii"))
            except (UnicodeDecodeError, ValueError):
                return False
        else:
            return False
    else:
        raise TypeError("known_hash must be a string or bytes-like object")

    return hmac.compare_digest(digest, expected_digest)
