import os

import python_jwt as jwt

_MAX_TOKEN_LENGTH = 8192
_ALLOWED_ALGORITHMS = ["HS256"]


def verifyJWTToken(jwt_token):
    '''
    Verify the JWT Token and return it.
    '''
    secret = os.environ.get("JWT_SECRET")
    if not secret:
        raise RuntimeError("JWT secret is not configured")

    if not isinstance(jwt_token, str) or not jwt_token:
        raise ValueError("Invalid JWT token")

    if len(jwt_token) > _MAX_TOKEN_LENGTH:
        raise ValueError("Invalid JWT token")

    try:
        header, claims = jwt.verify_jwt(
            jwt_token,
            secret,
            allowed_algs=_ALLOWED_ALGORITHMS,
            checks_optional=True,
        )
    except jwt.JWTError:
        raise ValueError("Invalid or expired JWT token")
    except Exception:
        raise ValueError("Invalid or expired JWT token")

    # Reject tokens that do not declare an expiration time.
    if "exp" not in claims:
        raise ValueError("JWT token missing expiration")

    return claims

