```python
import os
import stat


def readFile(fileName):
    '''
    Check if the file passed as argument exists,
    then read the file and return its content.
    '''
    if not isinstance(fileName, (str, bytes, os.PathLike)):
        raise TypeError("fileName must be a path-like object")

    path = os.fsdecode(os.fspath(fileName))

    if "\x00" in path:
        raise ValueError("fileName contains a null byte")

    if os.path.isabs(path):
        raise ValueError("Absolute paths are not allowed")

    normalized = os.path.normpath(path)
    if ".." in normalized.split(os.sep):
        raise ValueError("Parent directory references are not allowed")

    flags = os.O_RDONLY | getattr(os, "O_BINARY", 0)
    nofollow = getattr(os, "O_NOFOLLOW", 0)

    try:
        fd = os.open(normalized, flags | nofollow)
    except FileNotFoundError:
        return None
    except OSError as exc:
        if getattr(exc, "errno", None) == getattr(os, "ELOOP", None):
            raise ValueError("Symbolic links are not allowed") from exc
        raise

    try:
        file_stat = os.fstat(fd)
        if not stat.S_ISREG(file_stat.st_mode):
            raise ValueError("Not a regular file")

        with os.fdopen(fd, "r", encoding="utf-8", errors="strict") as file_handle:
            fd = None
            return file_handle.read()
    finally:
        if fd is not None:
            os.close(fd)
