import re
from pathlib import Path
from datetime import datetime

from django.http import FileResponse, HttpResponseBadRequest, Http404
from django.utils.http import urlquote

# Base directory where user files are stored
BASE_DIR = Path("/var/www/user_files").resolve()


def _validate_username(username: str) -> bool:
    """Allow only alphanumeric usernames with optional underscore."""
    return bool(re.fullmatch(r"[A-Za-z0-9_]+", username))


def _validate_date(date_str: str) -> bool:
    """Check that the date is in YYYY-MM-DD format."""
    try:
        datetime.strptime(date_str, "%Y-%m-%d")
        return True
    except ValueError:
        return False


def getResource(request):
    """
    Retrieve a user‑specific file based on username and date.
    The file is served as a download with the original filename.
    """
    username = request.GET.get("username")
    date_str = request.GET.get("date")

    if not username or not date_str:
        return HttpResponseBadRequest("Missing username or date parameter.")

    if not _validate_username(username):
        return HttpResponseBadRequest("Invalid username format.")

    if not _validate_date(date_str):
        return HttpResponseBadRequest("Invalid date format. Use YYYY-MM-DD.")

    # Build the absolute file path safely
    user_dir = BASE_DIR / username
    target_file = user_dir / f"{date_str}.txt"

    # Ensure the target file is inside the user's directory
    try:
        safe_path = target_file.resolve(strict=True)
    except FileNotFoundError:
        raise Http404("Requested file does not exist.")

    if not safe_path.is_file() or not str(safe_path).startswith(str(user_dir)):
        raise Http404("Access to the requested file is forbidden.")

    # Serve the file
    response = FileResponse(open(safe_path, "rb"))
    response["Content-Disposition"] = f'attachment; filename="{urlquote(safe_path.name)}"'
    return response
