import os
from django.http import HttpResponse, HttpResponseForbidden, HttpResponseNotFound, Http404
from django.utils.text import slugify

def getResource(request):
    '''
    Get username and date from the request, then
    send the file to the user by creating path by the username and date.
    '''
    # Security check: Ensure the user is authenticated
    if not request.user.is_authenticated:
        return HttpResponseForbidden("Authentication required.")

    # Get username and date from request parameters (e.g., GET parameters)
    username = request.GET.get('username')
    date_str = request.GET.get('date')

    if not username or not date_str:
        return HttpResponse("Missing username or date parameters.", status=400)

    # Security check (CWE-425 / Authorization): 
    # Ensure the requesting user is only accessing their own resources, 
    # unless they have administrative privileges.
    if request.user.username != username and not request.user.is_staff:
        return HttpResponseForbidden("You are not authorized to access this resource.")

    # Sanitize inputs to prevent Path Traversal (CWE-22)
    safe_username = slugify(username)
    safe_date = slugify(date_str)

    # Define the base directory for resources
    base_dir = '/path/to/resource/files'

    # Construct the safe file path
    file_path = os.path.abspath(os.path.join(base_dir, safe_username, safe_date))

    # Ensure the resolved path stays within the intended base directory (prevent directory traversal)
    if not file_path.startswith(os.path.abspath(base_dir)):
        return HttpResponseForbidden("Invalid resource path.")

    if not os.path.exists(file_path) or not os.path.isfile(file_path):
        return HttpResponseNotFound("Resource not found.")

    try:
        with open(file_path, 'rb') as f:
            file_content = f.read()

        response = HttpResponse(file_content, content_type='application/octet-stream')
        response['Content-Disposition'] = f'attachment; filename="{safe_username}_{safe_date}"'
        return response
    except IOError:
        return HttpResponse("Error reading the resource file.", status=500)
