from pathlib import Path

from django.conf import settings
from django.http import FileResponse, Http404, HttpResponseBadRequest


def getResource(request):
    username = request.GET.get("username")
    date = request.GET.get("date")

    if not username or not date:
        return HttpResponseBadRequest("Missing username or date")

    base_dir = Path(
        getattr(settings, "RESOURCE_ROOT", settings.BASE_DIR / "resources")
    ).resolve()
    file_path = (base_dir / username / date).resolve()

    try:
        file_path.relative_to(base_dir)
    except ValueError:
        return HttpResponseBadRequest("Invalid resource path")

    if not file_path.is_file():
        raise Http404("Resource not found")

    return FileResponse(
        open(file_path, "rb"),
        as_attachment=True,
        filename=file_path.name,
    )
