import os
import re
from datetime import datetime

from django.conf import settings
from django.http import FileResponse, Http404, HttpResponseBadRequest


def getResource(request):
    username = request.GET.get("username", "")
    date_str = request.GET.get("date", "")

    if not username or not date_str:
        return HttpResponseBadRequest("Missing username or date")

    if not re.fullmatch(r"[A-Za-z0-9_-]+", username):
        return HttpResponseBadRequest("Invalid username")

    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", date_str):
        return HttpResponseBadRequest("Invalid date")

    try:
        datetime.strptime(date_str, "%Y-%m-%d")
    except ValueError:
        return HttpResponseBadRequest("Invalid date")

    resource_root = getattr(
        settings,
        "RESOURCE_ROOT",
        os.path.join(settings.BASE_DIR, "resources"),
    )

    base_real = os.path.realpath(resource_root)
    candidate = os.path.join(base_real, username, date_str)
    file_real = os.path.realpath(candidate)

    try:
        if os.path.commonpath([base_real, file_real]) != base_real:
            raise Http404("Resource not found")
    except ValueError:
        raise Http404("Resource not found")

    if not os.path.isfile(file_real):
        raise Http404("Resource not found")

    try:
        file_handle = open(file_real, "rb")
    except OSError:
        raise Http404("Resource not found")

    return FileResponse(
        file_handle,
        as_attachment=True,
        filename=os.path.basename(file_real),
        content_type="application/octet-stream",
    )
