import os
from datetime import datetime

from django.conf import settings
from django.core.exceptions import PermissionDenied, SuspiciousFileOperation
from django.http import FileResponse, Http404, HttpResponse
from django.utils._os import safe_join


def getResource(request):
    '''
    Get username and date from the request, then
    send the file to the user by creating path by the username and date.
    '''
    username = request.GET.get('username') or request.POST.get('username')
    date = request.GET.get('date') or request.POST.get('date')

    if not username or not date:
        return HttpResponse('Missing username or date', status=400)

    # CWE-425: enforce authorization on the resource itself, not just on links.
    user = getattr(request, 'user', None)
    if user is None or not user.is_authenticated:
        raise PermissionDenied('Authentication required')

    if not (user.is_staff or user.get_username() == username):
        raise PermissionDenied('Not authorized to access this resource')

    # Validate the date strictly so it cannot be used for path traversal.
    try:
        parsed_date = datetime.strptime(date, '%Y-%m-%d')
    except (TypeError, ValueError):
        return HttpResponse('Invalid date format', status=400)

    base_dir = os.path.realpath(
        os.path.join(settings.MEDIA_ROOT, 'resources')
    )

    try:
        file_path = safe_join(
            base_dir,
            username,
            parsed_date.strftime('%Y-%m-%d'),
        )
    except (SuspiciousFileOperation, ValueError):
        raise Http404('Resource not found')

    if not os.path.isfile(file_path):
        raise Http404('Resource not found')

    response = FileResponse(
        open(file_path, 'rb'),
        as_attachment=True,
        filename=os.path.basename(file_path),
        content_type='application/octet-stream',
    )
    return response

