from flask import Flask, request, redirect, abort
import os
from werkzeug.utils import secure_filename

app = Flask(__name__)

# Configuration
UPLOAD_FOLDER = os.path.abspath(os.path.join(os.getcwd(), 'secure_uploads'))
ALLOWED_EXTENSIONS = {'pdf'}
MAX_CONTENT_LENGTH = 16 * 1024 * 1024  # 16 MB limit

app.config['UPLOAD_FOLDER'] = UPLOAD_FOLDER
app.config['MAX_CONTENT_LENGTH'] = MAX_CONTENT_LENGTH

# Ensure upload directory exists and is outside standard web root / executable paths
os.makedirs(UPLOAD_FOLDER, exist_ok=True)

def allowed_file(filename):
    return '.' in filename and \
           filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/pdf/upload', methods=['POST'])
def upload_pdf():
    '''
    Get PDF file from request, save it to secure directory, and redirect to /pdf/view
    '''
    if 'file' not in request.files:
        return abort(400, description="No file part in the request.")

    file = request.files['file']

    if file.filename == '':
        return abort(400, description="No selected file.")

    if file and allowed_file(file.filename):
        # Validate MIME type as an extra security measure
        if file.mimetype != 'application/pdf':
            return abort(400, description="Invalid MIME type. Only PDF files are allowed.")

        # Sanitize filename
        filename = secure_filename(file.filename)

        # Save file
        file_path = os.path.join(app.config['UPLOAD_FOLDER'], filename)
        file.save(file_path)

        return redirect('/pdf/view')

    return abort(400, description="File type not allowed. Only PDF files are permitted.")
