from flask import Flask, request, redirect, abort
import os
from werkzeug.utils import secure_filename

app = Flask(__name__)
app.config['MAX_CONTENT_LENGTH'] = 10 * 1024 * 1024  # 10 MB upload limit

UPLOAD_DIR = os.path.join(os.getcwd(), 'uploads')
ALLOWED_EXTENSIONS = {'.pdf'}
ALLOWED_MIMETYPES = {'application/pdf'}


def _allowed_extension(filename):
    ext = os.path.splitext(filename)[1].lower()
    return ext in ALLOWED_EXTENSIONS


@app.route('/pdf/upload', methods=['POST'])
def upload_pdf():
    '''
    Get PDF file from request, save it to ./uploads directory, and redirect to /pdf/view
    '''
    if 'file' not in request.files:
        abort(400, description='No file part in request')

    file = request.files['file']
    if not file or file.filename == '':
        abort(400, description='No file selected')

    if not _allowed_extension(file.filename):
        abort(400, description='Only PDF files are allowed')

    if file.mimetype not in ALLOWED_MIMETYPES:
        abort(400, description='Invalid file type')

    filename = secure_filename(file.filename)
    if not filename:
        abort(400, description='Invalid filename')

    os.makedirs(UPLOAD_DIR, exist_ok=True)

    filepath = os.path.abspath(os.path.join(UPLOAD_DIR, filename))
    if not filepath.startswith(os.path.abspath(UPLOAD_DIR) + os.sep):
        abort(400, description='Invalid filename')

    file.save(filepath)
    return redirect('/pdf/view')
