import hmac

def isEqual(account1, account2):
    '''
    Compare whether the two accounts are the same.
    '''
    if not isinstance(account1, str) or not isinstance(account2, str):
        return False

    # Use constant-time comparison to prevent timing attacks if these represent identifiers or tokens
    return hmac.compare_digest(account1, account2)

