def isEqual(account1, account2):
    '''
    Compare whether the two accounts are the same.

    Two accounts are considered equal when they have the same length and
    every position matches.  A '?' character acts as a wildcard that
    matches any single character on either side.
    '''
    if account1 is None or account2 is None:
        return account1 is account2

    if isinstance(account1, str) and isinstance(account2, str):
        if len(account1) != len(account2):
            return False
        return all(
            a == b or a == '?' or b == '?'
            for a, b in zip(account1, account2)
        )

    return account1 == account2
