import hmac


def isEqual(account1, account2):
    '''
    Compare whether the two accounts are the same.
    '''
    # Reject missing or non-string accounts early.
    if not isinstance(account1, str) or not isinstance(account2, str):
        return False

    try:
        a = account1.encode("utf-8")
        b = account2.encode("utf-8")
    except UnicodeError:
        return False

    # Constant-time comparison to avoid timing side channels.
    return hmac.compare_digest(a, b)

