from django.utils.http import url_has_allowed_host_setting
from django.conf import settings
from urllib.parse import urlparse

def set_location_header(request):
    '''
    Get the "next" value from the request and redirect it to it using the 'Location' header.
    '''
    next_url = request.GET.get('next') or request.POST.get('next')

    # Default fallback URL if 'next' is missing or unsafe
    fallback_url = '/'

    if next_url:
        # Ensure the URL is safe to prevent Open Redirect vulnerabilities
        # Determine the current request's host for validation
        allowed_hosts = {request.get_host()}

        if url_has_allowed_host_setting(next_url, allowed_hosts=allowed_hosts):
            return HttpResponseRedirect(next_url)

    return HttpResponseRedirect(fallback_url)
