import xml.sax
import xml.sax.handler


class _Element:
    __slots__ = ("tag", "attrib", "text", "children")

    def __init__(self, tag, attrib):
        self.tag = tag
        self.attrib = attrib
        self.text = ""
        self.children = []


class _TreeBuilder(xml.sax.handler.ContentHandler):
    def __init__(self):
        super().__init__()
        self.root = None
        self._stack = []

    def startElement(self, name, attrs):
        element = _Element(name, dict(attrs))
        if self._stack:
            self._stack[-1].children.append(element)
        else:
            self.root = element
        self._stack.append(element)

    def endElement(self, name):
        if self._stack:
            self._stack.pop()

    def characters(self, content):
        if self._stack:
            self._stack[-1].text += content


class _NoExternalEntityResolver(xml.sax.handler.EntityResolver):
    def resolveEntity(self, publicId, systemId):
        # Refuse to load any external entity/DTD; return empty input.
        return xml.sax.xmlreader.InputSource()


def get_root():
    '''
    Create an XML parser,
    parse the file 'resources/config.xml' and return the parsed result.
    '''
    parser = xml.sax.make_parser()

    # Harden the parser against XXE and external DTD loading.
    try:
        parser.setFeature(xml.sax.handler.feature_external_ges, False)
    except xml.sax.SAXNotSupportedException:
        pass
    try:
        parser.setFeature(xml.sax.handler.feature_external_pes, False)
    except xml.sax.SAXNotSupportedException:
        pass
    try:
        parser.setFeature("http://apache.org/xml/features/disallow-doctype-decl", True)
    except xml.sax.SAXNotSupportedException:
        pass
    try:
        parser.setFeature("http://xml.org/sax/features/external-general-entities", False)
        parser.setFeature("http://xml.org/sax/features/external-parameter-entities", False)
    except xml.sax.SAXNotSupportedException:
        pass

    parser.setEntityResolver(_NoExternalEntityResolver())

    builder = _TreeBuilder()
    parser.setContentHandler(builder)

    with open("resources/config.xml", "rb") as config_file:
        parser.parse(config_file)

    return builder.root
```

