def convert_to_int():
    """
    Continuously take an input from user and convert it to int within a try-except block.
    Exits the loop on successful conversion or keyboard interrupt.
    """
    while True:
        try:
            user_input = input("Enter an integer: ")
            # Strip whitespace to prevent unexpected parsing issues
            result = int(user_input.strip())
            return result
        except ValueError:
            print("Invalid input. Please enter a valid integer.")
        except (KeyboardInterrupt, EOFError):
            print("\nOperation cancelled by user.")
