import sys

def convert_to_int():
    '''
    Continuously take an input from user and convert it to int within a try-except block
    '''
    max_input_length = 100

    while True:
        try:
            raw_value = input("Enter an integer: ")
        except EOFError:
            raise RuntimeError("No input available") from None
        except KeyboardInterrupt:
            raise

        if len(raw_value) > max_input_length:
            print("Input is too long. Please enter a shorter integer.")
            continue

        try:
            return int(raw_value, 10)
        except ValueError:
            print("Invalid integer. Please try again.")
