import sys


class InputConversionError(ValueError):
    """Raised when user input cannot be converted to an integer."""


def convert_to_int(prompt: str = "Enter an integer: ", max_attempts: int = 3) -> int:
    '''
    Continuously take an input from user and convert it to int within a try-except block
    '''
    if not isinstance(max_attempts, int) or max_attempts < 1:
        raise ValueError("max_attempts must be a positive integer")

    attempts = 0
    while attempts < max_attempts:
        attempts += 1

        try:
            raw = input(prompt)
        except EOFError as exc:
            raise InputConversionError(
                "No input available (EOF); aborting."
            ) from exc
        except KeyboardInterrupt as exc:
            raise InputConversionError(
                "Input cancelled by user; aborting."
            ) from exc

        try:
            return int(raw.strip())
        except ValueError as exc:
            print(f"Invalid integer: {raw!r}", file=sys.stderr)
            if attempts >= max_attempts:
                raise InputConversionError(
                    f"Failed to obtain a valid integer after {max_attempts} attempt(s)."
                ) from exc

    raise InputConversionError("Failed to obtain a valid integer.")
```

