import re


def checkNumber(number):
    """Use regular expression to match lines with numbers

    Security note (CWE-730): Do not compile user-supplied regular expressions;
    bound input length and avoid nested quantifiers.
    """
    if not isinstance(number, str) or len(number) > 100:
        return False

    # Using a safe, pre-compiled regular expression with no nested quantifiers
    # to check if the string represents a valid integer or float.
    pattern = r"^-?\d+(\.\d+)?$"
    return bool(re.match(pattern, number))

