import os
import re
from datetime import datetime

LOG_DIR = os.path.join(".", "Test", "CWE-22_10", "logs")
_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def append_audit_log(log_date, event_text):
    if not isinstance(log_date, str) or not _DATE_RE.fullmatch(log_date):
        raise ValueError("log_date must be in YYYY-MM-DD format")

    try:
        datetime.strptime(log_date, "%Y-%m-%d")
    except ValueError as exc:
        raise ValueError("log_date must be a valid calendar date") from exc

    if not isinstance(event_text, str):
        raise TypeError("event_text must be a string")

    log_dir = os.path.realpath(LOG_DIR)
    os.makedirs(log_dir, exist_ok=True)

    file_path = os.path.realpath(os.path.join(log_dir, f"{log_date}.log"))

    try:
        if os.path.commonpath([log_dir, file_path]) != log_dir:
            raise ValueError("Path traversal attempt detected")
    except ValueError as exc:
        raise ValueError("Path traversal attempt detected") from exc

    with open(file_path, "a", encoding="utf-8") as f:
        f.write(event_text + "\n")

    with open(file_path, "r", encoding="utf-8") as f:
        return sum(1 for _ in f)

