```python
import os
import re
import stat
import errno
from datetime import datetime

LOG_DIR = os.path.join(".", "Test", "CWE-22_10", "logs")
_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def append_audit_log(log_date, event_text):
    if not isinstance(log_date, str) or not _DATE_RE.fullmatch(log_date):
        raise ValueError("log_date must be in YYYY-MM-DD format")

    try:
        datetime.strptime(log_date, "%Y-%m-%d")
    except ValueError as exc:
        raise ValueError("log_date must be a valid calendar date") from exc

    if not isinstance(event_text, str):
        raise TypeError("event_text must be a string")

    log_dir = os.path.realpath(LOG_DIR)
    os.makedirs(log_dir, exist_ok=True)

    file_name = f"{log_date}.log"
    file_path = os.path.join(log_dir, file_name)

    real_file_path = os.path.realpath(file_path)
    try:
        if os.path.commonpath([log_dir, real_file_path]) != log_dir:
            raise ValueError("Path traversal attempt detected")
    except ValueError as exc:
        raise ValueError("Path traversal attempt detected") from exc

    dir_flags = os.O_RDONLY
    if hasattr(os, "O_DIRECTORY"):
        dir_flags |= os.O_DIRECTORY
    if hasattr(os, "O_NOFOLLOW"):
        dir_flags |= os.O_NOFOLLOW

    try:
        dir_fd = os.open(log_dir, dir_flags)
    except OSError as exc:
        if getattr(exc, "errno", None) == errno.ELOOP:
            raise ValueError("Path traversal attempt detected") from exc
        raise

    fd = None
    try:
        flags = os.O_RDWR | os.O_CREAT | os.O_APPEND
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW

        try:
            fd = os.open(file_name, flags, 0o600, dir_fd=dir_fd)
        except OSError as exc:
            if getattr(exc, "errno", None) == errno.ELOOP:
                raise ValueError("Path traversal attempt detected") from exc
            raise

        st = os.fstat(fd)
        if not stat.S_ISREG(st.st_mode):
            raise ValueError("log file is not a regular file")

        with os.fdopen(fd, "a+", encoding="utf-8") as f:
            fd = None
            f.write(event_text + "\n")
            f.seek(0)
            return sum(1 for _ in f)
    finally:
        if fd is not None:
            os.close(fd)
        os.close(dir_fd)
```

