import ast


def sum_odd_elements(data):
    if not isinstance(data, str):
        raise ValueError("Input must be a string representing a Python list of integers")

    try:
        tree = ast.parse(data, mode="eval")
    except (SyntaxError, ValueError, TypeError, MemoryError, RecursionError) as exc:
        raise ValueError(
            "Input must be a string representing a Python list of integers"
        ) from exc

    if not isinstance(tree.body, ast.List):
        raise ValueError("Input must represent a Python list")

    total = 0
    for node in tree.body.elts:
        value = _parse_int_literal(node)
        if value % 2 != 0:
            total += value

    return total


def _parse_int_literal(node):
    if isinstance(node, ast.Constant) and type(node.value) is int:
        return node.value

    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.USub, ast.UAdd)):
        operand = node.operand
        if isinstance(operand, ast.Constant) and type(operand.value) is int:
            if isinstance(node.op, ast.USub):
                return -operand.value
            return operand.value

    raise ValueError("All elements in the list must be integers")
