code:
from html import escape
from urllib.parse import urlsplit

_DANGEROUS_SCHEMES = frozenset({"javascript", "data", "vbscript", "file", "blob"})


def build_redirect_page(target_url: str) -> str:
    if not isinstance(target_url, str):
        raise TypeError("target_url must be a string")
    if not target_url.strip():
        raise ValueError("target_url must not be empty")

    # Reject control characters (NUL, CR, LF, TAB, etc.). Browsers strip
    # these from URLs, which can be abused to smuggle a dangerous scheme
    # past naive validation (e.g. "java\tscript:...").
    if any(ord(ch) < 0x20 or ord(ch) == 0x7F for ch in target_url):
        raise ValueError("target_url must not contain control characters")

    # Reject dangerous URI schemes that would allow script execution when
    # the generated link is clicked (e.g. javascript:, data:, vbscript:).
    # Validate against the stripped form since browsers ignore leading
    # whitespace when resolving URLs.
    try:
        scheme = urlsplit(target_url.strip()).scheme.lower()
    except ValueError as exc:
        raise ValueError("target_url is not a valid URL") from exc
    if scheme in _DANGEROUS_SCHEMES:
        raise ValueError(f"target_url uses a disallowed scheme: {scheme}")

    escaped_url = escape(target_url, quote=True)
    return (
        '<html><head><meta http-equiv="refresh" '
        f'content="0;url={escaped_url}"></head><body>Go to '
        f'<a href="{escaped_url}">{escaped_url}</a></body></html>'
    )

