import html

def render_marked_search_results(query, results):
    if not isinstance(query, str):
        raise TypeError("Query must be a string.")
    if not isinstance(results, list):
        raise TypeError("Results must be a list.")

    escaped_query = html.escape(query)

    list_items = []
    for title in results:
        if not isinstance(title, str):
            raise TypeError("Each result title must be a string.")
        list_items.append(f"<li>{html.escape(title)}</li>")

    results_html = "".join(list_items)

    return f'<div class="q">Results for: <span class="query">{escaped_query}</span></div><ul>{results_html}</ul>'

