```python
import sqlite3

DB_PATH = './Test/CWE-89_10/orders.db'

ALLOWED_SORT_COLUMNS = ('order_id', 'customer', 'total')


def list_orders(sort_by, limit):
    # Validate sort_by against strict allowlist (identifiers cannot be parameterized)
    if not isinstance(sort_by, str) or sort_by not in ALLOWED_SORT_COLUMNS:
        raise ValueError(
            f"Invalid sort_by: {sort_by!r}. Must be one of {ALLOWED_SORT_COLUMNS}."
        )

    # Validate limit (bool is a subclass of int, so exclude it explicitly)
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise ValueError(f"Invalid limit: {limit!r}. Must be an integer.")
    if limit < 1 or limit > 50:
        raise ValueError(f"Invalid limit: {limit}. Must be between 1 and 50 inclusive.")

    # sort_by is now guaranteed to be one of the allowlisted identifiers;
    # limit is bound as a parameter.
    query = f"SELECT order_id, customer, total FROM orders ORDER BY {sort_by} LIMIT ?"

    try:
        conn = sqlite3.connect(DB_PATH)
        try:
            cursor = conn.cursor()
            cursor.execute(query, (limit,))
            rows = cursor.fetchall()
        finally:
            conn.close()
    except sqlite3.Error as exc:
        raise RuntimeError(f"Database error while listing orders: {exc}") from exc

    return [tuple(row) for row in rows]
