import ast
import operator

def evaluate_expression(expression: str) -> float:
    """
    Evaluate a simple arithmetic expression containing digits, whitespace,
    '+', '-', '*', '/', and parentheses.
    Raises a ValueError if the expression is invalid or contains unsupported
    operations.
    """
    # Supported binary operators
    bin_ops = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
    }

    # Supported unary operators
    unary_ops = {
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
    }

    def _eval(node: ast.AST) -> float:
        if isinstance(node, ast.Expression):
            return _eval(node.body)
        if isinstance(node, ast.BinOp):
            left = _eval(node.left)
            right = _eval(node.right)
            op_type = type(node.op)
            if op_type not in bin_ops:
                raise ValueError(f"Unsupported binary operator: {op_type.__name__}")
            return bin_ops[op_type](left, right)
        if isinstance(node, ast.UnaryOp):
            op_type = type(node.op)
            if op_type not in unary_ops:
                raise ValueError(f"Unsupported unary operator: {op_type.__name__}")
            return unary_ops[op_type](_eval(node.operand))
        if isinstance(node, ast.Num):          # For Python < 3.8
            return node.n
        if isinstance(node, ast.Constant):     # For Python >= 3.8
            if isinstance(node.value, (int, float)):
                return node.value
            raise ValueError(f"Unsupported constant type: {type(node.value).__name__}")
        raise ValueError(f"Unsupported expression type: {type(node).__name__}")

    # Parse the expression into an AST
    try:
        parsed = ast.parse(expression, mode="eval")
    except SyntaxError as exc:
        raise ValueError(f"Invalid expression: {expression}") from exc

    # Ensure the AST contains only allowed nodes
    allowed_nodes = {
        ast.Expression, ast.BinOp, ast.UnaryOp, ast.Num, ast.Constant,
        ast.Add, ast.Sub, ast.Mult, ast.Div, ast.UAdd, ast.USub,
        ast.Load, ast.Expr,
    }

    for node in ast.walk(parsed):
        if not isinstance(node, tuple(allowed_nodes)):
            raise ValueError(f"Unsupported syntax element: {type(node).__name__}")

    return _eval(parsed)

