class ExpressionError(ValueError):
    """Raised when an arithmetic expression is invalid."""


def evaluate_expression(expression):
    if not isinstance(expression, str):
        raise TypeError("expression must be a string")

    tokens = _tokenize(expression)
    if not tokens:
        raise ExpressionError("empty expression")

    parser = _ExpressionParser(tokens)
    value = parser.parse()

    if parser.index != len(tokens):
        raise ExpressionError(f"unexpected token {tokens[parser.index][1]!r}")

    if isinstance(value, float) and value.is_integer():
        return int(value)
    return value


def _tokenize(expression):
    tokens = []
    i = 0
    n = len(expression)

    while i < n:
        ch = expression[i]

        if ch.isspace():
            i += 1
            continue

        if ch.isdigit():
            start = i
            while i < n and expression[i].isdigit():
                i += 1
            tokens.append(("number", int(expression[start:i])))
            continue

        if ch in "+-*/()":
            tokens.append(("op", ch))
            i += 1
            continue

        raise ExpressionError(f"invalid character {ch!r} at position {i}")

    return tokens


class _ExpressionParser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.index = 0

    def parse(self):
        return self._parse_expression()

    def _peek(self):
        if self.index >= len(self.tokens):
            return None
        return self.tokens[self.index]

    def _consume(self, expected=None):
        token = self._peek()
        if token is None:
            raise ExpressionError("unexpected end of expression")
        if expected is not None and token[1] != expected:
            raise ExpressionError(f"expected {expected!r}, got {token[1]!r}")
        self.index += 1
        return token

    def _parse_expression(self):
        value = self._parse_term()

        while True:
            token = self._peek()
            if token is not None and token[0] == "op" and token[1] in "+-":
                op = token[1]
                self.index += 1
                right = self._parse_term()
                if op == "+":
                    value += right
                else:
                    value -= right
            else:
                break

        return value

    def _parse_term(self):
        value = self._parse_unary()

        while True:
            token = self._peek()
            if token is not None and token[0] == "op" and token[1] in "*/":
                op = token[1]
                self.index += 1
                right = self._parse_unary()
                if op == "*":
                    value *= right
                else:
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    value /= right
            else:
                break

        return value

    def _parse_unary(self):
        token = self._peek()
        if token is not None and token[0] == "op" and token[1] in "+-":
            op = token[1]
            self.index += 1
            value = self._parse_unary()
            return value if op == "+" else -value

        return self._parse_primary()

    def _parse_primary(self):
        token = self._peek()
        if token is None:
            raise ExpressionError("unexpected end of expression")

        if token[0] == "number":
            self.index += 1
            return token[1]

        if token[0] == "op" and token[1] == "(":
            self.index += 1
            value = self._parse_expression()
            self._consume(")")
            return value

        raise ExpressionError(f"unexpected token {token[1]!r}")

