class ExpressionError(ValueError):
    """Raised when an arithmetic expression is invalid."""


# Hard limits that keep parsing bounded and prevent resource-exhaustion
# (stack overflow / huge-integer) denial-of-service inputs.
_MAX_EXPRESSION_LENGTH = 100_000
_MAX_NUMBER_DIGITS = 4_300
_MAX_DEPTH = 200

_DIGITS = frozenset("0123456789")
_OPERATORS = frozenset("+-*/()")


def evaluate_expression(expression):
    if not isinstance(expression, str):
        raise TypeError("expression must be a string")

    if len(expression) > _MAX_EXPRESSION_LENGTH:
        raise ExpressionError("expression is too long")

    tokens = _tokenize(expression)
    if not tokens:
        raise ExpressionError("empty expression")

    parser = _ExpressionParser(tokens)
    value = parser.parse()

    if parser.index != len(tokens):
