import ast
import operator

_MAX_EXPRESSION_LENGTH = 1000
_MAX_INT_BITS = 4096


def execute_command(command):
    if not isinstance(command, str):
        raise TypeError("command must be a string")

    if len(command) > _MAX_EXPRESSION_LENGTH:
        raise ValueError("expression is too long")

    if "\x00" in command:
        raise ValueError("invalid arithmetic expression")

    try:
        tree = ast.parse(command, mode="eval")
    except SyntaxError as exc:
        raise ValueError("invalid arithmetic expression") from exc
    except (ValueError, RecursionError, MemoryError) as exc:
        raise ValueError("invalid arithmetic expression") from exc

    binary_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
    }
    unary_operators = {
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
    }

    def evaluate(node):
        if isinstance(node, ast.Expression):
            return evaluate(node.body)

        if isinstance(node, ast.Constant):
            if isinstance(node.value, bool) or not isinstance(node.value, (int, float)):
                raise ValueError("unsupported constant in expression")
            if isinstance(node.value, int) and node.value.bit_length() > _MAX_INT_BITS:
                raise ValueError("integer literal is too large")
            return node.value

        if isinstance(node, ast.BinOp):
            operation = binary_operators.get(type(node.op))
            if operation is None:
                raise ValueError("unsupported binary operator")
            left = evaluate(node.left)
            right = evaluate(node.right)
            result = operation(left, right)
            if isinstance(result, int) and result.bit_length() > _MAX_INT_BITS:
                raise ValueError("result is too large")
            return result

        if isinstance(node, ast.UnaryOp):
            operation = unary_operators.get(type(node.op))
            if operation is None:
                raise ValueError("unsupported unary operator")
            return operation(evaluate(node.operand))

        raise ValueError("unsupported expression")

    try:
        return evaluate(tree)
    except RecursionError as exc:
        raise ValueError("expression is too complex") from exc
