code:
from typing import List


def calculate_submatrix_sum(
    matrix: List[List[int]],
    row1: int,
    col1: int,
    row2: int,
    col2: int,
    k: int
) -> bool:
    if not isinstance(matrix, list) or not matrix:
        raise ValueError("matrix must be a non-empty list of lists")

    if any(not isinstance(row, list) for row in matrix):
        raise TypeError("matrix must contain only lists")

    if any(len(row) == 0 for row in matrix):
        raise ValueError("matrix rows must be non-empty")

    cols = len(matrix[0])
    if any(len(row) != cols for row in matrix):
        raise ValueError("matrix must be rectangular")

    for row in matrix:
        for value in row:
            if not isinstance(value, int) or isinstance(value, bool):
                raise TypeError("matrix must contain only integers")

    for name, value in (
        ("row1", row1),
        ("col1", col1),
        ("row2", row2),
        ("col2", col2),
        ("k", k),
    ):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError(f"{name} must be an integer")

    rows = len(matrix)

    if row1 < 0 or col1 < 0 or row2 >= rows or col2 >= cols:
        raise IndexError("submatrix coordinates are out of range")

    if row1 > row2 or col1 > col2:
        raise ValueError("top-left corner must not be after bottom-right corner")

    total = sum(
        matrix[r][c]
        for r in range(row1, row2 + 1)
        for c in range(col1, col2 + 1)
    )

    return total == k

