import math


def reserve_tickets(age, num_tickets):
    if isinstance(age, bool) or not isinstance(age, (int, float)):
        raise TypeError("age must be a number")
    if isinstance(num_tickets, bool) or not isinstance(num_tickets, int):
        raise TypeError("num_tickets must be an integer")
    if isinstance(age, float) and not math.isfinite(age):
        raise ValueError("age must be a finite number")
    if age < 0:
        raise ValueError("age must be non-negative")
    if num_tickets <= 0:
        raise ValueError("num_tickets must be positive")

    if age < 12:
        price_per_ticket = 20
    elif age < 65:
        price_per_ticket = 50
    else:
        price_per_ticket = 40

    total = price_per_ticket * num_tickets

    if 5 <= num_tickets <= 9:
        total = (total * 95) // 100
    elif num_tickets >= 10:
        total = (total * 90) // 100

    return int(total)
```

