import errno
import os


def save_firmware_blob(blob_name, blob_bytes, upload_dir):
    if not isinstance(blob_name, str) or not blob_name.strip():
        raise ValueError("blob_name must be a non-empty string")

    if "\x00" in blob_name:
        raise ValueError("blob_name contains a null byte")

    safe_name = os.path.basename(blob_name.replace("\\", "/"))
    if not safe_name or safe_name in (".", ".."):
        raise ValueError("Invalid blob_name")

    if os.path.splitext(safe_name)[1].lower() != ".bin":
        raise ValueError("blob_name must end with '.bin'")

    if not isinstance(blob_bytes, (bytes, bytearray)):
        raise TypeError("blob_bytes must be bytes or bytearray")

    data = bytes(blob_bytes)
    if len(data) > 256 * 1024:
        raise ValueError("blob_bytes exceeds the 256KB limit")

    if len(data) < 4 or data[:4] != b"FWR1":
        raise ValueError("Invalid firmware magic header (expected 'FWR1')")

    upload_dir_abs = os.path.abspath(upload_dir)
    os.makedirs(upload_dir_abs, exist_ok=True)
    upload_dir_real = os.path.realpath(upload_dir_abs)

    full_path = os.path.join(upload_dir_real, safe_name)
    try:
        if os.path.commonpath([full_path, upload_dir_real]) != upload_dir_real:
            raise ValueError("Path traversal detected")
    except ValueError:
        raise ValueError("Path traversal detected")

    flags = os.O_WRONLY | os.O_CREAT | os.O_TRUNC
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    mode = 0o600

    dir_fd = None
    try:
        use_dir_fd = (
            os.open in getattr(os, "supports_dir_fd", set())
            and hasattr(os, "O_DIRECTORY")
        )
        if use_dir_fd:
            dir_fd = os.open(upload_dir_real, os.O_RDONLY | os.O_DIRECTORY)
            try:
                fd = os.open(safe_name, flags, mode, dir_fd=dir_fd)
            except OSError as exc:
                if getattr(exc, "errno", None) == errno.ELOOP:
                    raise ValueError("Path traversal detected") from exc
                raise
            try:
                with os.fdopen(fd, "wb") as f:
                    fd = None
                    f.write(data)
            finally:
                if fd is not None:
                    os.close(fd)
        else:
            if hasattr(os, "O_NOFOLLOW"):
                try:
                    fd = os.open(full_path, flags, mode)
                except OSError as exc:
                    if getattr(exc, "errno", None) == errno.ELOOP:
                        raise ValueError("Path traversal detected") from exc
                    raise
                try:
                    with os.fdopen(fd, "wb") as f:
                        fd = None
                        f.write(data)
                finally:
                    if fd is not None:
                        os.close(fd)
            else:
                if os.path.islink(full_path):
                    raise ValueError("Path traversal detected")
                with open(full_path, "wb") as f:
                    f.write(data)
    finally:
        if dir_fd is not None:
            os.close(dir_fd)

    return f"Firmware stored at {full_path}"
