import os
import tempfile
from pathlib import Path


def upload_web_template(user_id, file_name, file_content, file_type, base_dir):
    supported_types = {"html", "css"}

    if not isinstance(file_type, str) or file_type.lower() not in supported_types:
        raise ValueError("Unsupported file type. Only 'html' and 'css' are allowed.")
    file_type = file_type.lower()

    if not isinstance(file_name, str) or not file_name.strip():
        raise ValueError("file_name must be a non-empty string.")
    if (
        file_name in {".", ".."}
        or "/" in file_name
        or "\\" in file_name
        or "\x00" in file_name
        or ":" in file_name
        or any(ord(ch) < 32 for ch in file_name)
    ):
        raise ValueError("Invalid file name.")
    if Path(file_name).is_absolute():
        raise ValueError("Invalid file name.")
    if Path(file_name).suffix.lower() != f".{file_type}":
        raise ValueError(f"File name must have a .{file_type} extension.")

    if not isinstance(file_content, (str, bytes)):
        raise TypeError("file_content must be str or bytes.")

    base_path = Path(base_dir).expanduser().resolve()
    base_path.mkdir(parents=True, exist_ok=True)

    if not base_path.is_dir():
        raise NotADirectoryError(f"Base path is not a directory: {base_dir}")

    target = base_path / file_name
    resolved_target = target.resolve(strict=False)
    try:
        resolved_target.relative_to(base_path)
    except ValueError as exc:
        raise ValueError("Resolved file path is outside base_dir.") from exc

    fd, temp_path = tempfile.mkstemp(prefix=".upload-", dir=str(base_path))
    try:
        if isinstance(file_content, bytes):
            file_obj = os.fdopen(fd, "wb")
            fd = None
            with file_obj as f:
                f.write(file_content)
        else:
            file_obj = os.fdopen(fd, "w", encoding="utf-8")
            fd = None
            with file_obj as f:
                f.write(file_content)

        os.replace(temp_path, target)
        temp_path = None
    finally:
        if fd is not None:
            os.close(fd)
        if temp_path is not None:
            try:
                os.unlink(temp_path)
            except FileNotFoundError:
                pass

    return "Web template uploaded successfully."
