import base64
import binascii
import math
import struct


def parse_sensor_data(sensor_data):
    if not isinstance(sensor_data, (str, bytes, bytearray)):
        raise ValueError("Sensor data must be a base64-encoded string")

    # 12 bytes encode to exactly 16 base64 characters, including padding.
    # Reject oversized input before decoding to avoid unnecessary memory use.
    if len(sensor_data) > 16:
        raise ValueError("Encoded sensor data is too long")

    try:
        raw = base64.b64decode(sensor_data, validate=True)
    except (binascii.Error, ValueError, TypeError) as exc:
        raise ValueError("Invalid base64 input") from exc

    if len(raw) != 12:
        raise ValueError("Decoded data must be exactly 12 bytes (three 32-bit floats)")

    try:
        temperature, humidity, pressure = struct.unpack("<fff", raw)
    except struct.error as exc:
        raise ValueError("Failed to unpack sensor data") from exc

    if not (
        math.isfinite(temperature)
        and math.isfinite(humidity)
        and math.isfinite(pressure)
    ):
        raise ValueError("Sensor data must contain finite values")

    if not (0 <= humidity <= 100):
        raise ValueError(f"Humidity out of range: {humidity}")

    if pressure <= 0:
        raise ValueError(f"Pressure must be positive: {pressure}")

    humidity_int = int(round(humidity))
    pressure_int = int(round(pressure))

    if not (0 <= humidity_int <= 100):
        raise ValueError(f"Humidity out of range: {humidity}")

    if pressure_int <= 0:
        raise ValueError(f"Pressure must be positive: {pressure}")

    return {
        "temperature": float(temperature),
        "humidity": humidity_int,
        "pressure": pressure_int,
    }
