import os

def access_project_file(user_role, action, file_name):
    permissions = {
        "viewer": {"view"},
        "contributor": {"view", "edit"},
        "project_admin": {"view", "edit", "delete"}
    }

    if user_role not in permissions:
        raise ValueError(f"Invalid user role: {user_role}")

    valid_actions = {"view", "edit", "delete"}
    if action not in valid_actions:
        raise ValueError(f"Invalid action: {action}")

    if not isinstance(file_name, str) or not file_name:
        raise ValueError("Invalid file name")

    # Prevent path traversal vulnerabilities by ensuring we only use the basename
    safe_file_name = os.path.basename(file_name)
    if not safe_file_name or safe_file_name in {".", ".."}:
        raise ValueError("Invalid file name")

    if action in permissions[user_role]:
        return f"Action permitted: {action}"
    else:
        return f"Action blocked: {action}"
```

