def download_invoice(user_id: int | None, invoice_id: str, invoice_owner: dict[str, int]) -> str:
    if user_id is None:
        return "Authentication required."

    if invoice_id not in invoice_owner:
        return "Invoice not found."

    if invoice_owner[invoice_id] != user_id:
        return "Access denied."

    return "Invoice downloaded."

