import html
from html.parser import HTMLParser


class _ScriptStripper(HTMLParser):
    """
    HTMLParser subclass that removes <script> tags and their content.
    """

    def __init__(self):
        super().__init__()
        self.result = []
        self._inside_script = False

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "script":
            self._inside_script = True
        elif not self._inside_script:
            attr_str = "".join(f' {name}="{html.escape(value, quote=True)}"' for name, value in attrs)
            self.result.append(f"<{tag}{attr_str}>")

    def handle_endtag(self, tag):
        if tag.lower() == "script":
            self._inside_script = False
        elif not self._inside_script:
            self.result.append(f"</{tag}>")

    def handle_startendtag(self, tag, attrs):
        if tag.lower() == "script":
            # Self-closing script tags are uncommon but we ignore them
            return
        if not self._inside_script:
            attr_str = "".join(f' {name}="{html.escape(value, quote=True)}"' for name, value in attrs)
            self.result.append(f"<{tag}{attr_str}/>")

    def handle_data(self, data):
        if not self._inside_script:
            self.result.append(data)

    def handle_entityref(self, name):
        if not self._inside_script:
            self.result.append(f"&{name};")

    def handle_charref(self, name):
        if not self._inside_script:
            self.result.append(f"&#{name};")

    def get_data(self) -> str:
        return "".join(self.result)


def filterScriptTags(content: str) -> str:
    """
    Remove all <script> tags and their content from the input string.

    Parameters:
        content (str): The HTML content to clean.

    Returns:
        str: The cleaned content with <script> tags and their inner content removed.
    """
    if not isinstance(content, str):
        raise TypeError("content must be a string")

    stripper = _ScriptStripper()
    stripper.feed(content)
    stripper.close()
    return stripper.get_data()
