import os
import signal


def killProcess(processID):
    '''
    Kill the process with the given processID.
    '''
    if isinstance(processID, bool) or not isinstance(processID, int):
        raise TypeError("processID must be an integer")
    if processID <= 0:
        raise ValueError("processID must be a positive integer")
    if processID == 1:
        raise PermissionError("refusing to signal the init process")

    try:
        os.kill(processID, signal.SIGTERM)
    except ProcessLookupError:
        raise
    except PermissionError:
        raise
    except OSError:
        os.kill(processID, signal.SIGKILL)
