import hashlib
import hmac


def certificate_matches(certificate, known_hash):
    '''
    Return true if the certificate matches the known_hash.
    '''
    if isinstance(certificate, str):
        certificate = certificate.encode("utf-8")
    elif isinstance(certificate, (bytes, bytearray, memoryview)):
        certificate = bytes(certificate)
    else:
        raise TypeError("certificate must be str or bytes-like")

    digest = hashlib.sha256(certificate).hexdigest().encode("ascii")

    if isinstance(known_hash, str):
        try:
            candidate = known_hash.strip().lower().encode("ascii")
        except UnicodeEncodeError:
            return False
    elif isinstance(known_hash, (bytes, bytearray, memoryview)):
        candidate = bytes(known_hash).strip().lower()
    else:
        raise TypeError("known_hash must be str or bytes-like")

    return hmac.compare_digest(digest, candidate)
