import os
import stat

# Directory that readFile is allowed to serve files from.
# Any path that resolves outside this directory is rejected.
_ALLOWED_BASE_DIR = os.path.realpath(os.path.dirname(os.path.abspath(__file__)))

# Upper bound on the size of a file that will be read, to avoid DoS.
_MAX_FILE_SIZE = 10 * 1024 * 1024  # 10 MiB


def readFile(fileName):
    '''
    Check if the file passed as argument exists,
    then read the file and return its content.
    '''
    # Normalise the incoming argument without trusting its type.
    try:
        requested = os.fspath(fileName)
    except TypeError:
        return None

    # Canonicalise the path (resolves '..', symlinks, etc.).
    try:
        resolved = os.path.realpath(requested)
    except (OSError, ValueError, TypeError):
        return None

    # Reject anything that escapes the allowed base directory
    # (path traversal / symlink escape).
    try:
        if os.path.commonpath([_ALLOWED_BASE_DIR, resolved]) != _ALLOWED_BASE_DIR:
            return None
    except (ValueError, TypeError):
        return None

    flags = os.O_RDONLY
    flags |= getattr(os, "O_NOFOLLOW", 0)
    flags |= getattr(os, "O_CLOEXEC", 0)

    # Open directly instead of a check-then-open (avoids TOCTOU races).
    try:
        fd = os.open(resolved, flags)
    except OSError:
        # Covers FileNotFoundError, NotADirectoryError, ELOOP, EACCES, ...
        return None

    try:
        st = os.fstat(fd)
        is_regular = stat.S_ISREG(st.st_mode)
        size_ok = st.st_size <= _MAX_FILE_SIZE
    except OSError:
        is_regular = False
        size_ok = False

    if not (is_regular and size_ok):
        try:
            os.close(fd)
        except OSError:
            pass
        return None

    try:
        f = os.fdopen(fd, "r")
    except OSError:
        try:
            os.close(fd)
        except OSError:
            pass
        return None

    with f:
        return f.read()
