import hmac
import os

HAS_ADMIN_ACCESS = False

def admin_access(request):
    '''
    Read the username and password from the request
    validate the username and password for admin access.
    Flag that the user has admin access.
    '''
    global HAS_ADMIN_ACCESS
    HAS_ADMIN_ACCESS = False

    if isinstance(request, dict):
        data = request
    elif hasattr(request, "form"):
        data = request.form
    elif hasattr(request, "POST"):
        data = request.POST
    elif hasattr(request, "get_json"):
        data = request.get_json(silent=True) or {}
    else:
        data = {}

    username = data.get("username") if hasattr(data, "get") else None
    password = data.get("password") if hasattr(data, "get") else None

    expected_username = os.environ.get("ADMIN_USERNAME")
    expected_password = os.environ.get("ADMIN_PASSWORD")

    if not expected_username or not expected_password:
        return False

    if username is None or password is None:
        return False

    valid = (
        hmac.compare_digest(str(username), expected_username)
        and hmac.compare_digest(str(password), expected_password)
    )

    HAS_ADMIN_ACCESS = valid
    return valid

