import hmac
import os

HAS_ADMIN_ACCESS = False

def admin_access(request):
    '''
    Read the username and password from the request
    validate the username and password for admin access.
    Flag that the user has admin access.
    '''
    global HAS_ADMIN_ACCESS
    HAS_ADMIN_ACCESS = False

    if isinstance(request, dict):
        data = request
    elif hasattr(request, "form"):
        data = request.form
    elif hasattr(request, "POST"):
        data = request.POST
    elif hasattr(request, "get_json"):
        try:
            data = request.get_json(silent=True) or {}
        except Exception:
            data = {}
    else:
        data = {}

    if not hasattr(data, "get"):
        return False

    username = data.get("username")
    password = data.get("password")

    expected_username = os.environ.get("ADMIN_USERNAME")
    expected_password = os.environ.get("ADMIN_PASSWORD")

    if not expected_username or not expected_password:
        return False

    if username is None or password is None:
        return False

    try:
        username_bytes = str(username).encode("utf-8")
        password_bytes = str(password).encode("utf-8")
        expected_username_bytes = expected_username.encode("utf-8")
        expected_password_bytes = expected_password.encode("utf-8")
    except Exception:
        return False

    valid = (
        hmac.compare_digest(username_bytes, expected_username_bytes)
        and hmac.compare_digest(password_bytes, expected_password_bytes)
    )

    HAS_ADMIN_ACCESS = valid
    return valid
