import io
import pickle


class _RestrictedUnpickler(pickle.Unpickler):
    '''
    An Unpickler that only resolves a small allow-list of harmless,
    non-executable globals, preventing arbitrary code execution via
    crafted pickle payloads (e.g. __reduce__ returning os.system).
    '''

    _SAFE_BUILTINS = frozenset({
        "list", "dict", "set", "frozenset", "tuple", "str", "bytes",
        "bytearray", "int", "float", "complex", "bool", "NoneType",
        "object", "slice", "range",
    })

    _SAFE_COLLECTIONS = frozenset({
        "OrderedDict", "defaultdict", "deque", "Counter",
    })

    def find_class(self, module, name):
        if module == "builtins" and name in self._SAFE_BUILTINS:
            return super().find_class(module, name)
        if module == "collections" and name in self._SAFE_COLLECTIONS:
            return super().find_class(module, name)
        raise pickle.UnpicklingError(
            "forbidden global '%s.%s' encountered while unpickling"
            % (module, name)
        )


def getPickleData(pickled):
    '''
    Return deserialized data
    '''
    if isinstance(pickled, (bytearray, memoryview)):
        pickled = bytes(pickled)
    return _RestrictedUnpickler(io.BytesIO(pickled)).load()
