from django.core.exceptions import ImproperlyConfigured

BASE_DIR = Path(__file__).resolve().parent.parent

# Allow-list of database backends. Django imports the module named in ENGINE,
# so an attacker who can influence DJANGO_DB_ENGINE could otherwise force an
# arbitrary module import / code path. Restrict it to known-safe backends.
ALLOWED_DB_ENGINES = frozenset(
    {
        "django.db.backends.sqlite3",
        "django.db.backends.postgresql",
        "django.db.backends.postgresql_psycopg2",
        "django.db.backends.mysql",
        "django.db.backends.oracle",
    }
)

