from django.http import HttpResponseRedirect, HttpResponseBadRequest
from django.utils.http import url_has_allowed_host_and_scheme
from django.conf import settings


def set_location_header(request):
    """
    Retrieve the "next" parameter from the request and redirect to that URL
    by setting the `Location` header explicitly, ensuring the URL is safe.
    """
    # Look for the "next" parameter in GET or POST data
    next_url = request.GET.get("next") or request.POST.get("next")

    if not next_url:
        # If no "next" value is provided, return a 400 Bad Request response
        return HttpResponseBadRequest("Missing 'next' parameter")

    # Ensure the URL is safe to redirect to (prevent open redirects)
    allowed_hosts = {request.get_host(), *settings.ALLOWED_HOSTS}
    if not url_has_allowed_host_and_scheme(
        url=next_url, allowed_hosts=allowed_hosts, require_https=request.is_secure()
    ):
        return HttpResponseBadRequest("Unsafe redirect URL")

    # Use Django's HttpResponseRedirect to set the Location header
    return HttpResponseRedirect(next_url)
