import socket as socket_module
from socket import socket


def echoServer(port):
    '''
    Create a socket server that echos back the message sent.
    '''
    with socket(socket_module.AF_INET, socket_module.SOCK_STREAM) as server_socket:
        server_socket.setsockopt(socket_module.SOL_SOCKET, socket_module.SO_REUSEADDR, 1)
        server_socket.bind(('', port))
        server_socket.listen()

        while True:
            try:
                connection, _ = server_socket.accept()
            except OSError:
                continue

            with connection:
                connection.settimeout(30)
                try:
                    while True:
                        data = connection.recv(4096)
                        if not data:
                            break
                        connection.sendall(data)
                except (socket_module.timeout, ConnectionError, OSError):
                    continue

