import sys

def convert_to_int():
    """
    Continuously prompt the user for input until a valid integer is entered.
    Handles EOFError gracefully by returning None.
    Returns the integer value entered by the user or None if input is terminated.
    """
    while True:
        try:
            user_input = input("Enter an integer: ")
        except EOFError:
            print("EOF received. Exiting.", file=sys.stderr)
            return None

        try:
            result = int(user_input)
            return result
        except ValueError:
            print(f"'{user_input}' is not a valid integer. Please try again.", file=sys.stderr)
